def make_vinnie_se_heart_special(first_color: int, second_color: int) -> int:
    pair = tuple(sorted((int(first_color), int(second_color))))
    if pair not in VINNIE_SE_HEART_COLOR_PAIRS:
        raise ValueError(f"Unsupported Vinnie SE heart color pair: {pair}")
    return SPECIAL_VINNIE_SE_HEART_BASE + VINNIE_SE_HEART_COLOR_PAIRS.index(pair)


def is_vinnie_se_heart_special(special: int) -> bool:
    return SPECIAL_VINNIE_SE_HEART_BASE <= int(special) <= SPECIAL_VINNIE_SE_HEART_MAX


def _is_heart_special(special: int) -> bool:
    """True for any Vinnie heart -- the plain one-colour heart and the pair.

    Hearts are immune to another heart's colour wipe.  The 2026-08-22 captures
    show it in both directions: a plain heart wiping yellow left the two
    yellow/red pair hearts on the bottom row untouched, and a pair heart wiping
    its colours left a plain heart of that colour standing.  A heart still fires
    when it is matched or when a line/bomb special physically hits its cell.
    """
    return int(special) == SPECIAL_HEART or is_vinnie_se_heart_special(special)


def vinnie_se_heart_colors(special: int) -> tuple[int, int]:
    if not is_vinnie_se_heart_special(special):
        raise ValueError(f"Not a Vinnie SE heart special: {special}")
    return VINNIE_SE_HEART_COLOR_PAIRS[int(special) - SPECIAL_VINNIE_SE_HEART_BASE]


def is_red_blue_tile_special(special: int) -> bool:
    return int(special) == SPECIAL_RED_BLUE_TILE


def red_blue_tile_colors(_special: int = SPECIAL_RED_BLUE_TILE) -> tuple[int, int]:
    return RED_BLUE_TILE_COLORS


def _special_match_colors(special: int) -> tuple[int, ...]:
    if is_vinnie_se_heart_special(special):
        return vinnie_se_heart_colors(special)
    if is_red_blue_tile_special(special):
        return red_blue_tile_colors(special)
    return ()


def _is_color_flexible_special(special: int) -> bool:
    return bool(_special_match_colors(special))
