    cleo_scenario_weights: tuple[float, ...] = ()
    cleo_scenario_colors: tuple[int, ...] = ()
    cleo_scenario_scores: tuple[float, ...] = ()
    # Per-colour predicted extras (same order as cleo_scenario_colors), for the
