    # _banked_charge_priority.
    mixy_banked_charge_cells: float = 0.0
    destroyed_extra_candidates: int = 0
    preserved_extra_candidates: int = 0
    extra_preservation_penalty: float = 0.0
    decision_gate: str = DECISION_GATE_UNKNOWN
    # Set by the Cleo tier: this Cleo swap may go before a ready booster
