    froggy_lotus_charge_cells: float = 0.0
    froggy_lotus_charge_value: float = 0.0
    # True when the simulation itself fired the lotus, so `cleared_cells` and
    # `blue_cells` already hold the gathered cluster. `rank_froggy_lotus_moves`
    # reads this to keep its ranking bonus without counting the tiles twice.
    froggy_lotus_gathered: bool = False
    # See SimulationResult.has_direct_match_layer.
    has_direct_match_layer: bool = True
    cleared_color_counts: dict[int, float] = field(default_factory=dict)
    floor_lava_destroyed_columns: tuple[int, ...] = ()
    floor_lava_checked_columns_after: tuple[int, ...] = ()
    score_strategy: str = SCORE_STRATEGY_NORMAL
