def as_board_array(grid, *, copy: bool = False) -> np.ndarray:
    if isinstance(grid, np.ndarray):
        if grid.dtype == np.int16:
            return grid.copy() if copy else grid
        return grid.astype(np.int16, copy=True)
    return np.array(grid, dtype=np.int16, copy=True)


def clone_grid(grid) -> np.ndarray:
    return as_board_array(grid, copy=True)


def grid_to_lists(grid) -> list[list[int]]:
    return as_board_array(grid).astype(int, copy=False).tolist()


def _is_board_piece(value: int) -> bool:
    return value > EMPTY


# Board values that occupy a cell and can be swapped, but never form a line of
# their own. The disco ball is activated by swapping, never matched. The chest
# is an obstacle: it can be pushed around, but three chests in a row are not a
# match -- it only leaves the board by falling out of the bottom row.
NON_MATCHABLE_PIECES = (DISCO_BALL, CHEST)


def _is_matchable_piece(value: int) -> bool:
    return _is_board_piece(value) and value not in NON_MATCHABLE_PIECES


def _matchable_mask(board_array: np.ndarray) -> np.ndarray:
    """Cells whose colour can take part in a line/square match."""
    mask = board_array > EMPTY
    for value in NON_MATCHABLE_PIECES:
        mask &= board_array != value
    return mask


def _is_normal_color(value: int) -> bool:
    return BLUE <= value <= WHITE


def _is_high_voltage_color(value: int) -> bool:
    return BLUE <= value <= ORANGE


def _is_magic_wand_color(value: int) -> bool:
    return BLUE <= value <= ORANGE


def _is_woolly_workout_color(value: int) -> bool:
    return value in WOOLLY_WORKOUT_TARGET_COLORS


def _movable_specials_and_xtra_mask(special_grid) -> tuple[np.ndarray, np.ndarray]:
    specials = as_board_array(special_grid, copy=True)
    xtra_mask = specials == SPECIAL_XTRA_MOVE_TILE
    specials[xtra_mask] = EMPTY
    return specials, xtra_mask


def _restore_xtra_markers(special_grid, xtra_mask: np.ndarray) -> np.ndarray:
    restored = as_board_array(special_grid, copy=True)
    restored[xtra_mask & (restored == EMPTY)] = SPECIAL_XTRA_MOVE_TILE
    return restored


JOOJOO_SKULL_DIRECTIONS = {
    BLUE: ((0, -1), (0, 1), (-1, 0), (1, 0)),
    PURPLE: ((0, -1), (0, 1), (-1, 0), (1, 0)),
    RED: ((0, -1), (0, 1), (-1, 0), (1, 0)),
    GREEN: ((-1, -1), (-1, 1), (1, -1), (1, 1)),
    YELLOW: ((-1, -1), (-1, 1), (1, 0)),
    ORANGE: ((-1, 0), (1, -1), (1, 1)),
}


def _can_swap_cell(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
) -> bool:
    special = special_board[row][col]
    if special in {SPECIAL_FROGGY_LOTUS, SPECIAL_BILLIE_DRONE}:
        # Both ride on a BLOCKED (-1) board cell, so _is_board_piece is False
        # for them, yet they can still be swapped with an adjacent tile: the
        # tile sliding into their old cell may complete a line. Allow the swap
        # here unconditionally; the downstream match filter keeps only the
        # candidate that actually forms a match (and the lotus then collects it,
        # since its original zone overlaps that match).
        return True
    return _is_board_piece(board[row][col]) and special not in {
        SPECIAL_SPRAY_SE,
        SPECIAL_SWEEP_SE_BROOM,
    }


def _can_swap_pair(
    board: list[list[int]],
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    # A Joo Joo skull rides on a normal coloured tile and drags like any other
    # piece: swapping it into a run makes that run match (and detonates the
    # skull along its colour's rays).  Joining two adjacent skulls is the
    # booster's dedicated activation gesture and goes through the same check.
    return _can_swap_cell(board, special_board, *start) and _can_swap_cell(board, special_board, *target)


def _is_joojoo_skull_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    return (
        special_board[start[0]][start[1]] == SPECIAL_JOOJOO_SKULL
        and special_board[target[0]][target[1]] == SPECIAL_JOOJOO_SKULL
    )


def _is_bomb_bomb_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    return (
        special_board[start[0]][start[1]] == SPECIAL_BOMB
        and special_board[target[0]][target[1]] == SPECIAL_BOMB
    )


def _is_special_combo_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    """Two specials that combine when one is swiped onto the other.

    Mirrors _candidate_activates_special_swap's exclusions, minus the mode-only
    fireworks rule the candidate generator cannot see; emitting one extra
    ordinary-swap candidate there is harmless.
    """
    first = special_board[start[0]][start[1]]
    second = special_board[target[0]][target[1]]
    if first in ZANY_ZAPPER_SPECIALS or second in ZANY_ZAPPER_SPECIALS:
        return False
    if first in DIRECTIONAL_FIREWORK_SPECIALS or second in DIRECTIONAL_FIREWORK_SPECIALS:
        return False
    return _is_activatable_special(first) and _is_activatable_special(second)


def _is_directional_special_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    """Pairs where swiping A onto B differs from swiping B onto A.

    Every two-special combo belongs here. The piece you drag is the one that
    lands on the other's cell, so it is the one that can complete a colour match
    there -- swipe the green lightning onto the bomb and the greens around the
    bomb make a four; swipe the bomb onto the lightning and they do not. Only
    joojoo and bomb+bomb used to be emitted both ways, so for every other pair
    the bot could only ever play the generator's left/upward orientation and had
    no way to reach the good one.
    """
    return (
        _is_joojoo_skull_pair(special_board, start, target)
        or _is_bomb_bomb_pair(special_board, start, target)
        or _is_special_combo_pair(special_board, start, target)
        or _is_disco_colour_pair(special_board, start, target)
        or _is_cleo_colour_pair(special_board, start, target)
    )


def _is_cleo_colour_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    """A Cleo next to something else: dragging Cleo and dragging the tile differ.

    The dragged piece's starting cell is left empty and the swipe's end cell
    holds the partner colour (player, 2026-09-15) -- see
    _simulate_cleo_candidate. So the recolour matches form around different
    cells depending on which piece is dragged.
    """
    return (
        special_board[start[0]][start[1]] == SPECIAL_CLEO_BUG
    ) != (
        special_board[target[0]][target[1]] == SPECIAL_CLEO_BUG
    )


def _is_disco_colour_pair(
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    """A Brocco disco next to something else -- two different moves, not one.

    Dragging the ball onto a tile fires it and wipes that tile's colour.
    Dragging a tile onto a resting ball does not fire anything: the two pieces
    simply change places, and if the tile that lands completes a run, that run
    matches like any other -- extra move included. The engine spells the
    asymmetry out (see `_candidate_drags_the_disco`), so both swipes have to
    exist as candidates for the evaluator to choose between them.
    """
    return (
        special_board[start[0]][start[1]] == SPECIAL_DISCO_BALL
    ) != (
        special_board[target[0]][target[1]] == SPECIAL_DISCO_BALL
    )


def swap_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> tuple[list[list[int]], list[list[int]]]:
    swapped_board = clone_grid(board)
    swapped_special, xtra_mask = _movable_specials_and_xtra_mask(special_board)
    r1, c1 = start
    r2, c2 = target
    swapped_board[r1][c1], swapped_board[r2][c2] = swapped_board[r2][c2], swapped_board[r1][c1]
    swapped_special[r1][c1], swapped_special[r2][c2] = swapped_special[r2][c2], swapped_special[r1][c1]
    swapped_special = _restore_xtra_markers(swapped_special, xtra_mask)
    return swapped_board, swapped_special


def _cell_in_direct_match(board: list[list[int]], cell: tuple[int, int]) -> bool:
    """Whether ``cell`` sits in a run of three (or a 2x2 square) of its colour."""
    size = len(board)
    row, col = cell
    color = board[row][col]
    if not _is_normal_color(color):
        return False
    for d_row, d_col in ((0, 1), (1, 0)):
        run = 1
        for sign in (1, -1):
            n_row, n_col = row + sign * d_row, col + sign * d_col
            while 0 <= n_row < size and 0 <= n_col < size and board[n_row][n_col] == color:
                run += 1
                n_row += sign * d_row
                n_col += sign * d_col
        if run >= 3:
            return True
    for d_row in (-1, 0):
        for d_col in (-1, 0):
            top, left = row + d_row, col + d_col
            if 0 <= top < size - 1 and 0 <= left < size - 1 and all(
                board[top + i][left + j] == color for i in (0, 1) for j in (0, 1)
            ):
                return True
    return False


def _is_lotus_two_colour_swap(
    swapped_board: list[list[int]],
    start: tuple[int, int],
    target: tuple[int, int],
) -> bool:
    """A plain swap on a lotus board that makes a match at BOTH ends.

    The game credits the swap to the tile you drag, and that is the match a
    lotus fires on (see "Swipe orientation" below). When only one end matches,
    the orientation is settled afterwards by `oriented_swap_candidate` and one
    candidate is enough. When both ends match in different colours and both
    reach a lotus, the two swipes are different moves -- one collects the first
    colour, the other the second -- and the ranking can only pick the better
    collect if it is shown both. 2026-09-19 01:43:21: orange at (5,3) over
    purple at (6,3), both matches touching the lotus at (5,4); only the
    orange-dragged swipe existed, so eight oranges at 3 were collected where
    nine purples at 4 were on offer for the other swipe.
    """
    first = swapped_board[start[0]][start[1]]
    second = swapped_board[target[0]][target[1]]
    if first == second:
        return False
    return _cell_in_direct_match(swapped_board, start) and _cell_in_direct_match(
        swapped_board, target
    )


def _line_lengths_through(rows: list[list[int]], row: int, col: int) -> tuple[int, int]:
    """Equal values in a row and in a column through a cell, the cell included."""
    size = len(rows)
    values = rows[row]
    color = values[col]
    left = col
    while left > 0 and values[left - 1] == color:
        left -= 1
    right = col
    while right + 1 < size and values[right + 1] == color:
        right += 1
    top = row
    while top > 0 and rows[top - 1][col] == color:
        top -= 1
    bottom = row
    while bottom + 1 < size and rows[bottom + 1][col] == color:
        bottom += 1
    return right - left + 1, bottom - top + 1


def _swap_makes_a_line(rows: list[list[int]], start: tuple[int, int], target: tuple[int, int]) -> bool:
    """Whether swapping two cells leaves a line of three through either of them."""
    (r1, c1), (r2, c2) = start, target
    rows[r1][c1], rows[r2][c2] = rows[r2][c2], rows[r1][c1]
    found = max(_line_lengths_through(rows, r1, c1)) >= 3 or max(_line_lengths_through(rows, r2, c2)) >= 3
    rows[r1][c1], rows[r2][c2] = rows[r2][c2], rows[r1][c1]
    return found


def generate_candidates(
    board: list[list[int]],
    special_board: list[list[int]],
    skip_plain_without_line: bool = False,
) -> list[MoveCandidate]:
    """Every swap to try. ``skip_plain_without_line`` leaves out two plain colours
    that form no line: they match nothing, and they were about 92% of the search."""
    check_planning_cancelled()
    candidates = []
    size = len(board)
    rows = as_board_array(board).tolist() if skip_plain_without_line else None

    def skipped(start, target):
        return (
            rows is not None
            and special_board[start[0]][start[1]] == EMPTY
            and special_board[target[0]][target[1]] == EMPTY
            and _is_normal_color(rows[start[0]][start[1]])
            and _is_normal_color(rows[target[0]][target[1]])
            and not _swap_makes_a_line(rows, start, target)
        )

    lotus_on_board = any(
        value == SPECIAL_FROGGY_LOTUS for values in special_board for value in values
    )
    for row in range(size):
        for col in range(size):
            if special_board[row][col] == SPECIAL_SPRAY_SE:
                for direction in (
                    Direction.LEFT,
                    Direction.RIGHT,
                    Direction.UP,
                    Direction.DOWN,
                ):
                    candidates.append(
                        MoveCandidate(
                            (row, col),
                            (row, col),
                            direction,
                            clone_grid(board),
                            clone_grid(special_board),
                        )
                    )
            if special_board[row][col] == SPECIAL_SWEEP_SE_BROOM:
                # The broom is activated by swiping it onto an adjacent plain
                # colour; that colour becomes the sweep target. Emit one
                # candidate per swipe direction whose neighbour is a plain tile
                # so the evaluator can score every (colour, direction) pairing
                # and keep only the worthwhile sweeps.
                for direction in (
                    Direction.LEFT,
                    Direction.RIGHT,
                    Direction.UP,
                    Direction.DOWN,
                ):
                    row_step, col_step = DIRECTION_STEPS[direction]
                    neighbor_row, neighbor_col = row + row_step, col + col_step
                    if (
                        0 <= neighbor_row < size
                        and 0 <= neighbor_col < size
                        and _is_normal_color(board[neighbor_row][neighbor_col])
                        and special_board[neighbor_row][neighbor_col] == EMPTY
                    ):
                        candidates.append(
                            MoveCandidate(
                                (row, col),
                                (neighbor_row, neighbor_col),
                                direction,
                                clone_grid(board),
                                clone_grid(special_board),
                            )
                        )
            if col + 1 < size and not skipped((row, col), (row, col + 1)):
                if _can_swap_pair(board, special_board, (row, col), (row, col + 1)):
                    swapped_board, swapped_special = swap_cells(board, special_board, (row, col), (row, col + 1))
                    candidates.append(
                        MoveCandidate((row, col), (row, col + 1), Direction.RIGHT, swapped_board, swapped_special)
                    )
                    if _is_directional_special_pair(special_board, (row, col), (row, col + 1)) or (
                        lotus_on_board
                        and _is_lotus_two_colour_swap(swapped_board, (row, col), (row, col + 1))
                    ):
                        candidates.append(
                            MoveCandidate((row, col + 1), (row, col), Direction.LEFT, swapped_board, swapped_special)
                        )
            if row + 1 < size and not skipped((row, col), (row + 1, col)):
                if _can_swap_pair(board, special_board, (row, col), (row + 1, col)):
                    swapped_board, swapped_special = swap_cells(board, special_board, (row, col), (row + 1, col))
                    candidates.append(
                        MoveCandidate((row, col), (row + 1, col), Direction.DOWN, swapped_board, swapped_special)
                    )
                    if _is_directional_special_pair(special_board, (row, col), (row + 1, col)) or (
                        lotus_on_board
                        and _is_lotus_two_colour_swap(swapped_board, (row, col), (row + 1, col))
                    ):
                        candidates.append(
                            MoveCandidate((row + 1, col), (row, col), Direction.UP, swapped_board, swapped_special)
                        )
    return candidates


# --- Swipe orientation -------------------------------------------------------
# The game credits a swap to the tile you DRAG: the one that leaves its cell and
# lands on the other's. That tile's colour is the match the game treats as
# "the move you made", which is what Froggy Fu fires its lotus on, what the
# Jelly SE zone repaints itself to, and what a Mixy code reads.
# `_is_directional_special_pair` already documents the rule for special pairs
# and emits those both ways.
#
# Plain colour swaps are emitted in ONE orientation only (`generate_candidates`
# always drags the left/upper tile) because both orientations land the identical
# board -- and for an ordinary match they really are the same move. They are not
# the same move for the boosters above: with a blue match and a green match both
# available on the same pair, dragging the green tile tells the game the move
# was green. That is the "sometimes backwards" swipe -- the ranking chose the
# blue collect and the generator's fixed orientation played it as green.
#
# So the orientation is decided at the end, on the move actually being played:
# the tile whose colour the ranking picked is the tile that gets dragged. The
# board result is unchanged either way, which is why this can be a pure
# re-labelling of the same swipe rather than a second candidate through the
# whole search.
OPPOSITE_DIRECTIONS = {
    Direction.RIGHT: Direction.LEFT,
    Direction.LEFT: Direction.RIGHT,
    Direction.DOWN: Direction.UP,
    Direction.UP: Direction.DOWN,
}


def _is_plain_swap_candidate(candidate: MoveCandidate) -> bool:
    """Whether this candidate is an ordinary two-tile swap, safe to re-orient.

    Match-triggered specials still make ordinary colour swaps. Only explicit
    activations and directional combos must keep their evaluated orientation.
    """
    if candidate.start == candidate.target:
        return False
    (start_row, start_col), (target_row, target_col) = candidate.start, candidate.target
    if abs(start_row - target_row) + abs(start_col - target_col) != 1:
        return False
    endpoint_specials = {
        candidate.special_board[start_row][start_col],
        candidate.special_board[target_row][target_col],
    }
    if endpoint_specials & {
        SPECIAL_DISCO_BALL, SPECIAL_CLEO_BUG,
        SPECIAL_SPRAY_SE, SPECIAL_SWEEP_SE_BROOM,
    }:
        return False
    return not _is_directional_special_pair(
        candidate.special_board, candidate.start, candidate.target
    )


def flip_swap_candidate(candidate: MoveCandidate) -> MoveCandidate:
    """The same swap, dragged from the other end.

    ``candidate.board`` is already the post-swap board, and swapping A with B is
    the same exchange as swapping B with A, so the resulting board and every
    simulation built on it stay valid untouched. Only the swipe changes.
    """
    return MoveCandidate(
        start=candidate.target,
        target=candidate.start,
        direction=OPPOSITE_DIRECTIONS[Direction(candidate.direction)],
        board=candidate.board,
        special_board=candidate.special_board,
    )


def _swapped_colors(candidate: MoveCandidate) -> tuple[int, int]:
    """(dragged colour, displaced colour) for a plain swap.

    Read off the post-swap board: the dragged tile is the one now sitting on
    ``target``, the displaced one is what got pushed back to ``start``.
    """
    return (
        candidate.board[candidate.target[0]][candidate.target[1]],
        candidate.board[candidate.start[0]][candidate.start[1]],
    )


def intended_swap_color(evaluation: "MoveEvaluation") -> int | None:
    """Choose a tile that lands in its own direct match.

    Endpoint membership matters: a remote match or a later cascade of the
    same colour must never make us drag a tile away from the actual match.
    With two matches, respect explicit colour intent. Otherwise both endpoints
    are valid destinations, so keep the direction used by the simulation.
    """
    cascades = evaluation.cascade_matches or ()
    if not cascades:
        return None
    candidate = evaluation.candidate
    dragged, displaced = _swapped_colors(candidate)
    # A simulated lotus gather REPLACES the trigger match in the first cascade
    # with the gathered blob, which sits around the lotus and need not contain
    # either swapped cell. The colour the lotus fired on is still the colour of
    # the tile that made the match, so it stands in for the missing match here.
    # Without this every lotus move whose endpoint fell outside the blob read as
    # "no intent" and was swiped from the generator's fixed left/upper end --
    # a counter swipe whenever the matching tile was the right/lower one (22 of
    # 131 lotus moves recorded 2026-09-18/19, e.g. 22:38:49 red dragged down
    # onto the blue that made the match).
    gathered_colors = {
        int(event["color"])
        for event in evaluation.intent_events or ()
        if event.get("type") == FROGGY_LOTUS_GATHER_EVENT and "color" in event
    }
    landed_matches = {}
    for color, cell in ((dragged, candidate.target), (displaced, candidate.start)):
        cells = set()
        for match in cascades[0]:
            if match.color == color and cell in match.cells:
                cells.update(match.cells)
        if cells:
            landed_matches[int(color)] = len(cells)
        elif int(color) in gathered_colors:
            landed_matches[int(color)] = 1
    if not landed_matches:
        return None
    if len(landed_matches) == 1:
        return next(iter(landed_matches))
    preferred = [evaluation.froggy_lotus_color, evaluation.mixy_code_color]
    for event in evaluation.intent_events or ():
        if event.get("type") == JELLY_ZONE_CONVERSION_EVENT:
            try:
                preferred.append(int(event["color"]))
            except (KeyError, TypeError, ValueError):
                continue
    for color in preferred:
        if color is not None and int(color) in landed_matches:
            return int(color)
    return int(dragged)


def oriented_swap_candidate(evaluation: "MoveEvaluation") -> MoveCandidate:
    """``evaluation.candidate`` with the tile we are playing for as the dragged one.

    Returns the candidate unchanged whenever the orientation is not ours to
    choose (a directional activation), cannot matter (both tiles the same
    colour), or is already right.
    """
    candidate = evaluation.candidate
    if not _is_plain_swap_candidate(candidate):
        return candidate
    dragged, displaced = _swapped_colors(candidate)
    if dragged == displaced:
        return candidate
    intent = intended_swap_color(evaluation)
    if intent is None or int(intent) != int(displaced):
        return candidate
    return flip_swap_candidate(candidate)


def oriented_swipe(evaluation: "MoveEvaluation") -> tuple[tuple[int, int], str]:
    """The (start cell, direction) to actually swipe for this evaluation."""
    candidate = oriented_swap_candidate(evaluation)
    return candidate.start, Direction(candidate.direction).value


def _candidate_activates_spray_se(candidate: MoveCandidate) -> bool:
    start_row, start_col = candidate.start
    return candidate.special_board[start_row][start_col] == SPECIAL_SPRAY_SE


def _spray_se_ray_cells(
    board: list[list[int]],
    start: tuple[int, int],
    direction: Direction,
) -> list[tuple[int, int]]:
    direction = Direction(direction)
    row_step, col_step = DIRECTION_STEPS[direction]
    size = len(board)
    # The spray paints from the swap cell (one step in the swipe direction)
    # outward to the board edge; its own cell is consumed, not painted. So a
    # spray N tiles from the edge converts N tiles, counted from the swap cell
    # (e.g. swiping left from column 4 paints columns 3..0 -> 4 tiles).
    row, col = start
    row += row_step
    col += col_step
    cells = []
    while 0 <= row < size and 0 <= col < size:
        if _is_board_piece(board[row][col]):
            cells.append((row, col))
        row += row_step
        col += col_step
    return cells


def _spray_se_paint_color(candidate: MoveCandidate) -> int | None:
    spray_row, spray_col = candidate.start
    own_color = candidate.board[spray_row][spray_col]
    if _is_normal_color(own_color):
        return own_color

    row_step, col_step = DIRECTION_STEPS[Direction(candidate.direction)]
    adjacent_row = spray_row + row_step
    adjacent_col = spray_col + col_step
    size = len(candidate.board)
    if 0 <= adjacent_row < size and 0 <= adjacent_col < size:
        adjacent_color = candidate.board[adjacent_row][adjacent_col]
        if _is_normal_color(adjacent_color):
            return adjacent_color
    return None


def _spray_se_transformed_candidate(
    candidate: MoveCandidate,
) -> tuple[MoveCandidate, list[tuple[int, int]], int] | None:
    if not _candidate_activates_spray_se(candidate):
        return None
    spray_row, spray_col = candidate.start
    spray_color = _spray_se_paint_color(candidate)
    if spray_color is None:
        return None

    ray_cells = _spray_se_ray_cells(candidate.board, candidate.start, candidate.direction)
    if not ray_cells:
        return None

    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    for row, col in ray_cells:
        board[row][col] = spray_color
    # The spray cell itself is consumed by the swipe (not painted), so empty it
    # to keep it out of the resulting match instead of leaving the special tile.
    board[spray_row][spray_col] = EMPTY
    special_board[spray_row][spray_col] = EMPTY

    return (
        MoveCandidate(
            candidate.start,
            candidate.start,
            candidate.direction,
            board,
            special_board,
        ),
        ray_cells,
        spray_color,
    )


def _candidate_activates_sweep_se(candidate: MoveCandidate) -> bool:
    start_row, start_col = candidate.start
    return candidate.special_board[start_row][start_col] == SPECIAL_SWEEP_SE_BROOM


def _sweep_se_target(candidate: MoveCandidate) -> tuple[int, Direction] | None:
    target_row, target_col = candidate.target
    target_color = candidate.board[target_row][target_col]
    if not _is_normal_color(target_color):
        return None
    return target_color, Direction(candidate.direction)


def _sweep_se_packed_board(
    board: list[list[int]],
    special_board: list[list[int]],
    target_color: int,
    direction: Direction,
    broom_cell: tuple[int, int] | None = None,
) -> tuple[list[list[int]], list[list[int]], list[tuple[int, int]]]:
    # Model the sweep as a per-line gather: along every line parallel to the
    # swipe, the plain target-colour tiles slide to the swipe edge and pack
    # contiguously, while the remaining tiles keep their relative order and the
    # holes trail behind. Horizontal swipes therefore build horizontal runs and
    # vertical swipes build vertical runs, so the swipe direction matters.
    #
    # The broom's own line is the exception. Verified against a recording
    # (Debug run 2026-08-08_08-14-52_290, yellow sweep UP from (2,0)): the
    # tiles *behind* the broom -- further from the swipe edge -- do not move at
    # all, and the hole the consumed broom leaves stays on its own cell. Only
    # the segment between the swipe edge and the broom takes part in the
    # gather. Treating that hole as an ordinary one shifted the whole line by a
    # cell, which is why all seven mismatches in that recording sat in the
    # broom's column.
    direction = Direction(direction)
    size = len(board)
    packed_board = clone_grid(board)
    packed_special = clone_grid(special_board)
    horizontal = direction in (Direction.LEFT, Direction.RIGHT)
    toward_high = direction in (Direction.RIGHT, Direction.DOWN)
    broom_line = None
    if broom_cell is not None:
        broom_line = broom_cell[0] if horizontal else broom_cell[1]
    swept_cells: list[tuple[int, int]] = []
    for line in range(size):
        coords = (
            [(line, col) for col in range(size)]
            if horizontal
            else [(row, line) for row in range(size)]
        )
        if line == broom_line:
            broom_index = coords.index(tuple(broom_cell))
            # Keep only the stretch running from the swipe edge to the broom.
            coords = (
                coords[broom_index:] if toward_high else coords[: broom_index + 1]
            )
        # Immovable cells drop out of the gather entirely. SweepIt::MakeSwaps
        # (0x587eb88) checks SlotModel.movable before a cell enters the list of
        # positions it writes back to, so such a cell keeps its place and does
        # not shift the tiles around it.
        coords = [
            (row, col)
            for row, col in coords
            if special_board[row][col] not in SWEEP_IMMOVABLE_SPECIALS
        ]
        target_tiles: list[tuple[int, int]] = []
        other_tiles: list[tuple[int, int]] = []
        holes = 0
        for row, col in coords:
            color = board[row][col]
            special = special_board[row][col]
            if color == EMPTY:
                holes += 1
            elif color == target_color and (
                special == EMPTY or special in SWEEP_MOVABLE_SPECIALS
            ):
                # Read out of the engine (2026-08-21): SweepIt::MakeSwaps keeps
                # a slot when SlotModel::MatchesWithColor says yes, and that
                # goes through IsPieceWithColor -- true for Normal *and* for the
                # classic colour specials (Column/Row/Bomb/Fireworks/Crosshair).
                # So a target-colour classic special is gathered along with the
                # plain tiles; only the colourless board specials stay put.
                target_tiles.append((color, special))
            else:
                other_tiles.append((color, special))
        if not target_tiles:
            continue
        empties = [(EMPTY, EMPTY)] * holes
        if toward_high:
            ordered = empties + other_tiles + target_tiles
            target_start = holes + len(other_tiles)
        else:
            ordered = target_tiles + other_tiles + empties
            target_start = 0
        for (row, col), (color, special) in zip(coords, ordered):
            packed_board[row][col] = color
            packed_special[row][col] = special
        for offset in range(len(target_tiles)):
            swept_cells.append(coords[target_start + offset])
    return packed_board, packed_special, swept_cells


def _sweep_se_transformed_candidate(
    candidate: MoveCandidate,
) -> tuple[MoveCandidate, list[tuple[int, int]], int] | None:
    if not _candidate_activates_sweep_se(candidate):
        return None
    target = _sweep_se_target(candidate)
    if target is None:
        return None
    target_color, direction = target

    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    broom_row, broom_col = candidate.start
    # The broom is consumed by activation, so it leaves an empty cell.
    board[broom_row][broom_col] = EMPTY
    special_board[broom_row][broom_col] = EMPTY

    packed_board, packed_special, swept_cells = _sweep_se_packed_board(
        board,
        special_board,
        target_color,
        direction,
        broom_cell=(broom_row, broom_col),
    )
    if not swept_cells:
        return None

    return (
        MoveCandidate(
            candidate.start,
            candidate.start,
            direction,
            packed_board,
            packed_special,
        ),
        swept_cells,
        target_color,
    )


def _has_five_in_line(cells) -> bool:
    cell_set = set(cells)
    for row, col in cell_set:
        if (row, col - 1) not in cell_set and all(
            (row, col + step) in cell_set for step in range(1, 5)
        ):
            return True
        if (row - 1, col) not in cell_set and all(
            (row + step, col) in cell_set for step in range(1, 5)
        ):
            return True
    return False


def classify_cells(cells):
    count = len(cells)
    rows = {row for row, _ in cells}
    cols = {col for _, col in cells}
    if count == 4 and len(rows) == 2 and len(cols) == 2:
        return "square"

    is_straight = len(rows) == 1 or len(cols) == 1
    if is_straight:
        if count >= 5:
            return "five"
        if count == 4:
            return "four"
        return "three"
    # ComboModel.GetComboType asks IsFiveShapeFast first: any five in a row or
    # column inside the combo makes it a Five, so an L/T whose long arm is five
    # leaves a Lightning, not the L/T special (libil2cpp.so, 2026-10-14).
    if count >= 6 and _has_five_in_line(cells):
        return "five"

    row_counts = {row: sum(1 for cell in cells if cell[0] == row) for row in rows}
    col_counts = {col: sum(1 for cell in cells if cell[1] == col) for col in cols}
    for row, col in cells:
        if row_counts[row] < 3 or col_counts[col] < 3:
            continue
        directions = [
            any(other_col < col for other_row, other_col in cells if other_row == row),
            any(other_col > col for other_row, other_col in cells if other_row == row),
            any(other_row < row for other_row, other_col in cells if other_col == col),
            any(other_row > row for other_row, other_col in cells if other_col == col),
        ]
        if sum(directions) >= 3:
            return "t_or_cross"
    return "l"


def _line_runs(board, horizontal):
    board_array = as_board_array(board)
    if board_array.shape[0] < 3 and board_array.shape[1] < 3:
        return []

    matchable = _matchable_mask(board_array)
    if horizontal:
        if board_array.shape[1] < 3:
            return []
        starts = (
            matchable[:, :-2]
            & (board_array[:, :-2] == board_array[:, 1:-1])
            & (board_array[:, :-2] == board_array[:, 2:])
        )
        if not starts.any():
            return []
        run_mask = np.zeros(board_array.shape, dtype=bool)
        run_mask[:, :-2] |= starts
        run_mask[:, 1:-1] |= starts
        run_mask[:, 2:] |= starts
        scan_mask = run_mask
        scan_colors = board_array
    else:
        if board_array.shape[0] < 3:
            return []
        starts = (
            matchable[:-2, :]
            & (board_array[:-2, :] == board_array[1:-1, :])
            & (board_array[:-2, :] == board_array[2:, :])
        )
        if not starts.any():
            return []
        run_mask = np.zeros(board_array.shape, dtype=bool)
        run_mask[:-2, :] |= starts
        run_mask[1:-1, :] |= starts
        run_mask[2:, :] |= starts
        scan_mask = run_mask.T
        scan_colors = board_array.T

    runs = []
    rows_with_runs = np.flatnonzero(scan_mask.any(axis=1))
    for a in rows_with_runs:
        positions = np.flatnonzero(scan_mask[a])
        if positions.size == 0:
            continue
        colors = scan_colors[a, positions]
        split_points = np.flatnonzero(
            (np.diff(positions) > 1) | (colors[1:] != colors[:-1])
        ) + 1
        for segment in np.split(positions, split_points):
            if segment.size < 3:
                continue
            color = int(scan_colors[a, segment[0]])
            if horizontal:
                cells = {(int(a), int(col)) for col in segment}
            else:
                cells = {(int(row), int(a)) for row in segment}
            runs.append((color, cells))
    return runs


def _cell_matches_color(board_value: int, special_value: int, color: int) -> bool:
    special_colors = _special_match_colors(special_value)
    if special_colors:
        return color in special_colors
    return board_value == color


def _color_match_mask(
    board_array: np.ndarray,
    special_array: np.ndarray,
    color: int,
) -> np.ndarray:
    mask = (board_array == color) & _matchable_mask(board_array)
    flexible_rows, flexible_cols = np.where(
        (special_array >= SPECIAL_VINNIE_SE_HEART_BASE)
        & (special_array <= SPECIAL_VINNIE_SE_HEART_MAX)
        | (special_array == SPECIAL_RED_BLUE_TILE)
    )
    for row, col in zip(flexible_rows, flexible_cols):
        if color in _special_match_colors(int(special_array[row, col])):
            mask[row, col] = True
    return mask


def _line_runs_for_color(board_array, special_array, color, horizontal):
    match_mask = _color_match_mask(board_array, special_array, color)
    if horizontal:
        if board_array.shape[1] < 3:
            return []
        starts = match_mask[:, :-2] & match_mask[:, 1:-1] & match_mask[:, 2:]
        run_mask = np.zeros(board_array.shape, dtype=bool)
        run_mask[:, :-2] |= starts
        run_mask[:, 1:-1] |= starts
        run_mask[:, 2:] |= starts
        scan_mask = run_mask
    else:
        if board_array.shape[0] < 3:
            return []
        starts = match_mask[:-2, :] & match_mask[1:-1, :] & match_mask[2:, :]
        run_mask = np.zeros(board_array.shape, dtype=bool)
        run_mask[:-2, :] |= starts
        run_mask[1:-1, :] |= starts
        run_mask[2:, :] |= starts
        scan_mask = run_mask.T

    runs = []
    rows_with_runs = np.flatnonzero(scan_mask.any(axis=1))
    for a in rows_with_runs:
        positions = np.flatnonzero(scan_mask[a])
        if positions.size == 0:
            continue
        split_points = np.flatnonzero(np.diff(positions) > 1) + 1
        for segment in np.split(positions, split_points):
            if segment.size < 3:
                continue
            if horizontal:
                cells = {(int(a), int(col)) for col in segment}
            else:
                cells = {(int(row), int(a)) for row in segment}
            runs.append((color, cells))
    return runs


def _square_runs_for_color(board_array, special_array, color):
    if min(board_array.shape) < 2:
        return []
    match_mask = _color_match_mask(board_array, special_array, color)
    same_square = (
        match_mask[:-1, :-1]
        & match_mask[:-1, 1:]
        & match_mask[1:, :-1]
        & match_mask[1:, 1:]
    )
    runs = []
    rows, cols = np.where(same_square)
    for row, col in zip(rows, cols):
        row = int(row)
        col = int(col)
        cells = {(row, col), (row, col + 1), (row + 1, col), (row + 1, col + 1)}
        runs.append((color, cells))
    return runs


# Cheapest value that can make _has_color_flexible_specials true. Nearly every
# board is below it, and one max() beats building three boolean arrays.
_COLOR_FLEXIBLE_SPECIAL_MIN = min(SPECIAL_RED_BLUE_TILE, SPECIAL_VINNIE_SE_HEART_BASE)


def _has_color_flexible_specials(special_board) -> bool:
    if special_board is None:
        return False
    special_array = as_board_array(special_board)
    # ~15k calls per move on the reference board, so the early out matters: the
    # full predicate allocates three intermediate masks, the max() does not.
    if special_array.size == 0 or int(special_array.max()) < _COLOR_FLEXIBLE_SPECIAL_MIN:
        return False
    return bool(
        (
            (special_array >= SPECIAL_VINNIE_SE_HEART_BASE)
            & (special_array <= SPECIAL_VINNIE_SE_HEART_MAX)
            | (special_array == SPECIAL_RED_BLUE_TILE)
        ).any()
    )


def _has_vectorized_match(board, allow_square_matches: bool) -> bool:
    board_array = as_board_array(board)
    if min(board_array.shape) < 2:
        return False

    matchable = _matchable_mask(board_array)
    if board_array.shape[1] >= 3:
        horizontal = (
            matchable[:, :-2]
            & (board_array[:, :-2] == board_array[:, 1:-1])
            & (board_array[:, :-2] == board_array[:, 2:])
        )
        if bool(horizontal.any()):
            return True
    if board_array.shape[0] >= 3:
        vertical = (
            matchable[:-2, :]
            & (board_array[:-2, :] == board_array[1:-1, :])
            & (board_array[:-2, :] == board_array[2:, :])
        )
        if bool(vertical.any()):
            return True
    if allow_square_matches and min(board_array.shape) >= 2:
        square = (
            matchable[:-1, :-1]
            & (board_array[:-1, :-1] == board_array[:-1, 1:])
            & (board_array[:-1, :-1] == board_array[1:, :-1])
            & (board_array[:-1, :-1] == board_array[1:, 1:])
        )
        return bool(square.any())
    return False


def _square_runs(board):
    board_array = as_board_array(board)
    size = board_array.shape[0]
    if size < 2:
        return []
    top_left = board_array[:-1, :-1]
    same_square = (
        (top_left == board_array[:-1, 1:])
        & (top_left == board_array[1:, :-1])
        & (top_left == board_array[1:, 1:])
        & _matchable_mask(top_left)
    )
    runs = []
    rows, cols = np.where(same_square)
    for row, col in zip(rows, cols):
        row = int(row)
        col = int(col)
        cells = {(row, col), (row, col + 1), (row + 1, col), (row + 1, col + 1)}
        runs.append((int(board_array[row, col]), cells))
    return runs


def find_matches(board, allow_square_matches: bool = False, special_board=None):
    board_array = as_board_array(board)
    if _has_color_flexible_specials(special_board):
        special_array = as_board_array(special_board)
        runs = []
        for color in range(BLUE, WHITE + 1):
            runs += _line_runs_for_color(board_array, special_array, color, True)
            runs += _line_runs_for_color(board_array, special_array, color, False)
            if allow_square_matches:
                runs += _square_runs_for_color(board_array, special_array, color)
    else:
        runs = _line_runs(board_array, True) + _line_runs(board_array, False)
        if allow_square_matches:
            runs += _square_runs(board_array)

    groups = []
    for color, cells in runs:
        merged = False
        for index, (group_color, group_cells) in enumerate(groups):
            if group_color == color and group_cells.intersection(cells):
                groups[index] = (group_color, group_cells.union(cells))
                merged = True
                break
        if not merged:
            groups.append((color, cells))

    changed = True
    while changed:
        changed = False
        merged_groups = []
        while groups:
            color, cells = groups.pop(0)
            did_merge = False
            for index, (other_color, other_cells) in enumerate(groups):
                if color == other_color and cells.intersection(other_cells):
                    groups[index] = (color, cells.union(other_cells))
                    changed = True
                    did_merge = True
                    break
            if not did_merge:
                merged_groups.append((color, cells))
        groups = merged_groups

    return [
        MatchGroup(frozenset(cells), color, classify_cells(cells))
        for color, cells in groups
    ]


def _match_scan_cache_key(
    board: list[list[int]],
    allow_square_matches: bool,
    special_board=None,
    has_color_flexible_specials: bool | None = None,
) -> tuple:
    # Callers that already know the answer pass it in: this used to recompute
    # the scan on every key build, doubling the ~15k calls per move.
    if has_color_flexible_specials is None:
        has_color_flexible_specials = _has_color_flexible_specials(special_board)
    if has_color_flexible_specials:
        return _grid_cache_key(board), _grid_cache_key(special_board), allow_square_matches
    return _grid_cache_key(board), allow_square_matches


def _find_matches_cached(
    board: list[list[int]],
    allow_square_matches: bool,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None,
    special_board=None,
) -> list[MatchGroup]:
    check_planning_cancelled()
    has_color_flexible_specials = _has_color_flexible_specials(special_board)
    if match_scan_cache is None:
        if has_color_flexible_specials:
            return find_matches(board, allow_square_matches, special_board)
        return find_matches(board, allow_square_matches)
    key = _match_scan_cache_key(
        board,
        allow_square_matches,
        special_board,
        has_color_flexible_specials=has_color_flexible_specials,
    )
    if key not in match_scan_cache:
        if has_color_flexible_specials:
            match_scan_cache[key] = find_matches(board, allow_square_matches, special_board)
        elif _has_vectorized_match(board, allow_square_matches):
            match_scan_cache[key] = find_matches(board, allow_square_matches)
        else:
            match_scan_cache[key] = []
    return match_scan_cache[key]


def drop_boards(
    board: list[list[int]],
    special_board: list[list[int]],
) -> tuple[list[list[int]], list[list[int]]]:
    source_board = as_board_array(board)
    source_special, xtra_mask = _movable_specials_and_xtra_mask(special_board)
    size = source_board.shape[0]
    has_blocker = bool((source_special == SPECIAL_BILLIE_DRONE).any()) or bool((source_board == BLOCKED).any())
    if not has_blocker:
        order = np.argsort(source_board != EMPTY, axis=0, kind="stable")
        dropped_special = np.take_along_axis(source_special, order, axis=0).astype(np.int16, copy=False)
        return (
            np.take_along_axis(source_board, order, axis=0).astype(np.int16, copy=False),
            _restore_xtra_markers(dropped_special, xtra_mask),
        )
    dropped_board = np.full_like(source_board, EMPTY, dtype=np.int16)
    dropped_special = np.full_like(source_special, EMPTY, dtype=np.int16)
    lotus_mask = source_special == SPECIAL_FROGGY_LOTUS
    # Billie is unmatchable but movable (SlotModel.movable=true). It falls
    # with the column; only the lotus stays fixed and is skipped by gravity.
    blocker_mask = (source_board == BLOCKED) & ~lotus_mask & (source_special != SPECIAL_BILLIE_DRONE)
    dropped_board[lotus_mask] = source_board[lotus_mask]
    dropped_special[lotus_mask] = source_special[lotus_mask]
    for col in range(size):
        segment_start = 0
        blocker_rows = [int(row) for row in np.flatnonzero(blocker_mask[:, col])] + [size]
        for segment_end in blocker_rows:
            if segment_end > segment_start:
                segment_rows = np.arange(segment_start, segment_end)
                segment_rows = segment_rows[~lotus_mask[segment_rows, col]]
                piece_mask = source_board[segment_rows, col] != EMPTY
                values = source_board[segment_rows, col][piece_mask]
                specials = source_special[segment_rows, col][piece_mask]
                if values.size:
                    target_rows = segment_rows[-values.size:]
                    dropped_board[target_rows, col] = values
                    dropped_special[target_rows, col] = specials
            if segment_end < size:
                dropped_board[segment_end, col] = source_board[segment_end, col]
                dropped_special[segment_end, col] = source_special[segment_end, col]
            segment_start = segment_end + 1
    return dropped_board, _restore_xtra_markers(dropped_special, xtra_mask)


def _drop_boards_with_origins(
    board: list[list[int]],
    special_board: list[list[int]],
    origins: list[list[tuple[int, int] | None]],
) -> tuple[list[list[int]], list[list[int]], list[list[tuple[int, int] | None]]]:
    source_board = as_board_array(board)
    source_special, xtra_mask = _movable_specials_and_xtra_mask(special_board)
    source_origins = np.empty(source_board.shape, dtype=object)
    source_origins[:, :] = origins
    size = source_board.shape[0]
    has_blocker = bool((source_special == SPECIAL_BILLIE_DRONE).any()) or bool((source_board == BLOCKED).any())
    if not has_blocker:
        order = np.argsort(source_board != EMPTY, axis=0, kind="stable")
        dropped_special = np.take_along_axis(source_special, order, axis=0).astype(np.int16, copy=False)
        return (
            np.take_along_axis(source_board, order, axis=0).astype(np.int16, copy=False),
            _restore_xtra_markers(dropped_special, xtra_mask),
            np.take_along_axis(source_origins, order, axis=0),
        )
    dropped_board = np.full_like(source_board, EMPTY, dtype=np.int16)
    dropped_special = np.full_like(source_special, EMPTY, dtype=np.int16)
    dropped_origins = np.empty(source_origins.shape, dtype=object)
    dropped_origins[:, :] = None
    lotus_mask = source_special == SPECIAL_FROGGY_LOTUS
    blocker_mask = (source_board == BLOCKED) & ~lotus_mask & (source_special != SPECIAL_BILLIE_DRONE)
    dropped_board[lotus_mask] = source_board[lotus_mask]
    dropped_special[lotus_mask] = source_special[lotus_mask]
    dropped_origins[lotus_mask] = source_origins[lotus_mask]
    for col in range(size):
        segment_start = 0
        blocker_rows = [int(row) for row in np.flatnonzero(blocker_mask[:, col])] + [size]
        for segment_end in blocker_rows:
            if segment_end > segment_start:
                segment_rows = np.arange(segment_start, segment_end)
                segment_rows = segment_rows[~lotus_mask[segment_rows, col]]
                piece_mask = source_board[segment_rows, col] != EMPTY
                values = source_board[segment_rows, col][piece_mask]
                specials = source_special[segment_rows, col][piece_mask]
                origin_values = source_origins[segment_rows, col][piece_mask]
                if values.size:
                    target_rows = segment_rows[-values.size:]
                    dropped_board[target_rows, col] = values
                    dropped_special[target_rows, col] = specials
                    dropped_origins[target_rows, col] = origin_values
            if segment_end < size:
                dropped_board[segment_end, col] = source_board[segment_end, col]
                dropped_special[segment_end, col] = source_special[segment_end, col]
                dropped_origins[segment_end, col] = source_origins[segment_end, col]
            segment_start = segment_end + 1
    return dropped_board, _restore_xtra_markers(dropped_special, xtra_mask), dropped_origins


# Ported RefillSlots callback (engine_refill.simulator_refill), or None: the
# holes then stay empty, the old unknown-refill boundary.
_ENGINE_REFILL = None
# peek_draws(count) of the same RNG, or None: picks a cascade special's cell.
_ENGINE_PEEK_DRAWS = None
# ball_spent(cell), or None: the refill stops counting the colour under that ball.
_ENGINE_BALL_SPENT = None
# Draws the special a player combo hatches into; see engine_refill_active.
_ENGINE_RANDOM_SPECIAL = None
# Exact Cleo action adapter. A refill alone cannot resolve its cloned games.
_ENGINE_CLEO_SWAP = None


@contextmanager
def engine_refill_active(refill=None, peek_draws=None, ball_spent=None, random_special=None, cleo_swap=None):
    """Fill the holes after every simulated gravity drop with ``refill``.

    ``refill(board, special_board, chain_combos) -> (board, special_board)``
    consumes the engine RNG, so simulation caches are bypassed while it is
    active. ``chain_combos`` counts the cascade combos just destroyed (0 for
    the player's own match). ``peek_draws(count)`` returns the next draws
    without consuming them; ``ball_spent(cell)`` is told which ball fired.
    ``random_special(cell, color)`` draws what a player combo hatches into, or
    returns None outside Match & Hatch.
    """
    global _ENGINE_REFILL, _ENGINE_PEEK_DRAWS, _ENGINE_BALL_SPENT, _ENGINE_RANDOM_SPECIAL, _ENGINE_CLEO_SWAP
    previous = (_ENGINE_REFILL, _ENGINE_PEEK_DRAWS, _ENGINE_BALL_SPENT,
                _ENGINE_RANDOM_SPECIAL, _ENGINE_CLEO_SWAP)
    _ENGINE_REFILL, _ENGINE_PEEK_DRAWS, _ENGINE_BALL_SPENT, _ENGINE_RANDOM_SPECIAL, _ENGINE_CLEO_SWAP = (
        refill, peek_draws, ball_spent, random_special, cleo_swap)
    try:
        yield
    finally:
        (_ENGINE_REFILL, _ENGINE_PEEK_DRAWS, _ENGINE_BALL_SPENT,
         _ENGINE_RANDOM_SPECIAL, _ENGINE_CLEO_SWAP) = previous


# engine_refill.ExactRefillSession while the ordinary ranking runs, or None.
_EXACT_REFILL = None
# exact_refill_choice: the most time the next-board search for a setup may add.
EXACT_REFILL_SETUP_SECONDS = 1.0


@contextmanager
def exact_refill_active(session=None):
    """Let one best-move computation see what falls after each candidate."""
    global _EXACT_REFILL
    previous = _EXACT_REFILL
    _EXACT_REFILL = session
    try:
        yield
    finally:
        _EXACT_REFILL = previous


# IsClassicSpecial: what specialsAutoExplode fires (DestroyMatches b__15 0x5965e14).
_AUTO_EXPLODE_SPECIALS = frozenset(
    {SPECIAL_HORIZONTAL, SPECIAL_VERTICAL, SPECIAL_BOMB, SPECIAL_LIGHTNING, 46}
)  # 46 is the crosshair, engine 8; IsClassicSpecial 0x5932b88 is engine 4..8.


def _classic_specials(special_board, enabled: bool, mode) -> set[tuple[int, int]] | None:
    """Where classic specials stand before a clear; None without the rule.

    The Blow Em Up mode entry and the caller's flag mean the same rule."""
    if not enabled and normalize_game_mode(mode) is not GameMode.BLOW_EM_UP:
        return None
    return {
        (row, col)
        for row, values in enumerate(special_board)
        for col, value in enumerate(values)
        if value in _AUTO_EXPLODE_SPECIALS
    }


def _tag_auto_explosions(special_board, origins, classic_before, tags) -> None:
    """Follow each special this clear made through gravity, by a tag of its own."""
    if classic_before is None:
        return
    for row, values in enumerate(special_board):
        for col, value in enumerate(values):
            if value in _AUTO_EXPLODE_SPECIALS and (row, col) not in classic_before:
                tag = ("auto_explode", len(tags), row, col)
                origins[row][col] = tag
                tags.add(tag)


def _with_auto_explosions(matches, board, origins, tags, past_boundary: bool):
    """specialsAutoExplode: DestroyMatches gives each classic special made this
    move a rank-11 combo of its own after the refill (GetAllCombos 0x595407c,
    ComboModel 0x5954248), so it fires in this layer, wherever it fell, next to
    whatever new matches the refill made. Every cascade loop goes through here."""
    if not tags or past_boundary:
        return matches
    matched_cells = {cell for match in matches for cell in match.cells}
    fired = [
        MatchGroup(frozenset({(row, col)}), int(board[row][col]), "auto_explode")
        for row, values in enumerate(origins)
        for col, origin in enumerate(values)
        if origin in tags and (row, col) not in matched_cells
    ]
    return list(matches) + fired if fired else matches


def _chain_combo_count(matches) -> int:
    """Spojevi koji trose Next() u kaskadi: a forced explosion combo draws nothing
    (every recorded moves-multiplier swipe was exactly one draw over with it)."""
    return sum(1 for match in matches if match.kind != "auto_explode")


def _drop_and_refill(board, special_board, origins, chain_combos: int = 0):
    """Gravity followed by BoardModel.RefillSlots, as each engine cascade does."""
    board, special_board, origins = _drop_boards_with_origins(board, special_board, origins)
    if _ENGINE_REFILL is not None:
        board, special_board = _ENGINE_REFILL(board, special_board, chain_combos)
    return board, special_board, origins


def _created_special_cell(
    match: MatchGroup,
    swap_cells: tuple[tuple[int, int], ...] = (),
    cascade_combos=(),
) -> tuple[int, int]:
    """Cell the new special occupies when this match clears.

    The game leaves it on the piece the player just moved, not in the middle of
    the line. Measured on the 2026-08-10 Special O'Rama game (Debug/runs): where
    the two rules disagreed, the swapped cell was right 8 times and the middle
    cell 0. The distinction decides which cell keeps a piece, which is what the
    rest of the column falls onto -- get it wrong and every cascade after it is
    a different board, which is how a predicted same-move extra turned into a
    next-move setup.

    Cascade matches have no swap: with the exact refill the cell is the combo's
    own engine draw modulo its size, over cells and combos scanned x-major, y
    ascending (BoardAnalyzer.GetAllCombos 0x59167c8). Measured on recorded UFO
    games (Debug/research 20261102), not yet confirmed in the disassembly; it is
    the per-combo draw EngineRefill.fill consumes before the refill. Without
    that RNG the last cell of the scan stands in. ``target`` (the cell the
    grabbed piece moved into) wins over ``start`` on the rare match that
    contains both, matching _dragon_origin_cells.
    """
    for cell in swap_cells:
        if cell in match.cells:
            return cell
    scan = lambda cell: (cell[1], cell[0])
    if cascade_combos and _ENGINE_PEEK_DRAWS is not None:
        ordered = sorted(cascade_combos, key=lambda combo: min(map(scan, combo.cells)))
        rank = next(index for index, combo in enumerate(ordered) if combo is match)
        cells = sorted(match.cells, key=scan)
        return cells[_ENGINE_PEEK_DRAWS(rank + 1)[rank] % len(cells)]
    return max(match.cells, key=scan)


def _created_special_type(match: MatchGroup) -> int:
    """Return the real special left by a match when its effect is known."""
    # MatchRulesModel.allSpecialsLightning overrides the shape-based table: in
    # that ruleset every created special is a Lightning, so the simulator knows
    # each one's effect instead of carrying an unresolved CREATED_SPECIAL.
    if _ALL_SPECIALS_LIGHTNING:
        return SPECIAL_LIGHTNING
    if match.kind == "square":
        return SPECIAL_CROSSHAIR
    if match.kind == "five":
        return SPECIAL_LIGHTNING
    # BoardAnalyzer.MakeSpecialSlotCreated (0x5726da4), reason ComboSpecial: the
    # ComboType -> SlotValueType table is Five->Fireworks, RShape->Bomb,
    # FourRow->Row, FourColumn->Column, Square->Crosshair. Recorded games agree
    # (Debug/runs 2026-09/10: four in a column left Column 677x and never a
    # bomb, four in a row left Row 377x, L/T left Bomb).
    if match.kind == "four":
        rows = {row for row, _ in match.cells}
        if len(rows) == 1:
            return SPECIAL_HORIZONTAL
        return SPECIAL_VERTICAL
    # Square-match: a 2x2 block with an arm that never forms a row of three and
    # a column of three through one cell is a Square combo, not an RShape, so it
    # leaves a Crosshair. Debug/runs 2026-10-01..31, moves with one 4+ match and
    # one new special: square + arm left Crosshair 76x and Bomb 2x; a real L/T
    # (3+3) that also contains a 2x2 left Bomb 5/5.
    if match.kind == "l" and _contains_square(match.cells) and not _has_line_cross(match.cells):
        return SPECIAL_CROSSHAIR
    if match.kind in {"l", "t_or_cross"}:
        return SPECIAL_BOMB
    return CREATED_SPECIAL


def _contains_square(cells) -> bool:
    cells = set(cells)
    return any(
        {(row, col + 1), (row + 1, col), (row + 1, col + 1)} <= cells for row, col in cells
    )


def _has_line_cross(cells) -> bool:
    """A row run of three and a column run of three through the same cell."""
    cells = set(cells)
    for row, col in cells:
        horizontal = 1
        step = 1
        while (row, col - step) in cells:
            horizontal += 1
            step += 1
        step = 1
        while (row, col + step) in cells:
            horizontal += 1
            step += 1
        vertical = 1
        step = 1
        while (row - step, col) in cells:
            vertical += 1
            step += 1
        step = 1
        while (row + step, col) in cells:
            vertical += 1
            step += 1
        if horizontal >= 3 and vertical >= 3:
            return True
    return False


def _count_extra_move_matches(matches: list[MatchGroup]) -> int:
    """Extra moves granted by a batch of matches.

    Square matches only exist when the square-match mode is enabled, and in that
    mode a 2x2 grants an extra move (and a crosshair special) in-game, so it
    counts the same as a straight four.

    The rule is identical for the direct (post-swap) batch and for cascade
    batches -- "direct" vs "cascade" is decided purely by *which* matches the
    caller passes in, never by a different threshold. Use
    ``_count_direct_extra_move_matches`` at the direct call sites so the intent
    stays readable.
    """
    return sum(1 for match in matches if len(match.cells) >= 4)


# The direct batch uses the exact same rule; this alias only documents intent at
# the call site. Keeping it as an alias (instead of a second body) makes it
# impossible for the two to silently drift apart.
_count_direct_extra_move_matches = _count_extra_move_matches


def _joojoo_skull_effect_cells_for_color(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
    color: int,
) -> set[tuple[int, int]]:
    size = len(board)
    effect_cells = set()
    for row_step, col_step in JOOJOO_SKULL_DIRECTIONS.get(color, ()):
        target_row = row + row_step
        target_col = col + col_step
        while 0 <= target_row < size and 0 <= target_col < size:
            if _is_board_piece(board[target_row][target_col]) or special_board[target_row][target_col] != EMPTY:
                effect_cells.add((target_row, target_col))
            target_row += row_step
            target_col += col_step
    return effect_cells


def _joojoo_skull_effect_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
) -> set[tuple[int, int]]:
    return _joojoo_skull_effect_cells_for_color(board, special_board, row, col, board[row][col])


def _random_board_wide_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
    remote_target_count: int,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> set[tuple[int, int]]:
    """Select random remote board pieces without replacement, plus the source."""
    source = (row, col)
    excluded_cells = set(excluded_cells or ())
    candidates = [
        (other_row, other_col)
        for other_row, values in enumerate(board)
        for other_col, value in enumerate(values)
        if _is_board_piece(value)
        and (other_row, other_col) != source
        and (other_row, other_col) not in excluded_cells
    ]

    sample_count = min(remote_target_count, len(candidates))
    rng = _RANDOM_SPECIAL_TARGET_RNG or random
    return {source, *rng.sample(candidates, sample_count)}


def _lightning_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> set[tuple[int, int]]:
    """Zap 12 random remote pieces, independently of Lightning's color."""
    return _random_board_wide_effect_cells(
        board,
        row,
        col,
        LIGHTNING_REMOTE_TARGET_COUNT,
        excluded_cells,
    )


def _crosshair_effect_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> set[tuple[int, int]]:
    """Fire six random remote shots, matching the isolated live observation."""
    return _random_board_wide_effect_cells(
        board,
        row,
        col,
        CROSSHAIR_REMOTE_TARGET_COUNT,
        excluded_cells,
    )


def _all_aboard_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> set[tuple[int, int]]:
    """Fire All Aboard using the client engine's default targeting order.

    IL2CPP ``GetAreaOfPieceExplode`` separates eligible pieces into the current
    player's blue, opponent-red and neutral pools. It guarantees the configured
    minimum blue picks while blue remains, then applies ``chanceToPickBlue`` to
    each remaining shot; a non-blue shot prefers red and finally a neutral
    colour. Selected positions are removed from their pool, so no shot repeats.
    """
    source = (row, col)
    excluded = set(excluded_cells or ()) | {source}
    pools = {
        "blue": [],
        "red": [],
        "neutral": [],
    }
    for other_row, values in enumerate(board):
        for other_col, value in enumerate(values):
            cell = (other_row, other_col)
            if cell in excluded or not _is_board_piece(value):
                continue
            pool = "blue" if value == BLUE else "red" if value == RED else "neutral"
            pools[pool].append(cell)

    rng = _RANDOM_SPECIAL_TARGET_RNG or random
    if _ALL_ABOARD_PROFILE == "solo":
        target_count = ALL_ABOARD_SOLO_REMOTE_TARGET_COUNT
        chance_to_pick_blue = ALL_ABOARD_SOLO_CHANCE_TO_PICK_BLUE
    else:
        target_count = ALL_ABOARD_REMOTE_TARGET_COUNT
        chance_to_pick_blue = ALL_ABOARD_CHANCE_TO_PICK_BLUE
    selected = {source}
    blue_picks = 0
    for _shot in range(target_count):
        pool = None
        if pools["blue"] and (
            blue_picks < ALL_ABOARD_MIN_BLUES_TO_PICK
            or rng.random() * 100.0 < chance_to_pick_blue
        ):
            pool = pools["blue"]
            blue_picks += 1
        elif pools["red"]:
            pool = pools["red"]
        elif pools["neutral"]:
            pool = pools["neutral"]
        elif pools["blue"]:
            pool = pools["blue"]
            blue_picks += 1
        if not pool:
            break
        selected.add(pool.pop(rng.randrange(len(pool))))
    return selected


def _special_effect_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
    special: int,
    excluded_cells: set[tuple[int, int]] | None = None,
) -> set[tuple[int, int]]:
    size = len(board)
    if special == SPECIAL_KNIGHT:
        return _knight_effect_cells(board, special_board, row, col)
    if special == SPECIAL_CLEO_BUG:
        return set()
    if special == SPECIAL_JOOJOO_SKULL:
        return _joojoo_skull_effect_cells(board, special_board, row, col)
    if special == SPECIAL_LIGHTNING:
        return _lightning_effect_cells(
            board,
            row,
            col,
            excluded_cells=excluded_cells,
        )
    if special == SPECIAL_CROSSHAIR:
        return _crosshair_effect_cells(
            board,
            special_board,
            row,
            col,
            excluded_cells=excluded_cells,
        )
    if special == SPECIAL_ALL_ABOARD_BANDIT:
        return _all_aboard_effect_cells(
            board,
            row,
            col,
            excluded_cells=excluded_cells,
        )
    if special == SPECIAL_ZANY_ZAPPER_1:
        return {
            (other_row, other_col)
            for other_row in range(size)
            for other_col in range(size)
            if (other_row == row or other_col == col)
            and _is_board_piece(board[other_row][other_col])
        }
    if is_vinnie_se_heart_special(special):
        colors = set(vinnie_se_heart_colors(special))
        # A Vinnie SE heart clears its colour pair off the board, but it does
        # NOT take out any other heart that happens to carry one of those
        # colours -- in game those hearts survive the wipe.  See
        # _is_heart_special() for the 2026-08-22 captures behind the rule.
        return {
            (other_row, other_col)
            for other_row, values in enumerate(board)
            for other_col, value in enumerate(values)
            if not _is_heart_special(special_board[other_row][other_col])
            and any(
                _cell_matches_color(
                    value,
                    special_board[other_row][other_col],
                    color,
                )
                for color in colors
            )
        }
    if special == SPECIAL_HEART:
        color = board[row][col]
        if not _is_board_piece(color):
            return set()
        # Same rule as the Vinnie SE pair heart above: the colour wipe walks
        # past every other heart on the board.
        return {
            (other_row, other_col)
            for other_row, values in enumerate(board)
            for other_col, value in enumerate(values)
            if (
                (other_row, other_col) == (row, col)
                or not _is_heart_special(special_board[other_row][other_col])
            )
            and _cell_matches_color(value, special_board[other_row][other_col], color)
        }
    if special == SPECIAL_COLOR_CRYSTAL:
        color = board[row][col]
        if not _is_board_piece(color):
            return set()
        # A colour crystal DOES take out same-coloured crystals: matching one
        # purple crystal clears every purple tile and every purple crystal.
        return {
            (other_row, other_col)
            for other_row, values in enumerate(board)
            for other_col, value in enumerate(values)
            if _cell_matches_color(value, special_board[other_row][other_col], color)
        }
    if special == SPECIAL_HORIZONTAL:
        return {(row, other_col) for other_col in range(size) if _is_board_piece(board[row][other_col])}
    if special == SPECIAL_VERTICAL:
        return {(other_row, col) for other_row in range(size) if _is_board_piece(board[other_row][col])}
    if special in DIRECTIONAL_FIREWORK_SPECIALS:
        row_step, col_step = FIREWORK_DIRECTION_STEPS[special]
        effect_cells = set()
        target_row = row
        target_col = col
        while 0 <= target_row < size and 0 <= target_col < size:
            if _is_board_piece(board[target_row][target_col]):
                effect_cells.add((target_row, target_col))
            target_row += row_step
            target_col += col_step
        return effect_cells
    if special == SPECIAL_BOMB or _is_created_special(special):
        return _bomb_effect_cells(board, row, col)
    return set()


def _is_laser_mode(mode: str | None) -> bool:
    return normalize_game_mode(mode) is GameMode.LASER


def _is_arcade_man_mode(mode: str | None) -> bool:
    return normalize_game_mode(mode) is GameMode.ARCADE_MAN


def _line_destruction_cells(
    board: list[list[int]],
    matches: list[MatchGroup],
    sweep_rows: bool | None = None,
    sweep_columns: bool | None = None,
) -> set[tuple[int, int]]:
    """Cells swept by destroyRowOnHorizontalMatch / destroyColumnOnVerticalMatch.

    The two engine flags are independent, so each axis is asked for separately.
    A compound match (L / T / cross / square) spans both axes and therefore
    sweeps whichever of them the ruleset enables. Passing ``None`` reads the
    currently active flags (see ``line_destruction_active``).

    Only real board pieces are added -- empty and off-board cells are skipped so
    the cleared count is not inflated.
    """
    if sweep_rows is None:
        sweep_rows = _DESTROY_ROW_ON_HORIZONTAL_MATCH
    if sweep_columns is None:
        sweep_columns = _DESTROY_COLUMN_ON_VERTICAL_MATCH
    if not sweep_rows and not sweep_columns:
        return set()

    size = len(board)
    cells: set[tuple[int, int]] = set()

    def _sweep_row(row: int) -> None:
        for col in range(size):
            if _is_board_piece(board[row][col]):
                cells.add((row, col))

    def _sweep_col(col: int) -> None:
        for row in range(size):
            if _is_board_piece(board[row][col]):
                cells.add((row, col))

    for match in matches:
        rows = {row for row, _ in match.cells}
        cols = {col for _, col in match.cells}
        horizontal = len(rows) == 1
        vertical = len(cols) == 1
        # A compound match is neither purely horizontal nor purely vertical, so
        # it triggers both rules; a straight match triggers only its own axis.
        compound = not horizontal and not vertical
        if sweep_rows and (horizontal or compound):
            for row in rows:
                _sweep_row(row)
        if sweep_columns and (vertical or compound):
            for col in cols:
                _sweep_col(col)
    return cells


def _arcade_man_cells(
    board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    """Cells swept when Arcade Man explodes a match's whole row or column.

    A horizontal match (cells sharing one row) detonates that entire row; a
    vertical match (cells sharing one column) detonates that entire column. A
    compound match (L / T / cross / square) spans both, so every row and column
    its cells occupy is detonated. Only real board pieces are added -- empty and
    off-board cells are skipped so the cleared count is not inflated. The native
    MatchLineBoard applies this in AfterPerformedSwap, so only direct matches
    trigger it.

    MatchLineBoard does this itself, with both engine line-destruction flags
    off, so this is that flag pair applied unconditionally from the mode.

    Measured 2026-08-21 (Debug/unmapped_modes/arcade-man): a vertical match of
    four in column 4 scored 33, which is every one of the seven tiles in that
    column at its own colour value (5+4+5+5+5+5+4), not the 20 the four matched
    tiles are worth. The match-4 special landed on the swapped cell and then
    fell to the bottom of the emptied column.
    """
    return _line_destruction_cells(board, matches, sweep_rows=True, sweep_columns=True)


def _frozen_feud_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    """Every piece in the row of a frozen tile the match just broke.

    Read out of libil2cpp.so 2026-08-21: ``FrozenFeudBoard`` overrides
    ``GetAreaOfBoardSpecialEffect`` and its whole body resolves to
    ``BoardModel.GetX(row, 0, 1, null)`` -- the entire row of the tile that was
    hit, not a blast shape around it. The tile itself is an ordinary matchable
    BoardSpecial (three of them, ``FROZEN_TILES_COUNT``), which the memory
    adapter already hands over as ``SPECIAL_MODE_TARGET``.

    Unlike Arcade Man or Drillin' Down this is *not* limited to the performed
    swap: the hook is the board special's own area of effect, so a frozen tile
    broken by a cascade clears its row just the same.
    """
    cells: set[tuple[int, int]] = set()
    for match in matches:
        for row, col in match.cells:
            if not (0 <= row < len(special_board)):
                continue
            special_row = special_board[row]
            if not (0 <= col < len(special_row)):
                continue
            if not is_mode_target_special(special_row[col]):
                continue
            board_row = board[row] if 0 <= row < len(board) else ()
            for target_col, value in enumerate(board_row):
                if _is_board_piece(value):
                    cells.add((row, target_col))
    return cells


def _drillin_down_cells(
    board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    """Every matched tile drills through all board pieces below it.

    The matched cells themselves are included because they explode normally.
    For a vertical match, overlapping drill paths naturally collapse into the
    one column segment beginning at the highest matched tile. The mechanic is
    applied only to the match layer created by the performed swap.
    """
    cells: set[tuple[int, int]] = set()
    for match in matches:
        for match_row, col in match.cells:
            for row in range(match_row, len(board)):
                if 0 <= col < len(board[row]) and _is_board_piece(board[row][col]):
                    cells.add((row, col))
    return cells


def _laser_effect_paths(
    board: list[list[int]],
    matches: list[MatchGroup],
) -> list[tuple[tuple[int, int], ...]]:
    """Connect each direct match to the nearest same-colour tile on each ray.

    LightsabersBoard.AfterPerformedSwap (0x578a978..0x578a988) abandons
    a ray when it reaches ANY original combo point, before adding its path.
    Both colours emit on a double match, but their matched cells block rays.
    """
    size = len(board)
    paths = []
    matched_cells = {cell for match in matches for cell in match.cells}
    # Native Point directions: (0,+1), (0,-1), (+1,0), (-1,0).
    # Keep the path order: Manual laser combos feed the UFO colour list.
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for match in matches:
        color = match.color
        if not _is_board_piece(color):
            continue
        for row, col in sorted(match.cells):
            for row_step, col_step in directions:
                path = []
                target_row = row + row_step
                target_col = col + col_step
                while 0 <= target_row < size and 0 <= target_col < size:
                    if (target_row, target_col) in matched_cells:
                        break
                    if not _is_board_piece(board[target_row][target_col]):
                        break
                    path.append((target_row, target_col))
                    if board[target_row][target_col] == color:
                        paths.append(tuple(path))
                        break
                    target_row += row_step
                    target_col += col_step
    return paths


def _laser_effect_cells(
    board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    return {cell for path in _laser_effect_paths(board, matches) for cell in path}


def _knight_effect_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
) -> set[tuple[int, int]]:
    size = len(board)
    offsets = (
        (-2, -1),
        (-2, 1),
        (-1, -2),
        (-1, 2),
        (1, -2),
        (1, 2),
        (2, -1),
        (2, 1),
    )
    candidates = []
    for row_offset, col_offset in offsets:
        target_row = row + row_offset
        target_col = col + col_offset
        if not (0 <= target_row < size and 0 <= target_col < size):
            continue
        if not _is_board_piece(board[target_row][target_col]):
            continue
        candidates.append((target_row, target_col))

    candidates.sort(
        key=lambda cell: (
            special_board[cell[0]][cell[1]] == EMPTY,
            board[cell[0]][cell[1]] != BLUE,
            cell[0],
            cell[1],
        )
    )
    return set(candidates[:3])


def _bomb_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
) -> set[tuple[int, int]]:
    size = len(board)
    offsets = {(0, 0)}
    for distance in (1, 2):
        offsets.update(
            {
                (-distance, 0),
                (distance, 0),
                (0, -distance),
                (0, distance),
            }
        )
    offsets.update({(-1, -1), (-1, 1), (1, -1), (1, 1)})
    return {
        (row + row_offset, col + col_offset)
        for row_offset, col_offset in offsets
        if 0 <= row + row_offset < size
        and 0 <= col + col_offset < size
        and _is_board_piece(board[row + row_offset][col + col_offset])
    }


SPECIAL_INTENT_NAMES = {
    SPECIAL_HORIZONTAL: "horizontal",
    SPECIAL_VERTICAL: "vertical",
    SPECIAL_BOMB: "bomb",
    SPECIAL_LIGHTNING: "lightning",
    SPECIAL_CROSSHAIR: "crosshair",
    SPECIAL_HEART: "heart",
    SPECIAL_KNIGHT: "knight",
    SPECIAL_CLEO_BUG: "cleo_bug",
    SPECIAL_COLOR_CRYSTAL: "color_crystal",
    SPECIAL_DISCO_BALL: "disco",
    SPECIAL_MUSHROOM: "mushroom",
    SPECIAL_ALL_ABOARD_BANDIT: "all_aboard_bandit",
    SPECIAL_JOOJOO_SKULL: "joojoo_skull",
    SPECIAL_FROGGY_LOTUS: "froggy_lotus",
    SPECIAL_FIREWORK_LEFT: "firework_left",
    SPECIAL_FIREWORK_RIGHT: "firework_right",
    SPECIAL_FIREWORK_UP: "firework_up",
    SPECIAL_FIREWORK_DOWN: "firework_down",
    SPECIAL_ZANY_ZAPPER_1: "zany_zapper_1",
    SPECIAL_ZANY_ZAPPER_2: "zany_zapper_2",
    SPECIAL_RED_BLUE_TILE: "red_blue_tile",
    SPECIAL_XTRA_MOVE_TILE: "xtra_move",
    SPECIAL_SPRAY_SE: "spray_se",
    SPECIAL_SWEEP_SE_BROOM: "sweep_se_broom",
}


def _intent_cell(cell: tuple[int, int]) -> list[int]:
    return [int(cell[0]), int(cell[1])]


def _intent_cells(cells) -> list[list[int]]:
    return [_intent_cell(cell) for cell in sorted(cells)]


def _special_intent_name(special: int) -> str:
    if _is_created_special(special):
        return "created_special"
    if is_red_blue_tile_special(special):
        return "red_blue_tile"
    if is_vinnie_se_heart_special(special):
        return "vinnie_se_heart"
    return SPECIAL_INTENT_NAMES.get(special, f"special_{special}")


def _append_match_intent_events(intent_events, matches, cascade_number: int) -> None:
    if intent_events is None:
        return
    for match in matches:
        intent_events.append(
            {
                "type": "match",
                "cascade": int(cascade_number),
                "kind": match.kind,
                "color": int(match.color),
                "cells": _intent_cells(match.cells),
                "tile_count": len(match.cells),
            }
        )


LIGHTNING_RANDOM_REFILL_REASON = "lightning_random_refill"
COLOR_CLEAR_RANDOM_REFILL_REASON = "color_clear_random_refill"
CROSSHAIR_RANDOM_REFILL_REASON = "crosshair_random_refill"
ALL_ABOARD_RANDOM_REFILL_REASON = "all_aboard_random_refill"
BOARD_WIPE_REFILL_REASON = "board_wipe_or_unknown_refill"
# The UFO abduction gets its own reason so it stays OUT of
# DETERMINISTIC_WIPE_REFILL_REASONS below: unlike Color Crush or a heart, the
# colour it takes is predicted rather than known, so the board it leaves behind
# is a guess and the cascade it feeds cannot promise an extra move.
UFO_ABDUCTION_REFILL_REASON = "ufo_abduction_refill"
UFO_DIRECTIONAL_REFILL_REASON = "ufo_directional_color_clear"

# Boundaries whose *cleared cell set* is fully determined (heart / Vinnie SE
# heart / Color Crush all wipe fixed colours).  The tiles that refill from off
# board are unknown, but the simulator never matches against them -- gravity
# only re-stacks pieces we can already see, and `_drop_boards_with_origins`
# leaves the top rows EMPTY.  So the single cascade right after such a wipe is
# made of known pieces and is guaranteed to happen in game.  Only random-TARGET
# specials (lightning, crosshair) make the post board itself a guess.
DETERMINISTIC_WIPE_REFILL_REASONS = frozenset(
    {
        COLOR_CLEAR_RANDOM_REFILL_REASON,
        BOARD_WIPE_REFILL_REASON,
    }
)

# Board-wide random/colour-clear specials empty scattered cells that refill with
# unknown random tiles. Any cascade past that point is a guess against tiles we
# cannot see, so its match-4s are NOT guaranteed extra moves. Lightning zaps 13
# random remote pieces; the heart and the colour-pair Vinnie SE heart clear fixed
# colours but still scatter-wipe large areas (a Vinnie pair routinely clears ~40%
# of the board and chains other specials), so their follow-up cascades are just
# as unreliable. Disco is deliberately excluded -- it
# clears the single colour the player picks and its follow-up four is treated as
# real (see the disco extra-move tests). Localised clears (bomb, knight, rockets)
# drop known tiles predictably, so their cascades stay trustworthy and are
# likewise excluded.
_COLOR_CLEAR_REFILL_REASONS = {
    "lightning": LIGHTNING_RANDOM_REFILL_REASON,
    "heart": COLOR_CLEAR_RANDOM_REFILL_REASON,
    "vinnie_se_heart": COLOR_CLEAR_RANDOM_REFILL_REASON,
    "crosshair": CROSSHAIR_RANDOM_REFILL_REASON,
    "all_aboard_bandit": ALL_ABOARD_RANDOM_REFILL_REASON,
}


def _color_clear_refill_reason(events: list[dict], start_index: int) -> str | None:
    reason = None
    for event in events[start_index:]:
        if event.get("type") != "special_effect":
            continue
        matched = _COLOR_CLEAR_REFILL_REASONS.get(event.get("special"))
        if _ENGINE_REFILL is not None and matched == COLOR_CLEAR_RANDOM_REFILL_REASON:
            # Hearts choose fixed colors; exact refill resolves the only
            # unknown part. Random-target specials retain their boundary.
            continue
        if matched == LIGHTNING_RANDOM_REFILL_REASON:
            # Lightning's reason wins whenever it fires in the cascade so the
            # existing lightning_random_refill behaviour/tests stay intact.
            return matched
        if matched is not None:
            reason = matched
    return reason


def _append_uncertain_refill_boundary(
    intent_events: list[dict] | None,
    cascade_number: int,
    reason: str,
) -> None:
    if intent_events is None:
        return
    boundary = {
        "type": "uncertain_refill_boundary",
        "after_cascade": int(cascade_number),
        "reason": reason,
    }
    if boundary not in intent_events:
        intent_events.append(boundary)


def _mark_color_clear_random_refill_boundary(
    intent_events: list[dict] | None,
    start_index: int,
    cascade_number: int,
) -> str | None:
    """Record the refill boundary and return its reason (None when no boundary)."""
    if intent_events is None:
        return None
    reason = _color_clear_refill_reason(intent_events, start_index)
    if reason is None:
        return None
    _append_uncertain_refill_boundary(
        intent_events,
        cascade_number,
        reason,
    )
    return reason


def _specials_fired_only_by_extra_matches(
    intent_events: list[dict],
    start_index: int,
    matches: list[MatchGroup],
) -> bool:
    """Whether every special activated in this cascade traces back to a
    special sitting inside one of its four-plus matches."""
    extra_cells = {
        (int(cell[0]), int(cell[1]))
        for match in matches
        if len(match.cells) >= 4
        for cell in match.cells
    }
    if not extra_cells:
        return False
    activated = []
    triggered_by = {}
    for event in intent_events[start_index:]:
        cell = event.get("cell")
        if cell is None:
            continue
        cell = (int(cell[0]), int(cell[1]))
        if event.get("type") == "special_activation":
            activated.append(cell)
        elif event.get("type") == "special_effect":
            for target in event.get("activated_specials") or ():
                triggered_by.setdefault((int(target[0]), int(target[1])), set()).add(cell)
    if not activated:
        return False
    reached = {cell for cell in activated if cell in extra_cells}
    changed = True
    while changed:
        changed = False
        for cell in activated:
            if cell not in reached and triggered_by.get(cell, set()) & reached:
                reached.add(cell)
                changed = True
    return all(cell in reached for cell in activated)


def _count_vinnie_se_heart_activations(events: list[dict], start_index: int = 0) -> int:
    return sum(
        1
        for event in events[start_index:]
        if (
        event.get("type") == "special_activation"
        and event.get("special") == "vinnie_se_heart"
        )
    )


def _events_include_vinnie_se_heart_activation(events: list[dict], start_index: int) -> bool:
    return _count_vinnie_se_heart_activations(events, start_index) > 0


def _special_chain_targets(board, special_board, effect_cells, source_cell, excluded_cells=None):
    excluded_cells = excluded_cells or set()
    return [
        cell
        for cell in sorted(effect_cells)
        if cell != source_cell
        and cell not in excluded_cells
        and not is_mode_target_special(special_board[cell[0]][cell[1]])
        and special_board[cell[0]][cell[1]] not in {
            EMPTY,
            SPECIAL_BILLIE_DRONE,
            SPECIAL_FROGGY_LOTUS,
            SPECIAL_ZANY_ZAPPER_2,
            SPECIAL_XTRA_MOVE_TILE,
            SPECIAL_SPRAY_SE,
            SPECIAL_SWEEP_SE_BROOM,
        }
    ]


def _bomb_bomb_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
) -> set[tuple[int, int]]:
    size = len(board)
    return {
        (row + row_offset, col + col_offset)
        for row_offset in range(-2, 3)
        for col_offset in range(-2, 3)
        if (abs(row_offset), abs(col_offset)) != (2, 2)
        and 0 <= row + row_offset < size
        and 0 <= col + col_offset < size
        and _is_board_piece(board[row + row_offset][col + col_offset])
    }


def _resolve_special_chain(
    board: list[list[int]],
    special_board: list[list[int]],
    initial_cells: set[tuple[int, int]],
    suppressed_special_effect_cells: set[tuple[int, int]] | None = None,
    intent_events: list[dict] | None = None,
    cascade_number: int = 1,
    random_refill_tracker: list[bool] | None = None,
    crosshair_tracker: list[set[tuple[int, int]]] | None = None,
    consumed_disco_cells: set[tuple[int, int]] | None = None,
) -> tuple[set[tuple[int, int]], int]:
    size = len(board)
    suppressed_special_effect_cells = suppressed_special_effect_cells or set()
    # A disco ball is a fixed piece: nothing but its own swap uses it up. A
    # bomb, line or lightning that reaches one leaves it standing (confirmed
    # by the player 2026-09-14, and by the recording: the 23:26:38 Brocco move
    # dragged one ball onto a bomb, the simulator had the blast fire and
    # remove the second ball, and the snapshots show it still on (6,1)
    # afterwards). Removing it made every plan after such a move blind to the
    # second free swap. `consumed_disco_cells` is the ball being swapped.
    consumed_disco_cells = consumed_disco_cells or set()

    def _fixed_disco(cell: tuple[int, int]) -> bool:
        return (
            special_board[cell[0]][cell[1]] == SPECIAL_DISCO_BALL
            and cell not in consumed_disco_cells
        )

    # A Cleo figure is not damageable either (raw slot damageable=False): every
    # line that crossed one in the recorded moves-multiplier games left it
    # standing and made one hole less (+63 draws = 3 + 6 holes, not 3 + 7).
    def _fixed_cleo(cell: tuple[int, int]) -> bool:
        return (
            special_board[cell[0]][cell[1]] == SPECIAL_CLEO_BUG
            and cell not in initial_cells
        )

    def _clearable(cell: tuple[int, int]) -> bool:
        row, col = cell
        return (
            0 <= row < size
            and 0 <= col < size
            and not _fixed_disco(cell)
            and not _fixed_cleo(cell)
            and (
                _is_board_piece(board[row][col])
                or special_board[row][col] not in {
                    EMPTY,
                    SPECIAL_BILLIE_DRONE,
                    SPECIAL_FROGGY_LOTUS,
                }
            )
        )

    cleared = {cell for cell in initial_cells if _clearable(cell)}
    activated = set()
    queue = list(cleared)

    while queue:
        row, col = queue.pop(0)
        special = special_board[row][col]
        if special == SPECIAL_ZANY_ZAPPER_2:
            special_board[row][col] = SPECIAL_ZANY_ZAPPER_1
            cleared.discard((row, col))
            continue
        if is_mode_target_special(special) or special in {
            EMPTY,
            SPECIAL_FROGGY_LOTUS,
            SPECIAL_XTRA_MOVE_TILE,
            SPECIAL_SPRAY_SE,
            SPECIAL_SWEEP_SE_BROOM,
        } or (row, col) in activated:
            continue
        activated.add((row, col))
        if intent_events is not None:
            intent_events.append(
                {
                    "type": "special_activation",
                    "cascade": int(cascade_number),
                    "special": _special_intent_name(special),
                    "cell": _intent_cell((row, col)),
                }
            )
        if (row, col) in suppressed_special_effect_cells:
            continue
        if special == SPECIAL_LIGHTNING and random_refill_tracker is not None:
            random_refill_tracker.append(True)
        effect_cells = _special_effect_cells(
            board,
            special_board,
            row,
            col,
            special,
            excluded_cells=cleared,
        )
        # Same filter as the initial set (2026-09-22): a chained Joo Joo skull
        # ray takes every non-EMPTY special cell, BLOCKED lotus / Billie drone
        # cells included, and the clear below would then have turned those
        # into EMPTY holes.
        effect_cells = {cell for cell in effect_cells if _clearable(cell)}
        if intent_events is not None and _ENGINE_REFILL is not None:
            intent_events[-1]["effect_cells"] = sorted(effect_cells)
        if special == SPECIAL_CROSSHAIR and crosshair_tracker is not None:
            crosshair_tracker.append(set(effect_cells))
        chain_targets = _special_chain_targets(
            board,
            special_board,
            effect_cells,
            (row, col),
            excluded_cells=suppressed_special_effect_cells,
        )
        if intent_events is not None:
            if special == SPECIAL_CROSSHAIR:
                # Up to CROSSHAIR_BLUE_CELLS, limited by the blue still standing.
                reachable_blue = sum(
                    1
                    for blue_row, values in enumerate(board)
                    for blue_col, value in enumerate(values)
                    if value == BLUE and (blue_row, blue_col) not in cleared
                )
                effect_blue_cells = (
                    min(CROSSHAIR_BLUE_CELLS, reachable_blue)
                    if is_booster_charge_color(BLUE)
                    else 0
                )
            else:
                effect_blue_cells = sum(
                    1
                    for effect_row, effect_col in effect_cells
                    if is_booster_charge_color(board[effect_row][effect_col])
                )
            intent_events.append(
                {
                    "type": "special_effect",
                    "cascade": int(cascade_number),
                    "special": _special_intent_name(special),
                    "cell": _intent_cell((row, col)),
                    "cleared_cells": len(effect_cells),
                    "blue_cells": effect_blue_cells,
                    "activated_specials": _intent_cells(chain_targets),
                }
            )
        for effect_cell in effect_cells:
            if effect_cell not in cleared:
                cleared.add(effect_cell)
                queue.append(effect_cell)

    return cleared, len(activated)


def _merge_color_counts(total: dict[int, float], increment: dict[int, float]) -> dict[int, float]:
    for color, count in increment.items():
        total[color] = total.get(color, 0.0) + count
    return total


def _red_blue_tile_cleared_color(
    board_value: int,
    matched_colors: set[int] | None,
) -> int:
    matched_colors = matched_colors or set()
    if BLUE in matched_colors:
        return BLUE
    if RED in matched_colors:
        return RED
    if board_value in RED_BLUE_TILE_COLORS:
        return board_value
    return BLUE


def _cleared_color_counts(
    board: list[list[int]],
    special_board: list[list[int]],
    cleared: set[tuple[int, int]],
    matched_colors_by_cell: dict[tuple[int, int], set[int]] | None = None,
) -> dict[int, float]:
    matched_colors_by_cell = matched_colors_by_cell or {}
    counts = {}
    for row, col in cleared:
        color = board[row][col]
        if special_board[row][col] == SPECIAL_RED_BLUE_TILE:
            color = _red_blue_tile_cleared_color(
                color,
                matched_colors_by_cell.get((row, col)),
            )
        if not _is_board_piece(color):
            continue
        counts[color] = counts.get(color, 0.0) + 1.0
    return counts


def _color_crush_cells(
    board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    """Every board tile sharing a color with a crushing match (inert colours excluded)."""
    inert = color_crush_inert_colors()
    crush_colors = {
        match.color
        for match in matches
        if match.color not in inert and _is_normal_color(match.color)
    }
    if not crush_colors:
        return set()
    cells = set()
    for row, line in enumerate(board):
        for col, value in enumerate(line):
            if value in crush_colors:
                cells.add((row, col))
    return cells


def _ufo_abduction_colors(
    matched_colors,
    already_abducted: set[int],
    charges: int,
) -> list[int]:
    """The next colours the UFO eyes lock onto, in the order they were matched.

    One eye takes one colour, and a colour already abducted cannot be taken
    again -- the board no longer holds it. ``charges`` is the budget for the
    call: every armed eye, since the direct destroy can lock all of them at
    once (UFO_MAX_COLORS_PER_MOVE).
    """
    if charges <= 0:
        return []
    picked: list[int] = []
    for color in matched_colors:
        # Passive eyes use the ordered distinct-colour list, not the active
        # beam's allowPickingBlues filter. Specials are filtered at the wipe.
        if color not in UFO_PASSIVE_PICKABLE_COLORS:
            continue
        if color in already_abducted or color in picked:
            continue
        picked.append(color)
        if len(picked) >= charges:
            break
    return picked


def _ufo_swap_ordered_matches(
    matches: list[MatchGroup],
    swap_cells: tuple[tuple[int, int], ...],
) -> list[MatchGroup]:
    """Match colours ordered the way the eye locks onto them.

    ValidSwapPerformed builds its testSlots with position2 (destination) first
    at 0x574a730, then position1. GetAllCombos/GetCombosFromTestList preserve
    that order; BeforeCombosDestroy moves swap combos ahead of other effects
    and collects their distinct colours. One eye therefore takes the dragged
    piece's destination match, including when that match is blue. Two eyes
    can take both distinct colours. Board scan order must not override this.
    """
    if not swap_cells:
        return list(matches)
    ranked: list[tuple[int, int]] = []
    for index, match in enumerate(matches):
        cells = set(match.cells)
        for priority, swap_cell in enumerate(swap_cells):
            if swap_cell in cells:
                break
        else:
            priority = len(swap_cells)
        ranked.append((priority, index))
    ranked.sort()
    return [matches[index] for _priority, index in ranked]


def _ufo_blast_colors(board_before_clear, events, matches) -> list[int]:
    """Colours of the pieces specials destroyed, as the eye's next choices.

    Recorded UFO SE, 2 eyes (Debug/research 20261102): the second colour comes
    from the first special set off, scanning its cells columns right to left
    and each from the top; a chained special follows. A rocket or bomb goes in
    as its own combo, like a laser ray.
    """
    matched = {cell for match in matches for cell in match.cells}
    colors = []
    for event in events:
        if event.get("type") == "special_activation":
            cells = [tuple(cell) for cell in event.get("effect_cells") or ()]
            blast = sorted(set(cells) - matched, key=lambda cell: (-cell[1], cell[0]))
            colors += [board_before_clear[row][col] for row, col in blast]
    return colors


def _ufo_swap_ordered_colors(
    matches: list[MatchGroup],
    swap_cells: tuple[tuple[int, int], ...],
) -> list[int]:
    return [match.color for match in _ufo_swap_ordered_matches(matches, swap_cells)]


def _ufo_laser_colors(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
    swap_cells: tuple[tuple[int, int], ...],
) -> list[int]:
    """Victim colours in native Manual laser-combo order, before gravity.

    LightsabersBoard appends each ray as ComboType.Manual (0x578aaa0).
    BeforeCombosDestroy enumerates its pieces when its combo colour is unset,
    in path order (0x57e264c..0x57e2738), skipping Cleo pieces. Ray victims,
    not just the matched colour, can therefore supply the second eye.
    """
    ordered = _ufo_swap_ordered_matches(matches, swap_cells)
    return [int(board[row][col])
            for path in _laser_effect_paths(board, ordered)
            for row, col in path
            if special_board[row][col] != SPECIAL_CLEO_BUG]


def _ufo_abduction_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    colors,
) -> set[tuple[int, int]]:
    """Every ordinary tile of an abducted colour.

    Specials are not abducted -- a bomb or line piece keeps its cell even when
    the eye takes its colour -- so cells carrying a special are skipped.
    """
    targets = set(colors)
    if not targets:
        return set()
    cells = set()
    for row, line in enumerate(board):
        for col, value in enumerate(line):
            if value in targets and not special_board[row][col]:
                cells.add((row, col))
    return cells


def _match_has_vertical_run(match: MatchGroup) -> bool:
    """Whether a match group contains at least three cells in one column."""
    column_counts: dict[int, int] = {}
    for _row, col in match.cells:
        column_counts[col] = column_counts.get(col, 0) + 1
    return any(count >= 3 for count in column_counts.values())


def _match_destroy_colors(
    special_board: list[list[int]],
    matches: list[MatchGroup],
    vertical_only: bool = True,
) -> set[int]:
    """Colors wiped by a destroy-color rule, hearts contributing both colors.

    `vertical_only` separates the two mutations that use this: Vertical Matches
    Destroy Color looks at matches with a vertical run, Matches Explode Color at
    every direct match.
    """
    destroy_colors: set[int] = set()
    for match in matches:
        if vertical_only and not _match_has_vertical_run(match):
            continue
        if _is_normal_color(match.color):
            destroy_colors.add(match.color)
        for row, col in match.cells:
            special = special_board[row][col]
            if is_vinnie_se_heart_special(special):
                destroy_colors.update(vinnie_se_heart_colors(special))
    return destroy_colors


def _vertical_match_destroy_colors(
    special_board: list[list[int]],
    matches: list[MatchGroup],
) -> set[int]:
    """Colors wiped by vertical matches, including both colors of Vinnie SE hearts."""
    return _match_destroy_colors(special_board, matches, vertical_only=True)


def _destroy_color_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
    vertical_only: bool = True,
) -> set[tuple[int, int]]:
    """Every tile matching a color selected by a vertical match.

    Color-flexible Vinnie SE hearts match either encoded color even when their
    board value is the other color. Matching ordinary hearts and other specials
    stay in the initial clear set so the normal special-chain resolver activates
    them instead of treating them as inert colored tiles.
    """
    destroy_colors = _match_destroy_colors(special_board, matches, vertical_only)
    if not destroy_colors:
        return set()
    return {
        (row, col)
        for row, values in enumerate(board)
        for col, value in enumerate(values)
        if any(
            _cell_matches_color(value, special_board[row][col], color)
            for color in destroy_colors
        )
    }


def _vertical_match_destroy_color_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
) -> set[tuple[int, int]]:
    """Every tile matching a color selected by a vertical match."""
    return _destroy_color_cells(board, special_board, matches, vertical_only=True)


def _funky_tile_effect_cells(
    board: list[list[int]],
    row: int,
    col: int,
) -> set[tuple[int, int]]:
    """Funky Tile blast: its cell plus two cells in each cardinal direction."""
    size = len(board)
    cells = {(row, col)}
    for distance in (1, 2):
        for row_step, col_step in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            target = (row + row_step * distance, col + col_step * distance)
            if 0 <= target[0] < size and 0 <= target[1] < size:
                cells.add(target)
    return cells


def _apply_funky_tile_matches(
    board: list[list[int]],
    matches: list[MatchGroup],
    active_funky_cells: set[tuple[int, int]] | None,
    intent_events: list[dict] | None,
    cascade_number: int,
) -> set[tuple[int, int]]:
    """Return blast cells for Funky markers directly included in a match.

    A marker is consumed after firing, but an untouched fixed board marker may
    still fire from a later cascade if falling pieces form a match through it.
    Being hit by another explosion alone does not activate it: the rule is a
    match *on* the marked cell.
    """
    if not active_funky_cells:
        return set()
    matched_cells = {cell for match in matches for cell in match.cells}
    triggered = active_funky_cells.intersection(matched_cells)
    if not triggered:
        return set()

    effect_cells = set()
    for row, col in sorted(triggered):
        blast = _funky_tile_effect_cells(board, row, col)
        effect_cells.update(blast)
        if intent_events is not None:
            intent_events.append(
                {
                    "type": "funky_tile_activation",
                    "cascade": int(cascade_number),
                    "cell": _intent_cell((row, col)),
                    "effect_cells": _intent_cells(blast),
                }
            )
    active_funky_cells.difference_update(triggered)
    return effect_cells


def _xtra_move_cells(
    special_board: list[list[int]],
    cleared: set[tuple[int, int]],
) -> list[tuple[int, int]]:
    return [
        (row, col)
        for row, col in sorted(cleared)
        if special_board[row][col] == SPECIAL_XTRA_MOVE_TILE
    ]


def _clear_cells_with_specials(
    board: list[list[int]],
    special_board: list[list[int]],
    initial_cells: set[tuple[int, int]],
    created_cells: dict[tuple[int, int], int] | None = None,
    created_special_types: dict[tuple[int, int], int] | None = None,
    suppressed_special_effect_cells: set[tuple[int, int]] | None = None,
    intent_events: list[dict] | None = None,
    cascade_number: int = 1,
    random_refill_tracker: list[bool] | None = None,
    matched_colors_by_cell: dict[tuple[int, int], set[int]] | None = None,
    extra_move_counter: list[int] | None = None,
    consumed_disco_cells: set[tuple[int, int]] | None = None,
) -> tuple[int, int, set[tuple[int, int]], int, int, int, bool, dict[int, float]]:
    created_cells = created_cells or {}
    created_special_types = created_special_types or {}
    crosshair_hits: list[set[tuple[int, int]]] = []
    cleared, activated_specials = _resolve_special_chain(
        board,
        special_board,
        initial_cells,
        suppressed_special_effect_cells=suppressed_special_effect_cells,
        intent_events=intent_events,
        cascade_number=cascade_number,
        random_refill_tracker=random_refill_tracker,
        crosshair_tracker=crosshair_hits,
        consumed_disco_cells=consumed_disco_cells,
    )
    color_counts = _cleared_color_counts(
        board,
        special_board,
        cleared,
        matched_colors_by_cell,
    )
    # Blue only counts while it actually charges: an engine charge table
    # without blue (Energized -- PlayerControl.energyColors never lists blue,
    # measured across all 183 snapshots on 2026-08-24) replaces the default
    # outright, and crediting blue anyway is exactly the misplay the table
    # exists to prevent. The crosshair's sampled-blue estimate is charge
    # accounting too, so it is gated with it.
    blue_charges = is_booster_charge_color(BLUE)
    blue_cells = int(color_counts.get(BLUE, 0.0)) if blue_charges else 0
    if crosshair_hits and blue_charges:
        # Each crosshair clears up to CROSSHAIR_BLUE_CELLS blue, so replace
        # whatever blue its random targets happened to contain -- but cap the
        # result at the blue the board can still supply. The cells other clears
        # already consumed are gone, so only the rest is reachable.
        # color_counts keeps the sampled colours: it feeds per-colour scoring,
        # which is about the pieces actually cleared, not the booster charge.
        crosshair_cells = set().union(*crosshair_hits) & cleared
        sampled_blue = sum(
            1 for row, col in crosshair_cells if board[row][col] == BLUE
        )
        other_blue = max(0, blue_cells - sampled_blue)
        board_blue = sum(1 for values in board for value in values if value == BLUE)
        reachable_blue = max(0, board_blue - other_blue)
        blue_cells = other_blue + min(
            CROSSHAIR_BLUE_CELLS * len(crosshair_hits), reachable_blue
        )
    # Energized: the two selected colors charge the meter exactly like blue, so
    # they ride along in the same counter the booster scoring already reads.
    blue_cells += _extra_charge_cells(color_counts)
    # `cleared` is a set, and _intent_cells sorts what it is given -- so sort
    # here too, or the logged multipliers pair up with the wrong cells.
    mushroom_cells = sorted(
        (row, col) for row, col in cleared if special_board[row][col] == SPECIAL_MUSHROOM
    )
    if _MUSHROOM_MULTIPLIERS_ACTIVE:
        # The counter carries multiplier points rather than mushrooms; the
        # per-point weight in evaluate_simulation is scaled to match.
        multiplier_mushrooms = sum(
            mushroom_multiplier(board[row][col]) for row, col in mushroom_cells
        )
    else:
        multiplier_mushrooms = len(mushroom_cells)
    if mushroom_cells and intent_events is not None:
        intent_events.append(
            {
                "type": "mushroom_collect",
                "cascade": int(cascade_number),
                "cells": _intent_cells(mushroom_cells),
                "multipliers": [
                    int(mushroom_multiplier(board[row][col]))
                    for row, col in mushroom_cells
                ],
                "multiplier_aware": bool(_MUSHROOM_MULTIPLIERS_ACTIVE),
            }
        )
    mode_targets = sum(
        mode_target_value(special_board[row][col]) for row, col in cleared
    )
    if mode_targets and intent_events is not None:
        intent_events.append({"type": "mode_target_collect", "cascade": int(cascade_number),
                              "count": float(mode_targets)})
    predictable_special_activated = any(
        _is_predictable_blue_special(special_board[row][col])
        for row, col in cleared
    )
    xtra_cells = _xtra_move_cells(special_board, cleared)
    if xtra_cells and extra_move_counter is not None:
        extra_move_counter.append(1)
    if xtra_cells and intent_events is not None:
        intent_events.append(
            {
                "type": "xtra_move_collect",
                "cascade": int(cascade_number),
                "cells": _intent_cells(xtra_cells),
                "extra_moves": 1,
                "xtra_tiles": len(xtra_cells),
            }
        )
    if _SPECIAL_COMBO_SCORE_MULTIPLIER > 1:
        # Cells only a special's blast reached: the blast area is a
        # ComboType.Special combo, scored x specialComboScoreMultiplier.
        blast_cells = cleared - set(initial_cells)
        if blast_cells:
            surplus = _cleared_color_counts(
                board, special_board, blast_cells, matched_colors_by_cell
            )
            color_counts = dict(color_counts)
            for color, count in surplus.items():
                key = SPECIAL_AREA_SCORE_KEY_BASE + int(color)
                color_counts[key] = color_counts.get(key, 0.0) + count * (
                    _SPECIAL_COMBO_SCORE_MULTIPLIER - 1
                )
    for row, col in cleared:
        if (row, col) in created_cells:
            board[row][col] = created_cells[(row, col)]
            special_board[row][col] = created_special_types.get((row, col), CREATED_SPECIAL)
        else:
            board[row][col] = EMPTY
            special_board[row][col] = EMPTY
    return (
        len(cleared),
        activated_specials,
        cleared,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        color_counts,
    )


def _jelly_zone_conversion_color(matches, jelly_cells) -> int | None:
    """Colour the jelly area takes on, or None when no match reaches it.

    One matched cell inside the area is enough. With two matches touching it in
    the same cascade the bigger one wins -- the game repaints once, and the
    larger group is the likelier source.
    """
    if not jelly_cells:
        return None
    best_match = None
    for match in matches:
        if not _is_normal_color(match.color):
            continue
        if not any(cell in jelly_cells for cell in match.cells):
            continue
        if best_match is None or len(match.cells) > len(best_match.cells):
            best_match = match
    return None if best_match is None else int(best_match.color)


# The jelly fires once per move and only for the player's own swap match: at
# least one of its matched cells must sit inside the area. Matches that form
# later in the cascade clear normally, even inside the repainted area
# (confirmed by the player, 2026-08-15).
JELLY_ZONE_CONVERSION_EVENT = "jelly_zone_conversion"
# Colourless pieces have no colour to take on; everything else, specials
# included, is repainted and keeps its own effect.
JELLY_ZONE_COLOURLESS_SPECIALS = frozenset(
    (
        SPECIAL_MODE_TARGET,
        SPECIAL_DISCO_BALL,
        SPECIAL_JOOJOO_SKULL,
        SPECIAL_FROGGY_LOTUS,
        SPECIAL_MUSHROOM,
        SPECIAL_ALL_ABOARD_BANDIT,
        SPECIAL_COLOR_CRYSTAL,
        SPECIAL_BILLIE_DRONE,
    )
)


def _jelly_conversion_event(evaluation) -> dict | None:
    """The move's jelly conversion event, if its swap repainted the zone."""
    for event in getattr(evaluation, "intent_events", None) or ():
        if event.get("type") == JELLY_ZONE_CONVERSION_EVENT:
            return event
    return None


def jelly_conversion_tiles(evaluation) -> int:
    """Tiles the swap repainted -- whether or not the blob survived the move.

    ``jelly_converted_tiles`` on the evaluation counts only the survivors
    (the Cleo-style banked potential), and the usual conversion clears itself
    in the very next cascade, so it is 0 for exactly the conversions that
    score the most. The event count is the one that says the zone was taken.
    """
    event = _jelly_conversion_event(evaluation)
    if event is None:
        return 0
    return int(event.get("converted_tiles") or 0)


def _apply_jelly_zone_conversion(
    board,
    special_board,
    matches,
    jelly_cells,
    intent_events,
    cascade_number: int,
) -> int:
    """Repaint the pieces left inside the jelly area after a match touched it.

    Specials are repainted too and keep their type: the game changes the colour
    of everything inside the area.
    """
    if not jelly_cells or cascade_number != 1:
        return 0
    color = _jelly_zone_conversion_color(matches, jelly_cells)
    if color is None:
        return 0

    converted = []
    # Charge pieces repainted to a colour that does not charge count as
    # destroyed charge pieces: the player (2026-09-15) -- two blue in the zone
    # and an orange conversion is +2 on the meter.
    charge_converted = 0
    target_charges = is_booster_charge_color(int(color))
    for row, col in sorted(jelly_cells):
        if not (0 <= row < len(board) and 0 <= col < len(board[row])):
            continue
        value = board[row][col]
        if value == color or not _is_normal_color(value):
            continue
        if (
            special_board[row][col] in JELLY_ZONE_COLOURLESS_SPECIALS
            or is_purple_gem_special(special_board[row][col])
        ):
            continue
        if not target_charges and is_booster_charge_color(int(value)):
            charge_converted += 1
        board[row][col] = color
        converted.append((row, col))
    if intent_events is not None:
        # Logged even when nothing changed colour: the jelly has fired for this
        # move either way, and the event is what stops it firing again.
        intent_events.append(
            {
                "type": JELLY_ZONE_CONVERSION_EVENT,
                "cascade": int(cascade_number),
                "color": int(color),
                "converted_tiles": len(converted),
                "charge_converted": int(charge_converted),
                "cells": [_intent_cell(cell) for cell in converted],
            }
        )
    return len(converted)


def _clear_matches_with_details(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
    mode: str = "None",
    intent_events: list[dict] | None = None,
    cascade_number: int = 1,
    random_refill_tracker: list[bool] | None = None,
    extra_move_counter: list[int] | None = None,
    active_funky_cells: set[tuple[int, int]] | None = None,
    swap_cells: tuple[tuple[int, int], ...] = (),
    ufo_abducted_colors: tuple[int, ...] = (),
    froggy_blob_cells: frozenset = frozenset(),
) -> tuple[int, int, int, set[tuple[int, int]], int, int, int, bool, dict[int, float]]:
    mode = normalize_game_mode(mode)
    if active_funky_cells is None:
        active_funky_cells = set(_FUNKY_TILE_CELLS)
    active_jelly_cells = set(_JELLY_ZONE_CELLS)
    initial_cells = set()
    matched_colors_by_cell = {}
    created_cells = {}
    created_special_types = {}
    created_specials = 0
    for match in matches:
        initial_cells.update(match.cells)
        for cell in match.cells:
            matched_colors_by_cell.setdefault(cell, set()).add(match.color)
        if (
            mode is GameMode.SPECIAL_O_RAMA
            or _EVERY_MATCH_IS_SPECIAL
            or match.kind in {"four", "five", "l", "t_or_cross", "square"}
        ):
            created_specials += 1
            # Only the swipe's own matches sit on a swapped piece; a match formed
            # by falling tiles has no swap cell, so a draw picks its cell.
            created_cell = _created_special_cell(
                match,
                swap_cells if cascade_number == 1 else (),
                matches if cascade_number > 1 else (),
            )
            created_cells[created_cell] = match.color
            created_special_types[created_cell] = (
                SPECIAL_LIGHTNING
                if mode is GameMode.LIGHTNING_STRIKE
                else _created_special_type(match)
            )
            # Match & Hatch: extraMoveRandomSpecial replaces what the player's
            # own combo makes (MakeSpecialSlotCreated, isPlayerInit). Not the
            # Froggy lotus blob: BuildMegaCombo clones the blob combo's own
            # special, so the shape's special stays and nothing is drawn
            # (recorded 2026-11-06 Match & Hatch: a bomb, one draw fewer).
            hatched = (
                _ENGINE_RANDOM_SPECIAL(created_cell, match.color)
                if cascade_number == 1 and _ENGINE_RANDOM_SPECIAL is not None
                and not (match.cells & froggy_blob_cells)
                else None
            )
            if hatched is not None:
                created_special_types[created_cell] = hatched
                if hatched in (SPECIAL_DISCO_BALL, SPECIAL_SPRAY_SE, SPECIAL_CLEO_BUG):
                    created_cells[created_cell] = 99
    if intent_events is not None:
        for created_cell, color in sorted(created_cells.items()):
            special = created_special_types[created_cell]
            intent_events.append(
                {
                    "type": "special_creation",
                    "cascade": int(cascade_number),
                    "special": _special_intent_name(special),
                    "cell": _intent_cell(created_cell),
                    "color": int(color),
                }
            )
    # Laser Mode fires only for the match made directly by the player's swipe.
    # A special+special activation takes its separate simulation path, while
    # matches formed later by falling pieces are ordinary cascade matches.
    if _is_laser_mode(mode) and cascade_number == 1:
        initial_cells.update(_laser_effect_cells(board, matches))
    # Arcade Man / native MatchLineBoard: the performed swap's matches explode
    # their rows/columns. Gravity cascades clear normally.
    if _is_arcade_man_mode(mode) and cascade_number == 1:
        initial_cells.update(_arcade_man_cells(board, matches))
    # Same mechanic expressed as the engine's two separate rule flags, for a
    # ruleset that enables only one axis. Like MatchLineBoard it lives in
    # AfterPerformedSwap, so only the performed swap's matches trigger it.
    elif (
        _DESTROY_ROW_ON_HORIZONTAL_MATCH or _DESTROY_COLUMN_ON_VERTICAL_MATCH
    ) and cascade_number == 1:
        initial_cells.update(_line_destruction_cells(board, matches))
    # Drillin' Down: the match also explodes every piece vertically below its
    # matched cells -- but only the player's own match, like Laser and unlike
    # Arcade Man. Measured on the 2026-08-10 22:40 solo game: three moves whose
    # blue came purely from a second cascade each predicted 4 and each charged
    # the booster by 3, and restricting the drill to the direct match reproduces
    # the observed 3 in all three.
    if mode is GameMode.DRILLIN_DOWN and cascade_number == 1:
        initial_cells.update(_drillin_down_cells(board, matches))
    # Frozen Feud: a broken frozen tile takes its whole row with it. This one is
    # the board special's own area of effect (FrozenFeudBoard overrides
    # GetAreaOfBoardSpecialEffect, not AfterPerformedSwap), so unlike the two
    # rules above it fires on cascade matches too -- no cascade_number gate.
    if mode is GameMode.FROZEN_FEUD:
        initial_cells.update(_frozen_feud_cells(board, special_board, matches))
    # The Floor Is Lava: a column matched for the second time erupts and takes
    # every piece standing in it. Only the swipe's own matches count -- the
    # marks are applied in AfterPerformedSwap, and a cascade match cannot break
    # more ground. The mark bookkeeping itself stays in floor_lava_transition,
    # which reads the same state, so the two cannot disagree.
    if (
        mode is GameMode.FLOOR_IS_LAVA
        and cascade_number == 1
        and not _ABILITY_USED_THIS_MOVE
    ):
        erupted, _marks_after = floor_lava_column_transition(
            matches, _FLOOR_LAVA_CHECKED_COLUMNS
        )
        if erupted:
            initial_cells.update(_floor_lava_eruption_cells(board, erupted))
            if intent_events is not None:
                intent_events.append(
                    {
                        "type": "floor_lava_eruption",
                        "cascade": int(cascade_number),
                        "columns": [int(col) + 1 for col in erupted],
                    }
                )
    # The whole-color wipe only fires on the player's direct swap (the first
    # cascade). Colors matched by later cascades - tiles that fall into place
    # after the wipe - clear normally, i.e. only their matched cells.
    if _COLOR_CRUSH_ACTIVE and cascade_number == 1:
        initial_cells.update(_color_crush_cells(board, matches))
    # UFO SE: the eyes that fired on this cascade take their colour off the
    # whole board. Which colours those are is decided by the caller (it owns
    # the per-move eye budget), so this only applies the wipe.
    if ufo_abducted_colors:
        initial_cells.update(
            _ufo_abduction_cells(board, special_board, ufo_abducted_colors)
        )
    # This rule belongs only to the match created by the player's swipe. A
    # vertical match formed after gravity is a normal cascade match (but a
    # match-4+ there can still award a genuine cascade extra move).
    if (
        _VERTICAL_MATCHES_DESTROY_COLOR_ACTIVE or _MATCHES_DESTROY_COLOR_ACTIVE
    ) and cascade_number == 1:
        initial_cells.update(
            _destroy_color_cells(
                board,
                special_board,
                matches,
                # "Matches explode color" drops the vertical condition; when
                # both somehow run at once the wider rule wins, which is what
                # the engine would do with two overlapping wipes anyway.
                vertical_only=not _MATCHES_DESTROY_COLOR_ACTIVE,
            )
        )
    if mode is GameMode.FUNKY_TILES:
        initial_cells.update(
            _apply_funky_tile_matches(
                board,
                matches,
                active_funky_cells,
                intent_events,
                cascade_number,
            )
        )

    (
        cleared,
        activated,
        cleared_cells,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        color_counts,
    ) = _clear_cells_with_specials(
        board,
        special_board,
        initial_cells,
        created_cells=created_cells,
        created_special_types=created_special_types,
        intent_events=intent_events,
            cascade_number=cascade_number,
            random_refill_tracker=random_refill_tracker,
            matched_colors_by_cell=matched_colors_by_cell,
            extra_move_counter=extra_move_counter,
        )
    _apply_jelly_zone_conversion(
        board,
        special_board,
        matches,
        active_jelly_cells,
        intent_events,
        cascade_number,
    )
    return (
        cleared,
        activated,
        created_specials,
        cleared_cells,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        color_counts,
    )


def clear_matches(
    board: list[list[int]],
    special_board: list[list[int]],
    matches: list[MatchGroup],
    mode: str = "None",
) -> tuple[int, int, int]:
    cleared, activated, created, _, _, _, _, _, _ = _clear_matches_with_details(board, special_board, matches, mode)
    return cleared, activated, created


def _candidate_origins(candidate: MoveCandidate) -> list[list[tuple[int, int] | None]]:
    origins = [
        [(row, col) if value != EMPTY else None for col, value in enumerate(values)]
        for row, values in enumerate(candidate.board)
    ]
    start_row, start_col = candidate.start
    target_row, target_col = candidate.target
    origins[start_row][start_col], origins[target_row][target_col] = (
        origins[target_row][target_col],
        origins[start_row][start_col],
    )
    return origins


def _count_new_chest_drops(
    board: list[list[int]],
    origins: list[list[tuple[int, int] | None]],
    counted_origins: set[tuple[int, int]],
) -> int:
    bottom_row = len(board) - 1
    drops = 0
    for col, value in enumerate(board[bottom_row]):
        if value != CHEST:
            continue
        origin = origins[bottom_row][col]
        if origin is None or origin[0] == bottom_row or origin in counted_origins:
            continue
        counted_origins.add(origin)
        drops += 1
    return drops


def _filter_stale_matches(
    matches: list[MatchGroup],
    origins: list[list[tuple[int, int] | None]],
    stale_match_cells: list[frozenset[tuple[int, int]]] | None,
) -> list[MatchGroup]:
    if not stale_match_cells:
        return matches

    filtered = []
    for match in matches:
        match_origins = {origins[row][col] for row, col in match.cells}
        if None in match_origins:
            filtered.append(match)
            continue
        if any(match_origins.issubset(stale_cells) for stale_cells in stale_match_cells):
            continue
        filtered.append(match)
    return filtered


def simulate_candidate(
    candidate: MoveCandidate,
    max_cascades: int = 40,
    initial_matches: list[MatchGroup] | None = None,
    stale_match_cells: list[frozenset[tuple[int, int]]] | None = None,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    extra_moves_uncertain_after_direct: bool = False,
) -> SimulationResult:
    # `extra_moves_uncertain_after_direct` is set by wipe-like moves (e.g. the
    # Sweep SE broom) whose board past the direct match set is only a modelled
    # rearrangement: deeper cascades are not guaranteed, so their extra moves
    # must not be counted as reliable.
    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    origins = _candidate_origins(candidate)
    all_matches = []
    cascade_matches = []
    cleared_cells = 0
    cleared_color_counts = {}
    blue_cells = 0
    activated_specials = 0
    created_specials = 0
    multiplier_mushrooms = 0
    mode_targets = 0
    chest_drops = 0
    counted_chest_origins = set()
    extra_moves = 0
    direct_extra_moves = 0
    cascade_count = 0
    first_wipe_cascade = None
    # True when the first wipe was a UFO abduction alone -- its cleared colour
    # is predicted, so even the cascade it feeds is untrusted for extra moves.
    ufo_wipe_is_boundary = False
    random_refill_after_cascade = None
    xtra_extra_move_awarded = False
    predictable_special_activated = False
    intent_events = []
    active_funky_cells = set(_FUNKY_TILE_CELLS)
    ufo_eyes_left = _ufo_eyes_this_move()
    ufo_abducted_colors: set[int] = set()
    # Colours an eye has locked onto but not yet pulled off the board.
    ufo_pending_colors: list[int] = []
    ufo_has_fired = False
    # Extras excluded by the UFO boundary but predictable if the lock is
    # trusted; ambiguity (more matched pickable colours than eyes) voids them.
    ufo_predicted_extra_moves = 0
    ufo_lock_ambiguous = False
    ufo_directional_lock = False
    froggy_gathered = False
    froggy_blob_cells: frozenset = frozenset()
    froggy_special_cells: tuple[tuple[int, int], ...] = ()
    # Origin labels of the pieces the jelly repainted, so that after the
    # cascades settle the repaint can be priced by what actually survived:
    # a packed blob usually forms a match of its own and clears in the very
    # next cascade (observed 2026-08-24: five conversions, zero surviving
    # blobs), and those tiles are already paid as cleared cells and blue.
    jelly_converted_origins: set[tuple[int, int]] = set()
    direct_match_cells = 0
    direct_blue_cells = 0
    direct_effect_cells = 0
    direct_effect_blue_cells = 0
    crazy_columns_score = 0.0

    auto_explode_tags = set()
    for cascade_index in range(max_cascades):
        # Counts resolved cascades, not loop turns: a UFO settle spends a turn
        # without being a cascade of its own, and everything downstream (intent
        # events, refill boundaries, Arcade Man) reasons about real cascades.
        cascade_number = cascade_count + 1
        past_random_refill_boundary = (
            random_refill_after_cascade is not None
            and cascade_number > random_refill_after_cascade
        )
        # Unknown falling-tile cascades stop here, but an eye that already
        # locked a known colour must still perform its deterministic pull.
        if past_random_refill_boundary and not ufo_pending_colors:
            break
        if past_random_refill_boundary:
            matches = []
        elif cascade_index == 0 and initial_matches is not None:
            matches = initial_matches
        else:
            matches = _filter_stale_matches(
                _find_matches_cached(
                    board,
                    allow_square_matches,
                    match_scan_cache,
                    special_board,
                ),
                origins,
                stale_match_cells,
            )
        matches = _with_auto_explosions(
            matches, board, origins, auto_explode_tags, past_random_refill_boundary
        )
        auto_explode_tags = set()
        # UFO SE: the eyes lock colours on while the cascades run but only
        # collect once the board has settled -- and if both eyes locked on,
        # both colours leave together in a single pull. So the wipe waits here,
        # for the first scan that finds nothing left to resolve.
        # Froggy Fu: a lotus only fires on the player's own match, so this is
        # cascade 0 or never. The gather runs on the board here and hands the
        # pulled cluster back as a match, which means the destroy path, the
        # gravity, the created special, the blue count and the extra move are
        # the ordinary ones -- and so is the board the lookahead inherits.
        # Before this, the simulated lotus move was a board where nothing had
        # happened, with the value bolted on afterwards by
        # `rank_froggy_lotus_moves`.
        if cascade_index == 0 and matches and not froggy_gathered:
            gathered = froggy_lotus_gather(
                board,
                special_board,
                matches,
                allow_square_matches,
                # The dragged tile is the one that landed on `target`.
                dragged_cell=(
                    candidate.target if _is_plain_swap_candidate(candidate) else None
                ),
            )
            if gathered is not None:
                board = gathered.board
                special_board = gathered.special_board
                matches = gathered.matches
                froggy_gathered = True
                # The blob special lands on the combo's `origin`, not on a
                # swapped cell, so it goes in front of the swap pair -- which
                # stays for any second match the same swipe made.
                froggy_special_cells = gathered.special_cells
                froggy_blob_cells = gathered.blob_cells
                intent_events.extend(gathered.events)
        ufo_settled_wipe: tuple[int, ...] = ()
        if not matches:
            if not ufo_pending_colors:
                break
            ufo_settled_wipe = tuple(ufo_pending_colors)
            ufo_pending_colors = []
            ufo_has_fired = True
        else:
            cascade_count += 1
            all_matches.extend(matches)
            cascade_matches.append(matches)
        if matches and cascade_index == 0:
            direct_extra_moves += _count_direct_extra_move_matches(matches)
            direct_cells = {cell for match in matches for cell in match.cells}
            direct_match_cells = len(direct_cells)
            direct_blue_cells = sum(
                1 for row, col in direct_cells if is_booster_charge_color(board[row][col])
            )
        color_crush_wipe = (
            _COLOR_CRUSH_ACTIVE
            and cascade_index == 0
            and any(
                match.color not in color_crush_inert_colors()
                and _is_normal_color(match.color)
                for match in matches
            )
        )
        vertical_color_wipe = (
            (_VERTICAL_MATCHES_DESTROY_COLOR_ACTIVE or _MATCHES_DESTROY_COLOR_ACTIVE)
            and cascade_index == 0
            and bool(
                _match_destroy_colors(
                    special_board,
                    matches,
                    vertical_only=not _MATCHES_DESTROY_COLOR_ACTIVE,
                )
            )
        )
        # Collect until the first passive fire, not just on the direct swap.
        # PlayerControl.BeforeCombosDestroy has no direct-cascade gate. The
        # passive fire itself then closes collection for the rest of the move.
        if ufo_eyes_left > 0 and matches and not ufo_has_fired:
            swap_order = (candidate.target, candidate.start) if cascade_index == 0 else ()
            ordered_colors = _ufo_swap_ordered_colors(
                matches,
                swap_order,
            )
            laser_colors = (
                _ufo_laser_colors(board, special_board, matches, swap_order)
                if cascade_index == 0 and _is_laser_mode(mode) else []
            )
            ordered_colors.extend(laser_colors)
            locked = _ufo_abduction_colors(
                ordered_colors,
                ufo_abducted_colors,
                ufo_eyes_left,
            )
            if locked:
                # More lockable colours than eyes means the resolve order
                # picks the winner -- exactly the misprediction the boundary
                # exists for, so the predicted-extra credit is off the table.
                lockable = {
                    color
                    for color in ordered_colors
                    if color in UFO_PASSIVE_PICKABLE_COLORS
                    and color not in ufo_abducted_colors
                }
                if len(lockable) > len(locked) and not laser_colors:
                    target_colors = {m.color for m in matches
                                     if cascade_index == 0
                                     and candidate.target in m.cells and m.color in lockable}
                    if len(locked) == 1 and target_colors == {locked[0]}:
                        # The dragged piece's destination match owns the eye.
                        # Two simultaneous colours do not make that order random.
                        ufo_directional_lock = True
                    else:
                        ufo_lock_ambiguous = True
                ufo_eyes_left -= len(locked)
                ufo_abducted_colors.update(locked)
                ufo_pending_colors.extend(locked)
                intent_events.append({
                    "type": "ufo_color_lock",
                    "cascade": int(cascade_number),
                    "colors": [int(color) for color in locked],
                    "source": "swap_and_laser" if laser_colors else
                              "swap" if cascade_index == 0 else "cascade",
                    "order_ambiguous": bool(ufo_lock_ambiguous),
                })
        if ufo_settled_wipe:
            intent_events.append(
                {
                    "type": UFO_ABDUCTION_EVENT,
                    "cascade": int(cascade_number),
                    "colors": [int(color) for color in ufo_settled_wipe],
                }
            )
        # The gather empties a cluster in one go, so the hole it leaves refills
        # with unknown tiles exactly like a colour wipe does. The pull itself is
        # deterministic, so the single cascade it feeds is still made of pieces
        # we can see -- same standing as Color Crush, not as the UFO.
        froggy_gather_wipe = froggy_gathered and cascade_index == 0
        # A capture-backed refill supplies the actual falling colors. In that
        # path a deterministic color wipe is not an unknown-refill boundary, and
        # neither is an eye: what it left falls known, so a four below it is an
        # extra (75 of 75 recorded UFO moves predicted the extra correctly).
        if _ENGINE_REFILL is None and first_wipe_cascade is None and (
            color_crush_wipe
            or vertical_color_wipe
            or ufo_settled_wipe
            or froggy_gather_wipe
        ):
            first_wipe_cascade = cascade_index
            # Color Crush / vertical colour wipes remove a colour set that is
            # known before the move starts, so the cascade the wipe feeds is
            # still made of pieces we can see. The UFO's colour set is itself a
            # prediction -- which colour the eye locks onto depends on the
            # order the game resolves the matches in -- so nothing past the
            # abduction is guaranteed. Mark the cascade *before* it as the last
            # certain one and use a reason outside
            # DETERMINISTIC_WIPE_REFILL_REASONS, so has_reliable_same_move_extra
            # stops trusting a match-4 that only exists on the wiped board.
            ufo_only_wipe = bool(ufo_settled_wipe) and not (
                color_crush_wipe or vertical_color_wipe
            )
            ufo_wipe_is_boundary = ufo_only_wipe and not ufo_directional_lock
            intent_events.append(
                {
                    "type": "uncertain_refill_boundary",
                    "after_cascade": int(
                        cascade_index if ufo_only_wipe else cascade_index + 1
                    ),
                    "reason": (
                        UFO_DIRECTIONAL_REFILL_REASON
                        if ufo_only_wipe and ufo_directional_lock
                        else UFO_ABDUCTION_REFILL_REASON
                        if ufo_only_wipe
                        else BOARD_WIPE_REFILL_REASON
                    ),
                }
            )
        # Whole-color wipes force a large random refill. The single cascade
        # right after the first wipe is still decided by known pieces falling
        # into place, but anything deeper depends on unknown refilled tiles --
        # those match-4s are not guaranteed extra moves, so they are not counted.
        # A UFO abduction is stricter still: the colour it removes is a
        # prediction, so this very cascade already runs on a board that may
        # never have existed and its match-4s do not count either.
        last_certain_wipe_cascade = (
            first_wipe_cascade - 1
            if first_wipe_cascade is not None and ufo_wipe_is_boundary
            else None
            if first_wipe_cascade is None
            else first_wipe_cascade + 1
        )
        extra_moves_certain = (
            not extra_moves_uncertain_after_direct or cascade_index == 0
        )
        cascade_match_extra = 0
        ufo_predicted_this_cascade = 0
        if extra_moves_certain and (
            last_certain_wipe_cascade is None
            or cascade_index <= last_certain_wipe_cascade
        ):
            cascade_match_extra = _count_extra_move_matches(matches)
            extra_moves += cascade_match_extra
        elif (
            extra_moves_certain
            and ufo_wipe_is_boundary
            and first_wipe_cascade is not None
            and cascade_index <= first_wipe_cascade + 1
        ):
            # The cascade the abduction settle feeds is gravity over pieces we
            # can already see (same standing Color Crush gets). It stays out of
            # `extra_moves` because the locked colour is a prediction; when
            # that prediction is unambiguous the manual Extra Move action may
            # still spend it -- tracked separately here.
            ufo_predicted_this_cascade = _count_extra_move_matches(matches)
            ufo_predicted_extra_moves += ufo_predicted_this_cascade
        _append_match_intent_events(intent_events, matches, cascade_number)
        event_start = len(intent_events)
        xtra_move_counter = []
        board_before_clear = (
            clone_grid(board)
            if _ENGINE_REFILL is not None and matches and ufo_eyes_left > 0 and not ufo_has_fired
            else None
        )
        classic_before = _classic_specials(special_board, explode_created_specials_immediately, mode)
        (
            cleared,
            activated,
            created,
            cleared_cell_set,
            cleared_blue,
            cleared_mushrooms,
            cleared_mode_targets,
            cleared_predictable_special,
            color_counts,
        ) = _clear_matches_with_details(
            board,
            special_board,
            matches,
            mode,
            intent_events=intent_events,
            cascade_number=cascade_number,
            extra_move_counter=xtra_move_counter,
            active_funky_cells=active_funky_cells,
            swap_cells=froggy_special_cells + (candidate.target, candidate.start),
            ufo_abducted_colors=ufo_settled_wipe,
            froggy_blob_cells=froggy_blob_cells if froggy_gather_wipe else frozenset(),
        )
        if board_before_clear is not None and ufo_eyes_left > 0:
            locked = _ufo_abduction_colors(
                _ufo_blast_colors(board_before_clear, intent_events[event_start:], matches),
                ufo_abducted_colors,
                ufo_eyes_left,
            )
            if locked:
                ufo_eyes_left -= len(locked)
                ufo_abducted_colors.update(locked)
                ufo_pending_colors.extend(locked)
                intent_events.append({
                    "type": "ufo_color_lock",
                    "cascade": int(cascade_number),
                    "colors": [int(color) for color in locked],
                    "source": "special_blast",
                    "order_ambiguous": bool(ufo_lock_ambiguous),
                })
        cleared_xtra_moves = 1 if xtra_move_counter and not xtra_extra_move_awarded else 0
        if extra_moves_certain:
            extra_moves += cleared_xtra_moves
            xtra_extra_move_awarded = xtra_extra_move_awarded or bool(cleared_xtra_moves)
        if cascade_index == 0:
            direct_extra_moves += cleared_xtra_moves
            # The first resolved effect contains the direct match plus every
            # cell destroyed by a special activated by that match. Later
            # gravity matches are independent cascades and are excluded.
            direct_effect_cells = cleared
            direct_effect_blue_cells = cleared_blue
        # Activating a Vinnie SE heart does NOT grant an extra move in-game --
        # only creating a special via a match-4+ (or a dedicated Xtra Move tile)
        # does. Counting heart activations as extras made the bot report phantom
        # extra moves and over-prefer match-3 heart chains; the genuine value of
        # those moves is the large board clear, which the score already reflects.
        color_clear_reason = _mark_color_clear_random_refill_boundary(
            intent_events,
            event_start,
            cascade_number,
        )
        if color_clear_reason is not None:
            if color_clear_reason in DETERMINISTIC_WIPE_REFILL_REASONS:
                # A heart / Vinnie SE heart removes a fixed set of colours, so
                # the pieces left on the board fall into an exactly predictable
                # position. Simulate that one follow-up cascade (its match-4 is
                # a real extra move) and only stop past it, where unknown
                # refilled tiles would start to matter.
                if first_wipe_cascade is None:
                    first_wipe_cascade = cascade_index
                if random_refill_after_cascade is None:
                    random_refill_after_cascade = cascade_number + 1
            else:
                random_refill_after_cascade = cascade_number
                # A random-target special (lightning / crosshair) that activates
                # inside this same cascade zaps random remote tiles as the
                # cascade resolves, so its whirl can break the very match-4 that
                # would have granted this cascade's extra move -- in game the
                # extra never comes. We optimistically added it above (matches
                # are found before the clear reveals the activation), so retract
                # it. Only for cascades past the direct swap: a match-4 made by
                # the player's own swap (cascade 0) still awards its extra.
                # Not when every special of this cascade was set off by the
                # four-plus match itself (a heart inside the four hitting a
                # lightning): the four has already resolved, so nothing is left
                # for the whirl to break (player, 2026-09-26: yellow three ->
                # purple four with a purple heart, booster fired instead).
                if (
                    cascade_index > 0
                    and cascade_match_extra
                    and not _specials_fired_only_by_extra_matches(
                        intent_events, event_start, matches
                    )
                ):
                    extra_moves -= cascade_match_extra
                if cascade_index > 0 and ufo_predicted_this_cascade:
                    ufo_predicted_extra_moves -= ufo_predicted_this_cascade
        # The conversion happens before gravity, so the repainted cells still
        # sit at their original coordinates and the origin grid names them.
        for event in intent_events[event_start:]:
            if event.get("type") == JELLY_ZONE_CONVERSION_EVENT:
                for row, col in event.get("cells") or ():
                    origin = origins[row][col]
                    if origin is not None:
                        jelly_converted_origins.add(origin)
        for row, col in cleared_cell_set:
            origins[row][col] = None
        cleared_cells += cleared
        crazy_columns_score += _crazy_columns_cell_score(cleared_cell_set)
        _merge_color_counts(cleared_color_counts, color_counts)
        blue_cells += cleared_blue
        activated_specials += activated
        created_specials += created
        multiplier_mushrooms += cleared_mushrooms
        mode_targets += cleared_mode_targets
        predictable_special_activated = predictable_special_activated or cleared_predictable_special
        _tag_auto_explosions(special_board, origins, classic_before, auto_explode_tags)
        board, special_board, origins = _drop_and_refill(
            board,
            special_board,
            origins,
            chain_combos=_chain_combo_count(matches) if cascade_index else 0,
        )
        chest_drops += _count_new_chest_drops(board, origins, counted_chest_origins)

    result = SimulationResult(
        candidate=candidate,
        board=board,
        special_board=special_board,
        matches=all_matches,
        cascade_matches=cascade_matches,
        cascade_count=cascade_count,
        cleared_cells=cleared_cells,
        cleared_color_counts=cleared_color_counts,
        blue_cells=blue_cells + _chest_blue(chest_drops),
        created_specials=created_specials,
        activated_specials=activated_specials,
        extra_moves=extra_moves,
        direct_extra_moves=direct_extra_moves,
        ufo_predicted_extra_moves=(
            0.0 if ufo_lock_ambiguous else float(ufo_predicted_extra_moves)
        ),
        ufo_directional_predicted_extra_moves=(
            float(ufo_predicted_extra_moves) if ufo_lock_ambiguous else 0.0
        ),
        multiplier_mushrooms=multiplier_mushrooms,
        mode_targets=mode_targets,
        chest_drops=chest_drops,
        predictable_special_activated=predictable_special_activated,
        intent_events=intent_events,
        direct_match_cells=float(direct_match_cells),
        direct_blue_cells=float(direct_blue_cells),
        direct_effect_cells=float(direct_effect_cells),
        direct_effect_blue_cells=float(direct_effect_blue_cells),
        effect_source_counts={
            EffectSource.DIRECT_MATCH.value: float(direct_match_cells),
            EffectSource.SPECIAL.value: max(
                0.0, float(direct_effect_cells) - float(direct_match_cells)
            ),
            EffectSource.CASCADE.value: max(
                0.0, float(cleared_cells) - float(direct_effect_cells)
            ),
        },
        crazy_columns_score=crazy_columns_score,
        froggy_lotus_gathered=froggy_gathered,
    )
    jelly_surviving_tiles = 0
    if jelly_converted_origins:
        jelly_surviving_tiles = sum(
            1
            for row in range(len(board))
            for col in range(len(board[row]))
            if origins[row][col] in jelly_converted_origins
        )
    return _refresh_created_special_values(
        _apply_knight_charge_expectation(
            _apply_jelly_conversion_value(result, jelly_surviving_tiles)
        )
    )


def count_legal_next_moves(
    board: list[list[int]],
    special_board: list[list[int]],
    allow_square_matches: bool = False,
    limit: int | None = None,
    mode: str = "None",
) -> int:
    # `limit` lets hot callers (board_potential) stop early once the count is
    # high enough, since that score component is capped anyway. Callers that
    # need the exact total leave it as None.
    count = 0
    # Both swipe directions of a two-special pair are separate candidates (the
    # dragged piece decides the outcome), but they are one move opportunity for
    # "how many moves does this board still offer", so count the pair once.
    # A spray keeps its per-direction candidates (start == target); those really
    # are different moves.
    counted_pairs = set()
    # One scan cache per call: every candidate re-scanned the same pre-swap
    # board for its preexisting matches (2026-09-22). Content-keyed, so the
    # answers are the ones the uncached scan gives.
    match_scan_cache: dict[tuple, list[MatchGroup]] = {}
    for candidate in generate_candidates(board, special_board):
        pair = frozenset({candidate.start, candidate.target})
        if len(pair) > 1 and pair in counted_pairs:
            continue
        if _candidate_creates_swapped_match(
            board,
            candidate,
            allow_square_matches,
            match_scan_cache=match_scan_cache,
            mode=mode,
        ):
            counted_pairs.add(pair)
            count += 1
            if limit is not None and count >= limit:
                break
    return count


EXACT_VALUE_SPECIAL_NAMES = frozenset({"lightning", "crosshair"})


def _created_special_effect_size(
    board: list[list[int]],
    special_board: list[list[int]],
    row: int,
    col: int,
    special: int,
) -> int:
    board_pieces = sum(1 for values in board for value in values if _is_board_piece(value))
    if special == SPECIAL_LIGHTNING:
        return min(LIGHTNING_REMOTE_TARGET_COUNT + 1, board_pieces)
    if special == SPECIAL_CROSSHAIR:
        return min(CROSSHAIR_REMOTE_TARGET_COUNT + 1, board_pieces)
    return len(_special_effect_cells(board, special_board, row, col, special))


def _apply_jelly_conversion_value(
    result: SimulationResult, surviving_tiles: int = 0
) -> SimulationResult:
    """Price what the jelly repaint left on the board.

    The repaint is the one part of a jelly move whose colour the player chooses:
    whichever match reaches the area decides what the whole area becomes. So the
    same board offers a blue repaint and a higher-scoring one, and the ranking
    has to be able to compare them instead of taking whichever match scores more
    on its own.

    Only the repainted tiles still standing when the cascades settle are priced
    here: a packed blob usually forms a match of its own and clears in the very
    next cascade (the 2026-08-24 debug sweep found five conversions and zero
    surviving blobs), and those tiles are already paid in full as cleared cells
    and ``blue_cells``. Pricing the whole repaint on top of that rewarded a
    "setup" that never survives the move. The survivors go into
    ``blue_potential`` -- the Cleo route for "repainted but not collected",
    scored at a discount and answering to how much the meter still needs.
    """
    events = [
        event
        for event in (result.intent_events or ())
        if event.get("type") == JELLY_ZONE_CONVERSION_EVENT
    ]
    if not events:
        return result
    event = events[0]
    color = event.get("color")
    converted = float(event.get("converted_tiles") or 0)
    surviving = float(min(max(surviving_tiles, 0), converted))
    result.jelly_converted_tiles = surviving
    result.jelly_converted_color = None if color is None else int(color)
    if surviving > 0 and color is not None and is_booster_charge_color(int(color)):
        result.blue_potential += surviving
        result.jelly_charge_cells = surviving
    elif (
        converted > 0
        and color is not None
        and not is_booster_charge_color(int(color))
    ):
        # A non-blue conversion charges the meter by the blue it repainted --
        # every blue in the zone counts as destroyed (the player, 2026-09-15).
        # That is what the measured flat "about three" was averaging: the
        # median zone held about three blue. The count is exact when the
        # conversion event carries it; an event from before it did falls back
        # to the measured average. Collected charge, not banked: it lands on
        # this very move.
        charge = event.get("charge_converted")
        charge = JELLY_CONVERSION_EXPECTED_CHARGE if charge is None else float(charge)
        if charge > 0:
            result.blue_cells += charge
            result.intent_events.append(
                {
                    "type": MEASURED_CHARGE_EVENT,
                    "source": "jelly_zone_conversion",
                    "color": int(color),
                    "blue_cells": float(charge),
                }
            )
    return result


def _apply_knight_charge_expectation(result: SimulationResult) -> SimulationResult:
    """Add the measured charge a knight chain earns beyond its modelled cells."""
    activations = sum(
        1
        for event in (result.intent_events or ())
        if event.get("type") == "special_activation" and event.get("special") == "knight"
    )
    if activations <= 0:
        return result
    result.expected_extra_cells += KNIGHT_EXPECTED_EXTRA_CELLS.get(
        min(activations, max(KNIGHT_EXPECTED_EXTRA_CELLS)), 0.0
    )
    extra = KNIGHT_EXPECTED_EXTRA_BLUE.get(
        min(activations, max(KNIGHT_EXPECTED_EXTRA_BLUE)), 0.0
    )
    if extra <= 0:
        return result
    result.blue_cells += extra
    result.intent_events.append(
        {
            "type": MEASURED_CHARGE_EVENT,
            "source": "knight",
            "activations": int(activations),
            "blue_cells": float(extra),
        }
    )
    return result


def _jelly_setup_bonus(
    result: SimulationResult,
    score_rally_values: dict[int, float] | None,
) -> float:
    """The colour-agnostic half of the repaint's value.

    A packed one-colour area is easier to take whole next turn whatever colour
    it is, and a colour the board is paying extra for is worth the difference on
    top. Both are capped: without a cap a fourteen-tile repaint would outweigh
    every ordinary move on the board, and the repaint is a *setup*, not points
    in hand.
    """
    tiles = float(result.jelly_converted_tiles or 0.0)
    if tiles <= 0:
        return 0.0
    bonus = min(tiles * JELLY_SETUP_TILE_BONUS, JELLY_SETUP_TILE_CAP)
    color = result.jelly_converted_color
    if score_rally_values and color is not None:
        # Only the surplus over an ordinary colour counts; the base value of the
        # tiles is not points until something matches them.
        surplus = float(score_rally_values.get(int(color), 0.0)) - 1.0
        if surplus > 0:
            bonus += min(
                tiles * surplus * JELLY_SETUP_RALLY_TILE_BONUS,
                JELLY_SETUP_RALLY_CAP,
            )
    return bonus


def _refresh_created_special_values(result: SimulationResult) -> SimulationResult:
    """Attach board-dependent values to surviving created Lightning/Crosshair pieces."""
    creation_events = [
        event
        for event in (result.intent_events or ())
        if event.get("type") == "special_creation"
        and event.get("special") in EXACT_VALUE_SPECIAL_NAMES
    ]
    if not creation_events:
        result.created_special_value = 0.0
        result.created_special_values = []
        return result

    type_by_name = {
        "lightning": SPECIAL_LIGHTNING,
        "crosshair": SPECIAL_CROSSHAIR,
    }
    available = {}
    for row, values in enumerate(result.special_board):
        for col, special in enumerate(values):
            if special not in type_by_name.values():
                continue
            key = (_special_intent_name(special), int(result.board[row][col]))
            available.setdefault(key, []).append((row, col))

    details = []
    for event in creation_events:
        name = event["special"]
        color = int(event.get("color", EMPTY))
        cells = available.get((name, color), [])
        final_cell = cells.pop(0) if cells else None
        value = 0
        if final_cell is not None:
            special = type_by_name[name]
            value = _created_special_effect_size(
                result.board,
                result.special_board,
                final_cell[0],
                final_cell[1],
                special,
            )
        detail = {
            "special": name,
            "color": color,
            "created_cell": list(event.get("cell") or ()),
            "final_cell": list(final_cell) if final_cell is not None else None,
            "value_cells": int(value),
            "survives": final_cell is not None,
        }
        details.append(detail)
        event["value_cells"] = int(value)
        event["final_cell"] = detail["final_cell"]
        event["survives"] = detail["survives"]

    result.created_special_values = details
    result.created_special_value = float(sum(item["value_cells"] for item in details))
    return result


def _exact_activated_special_count(result: SimulationResult) -> float:
    return float(
        sum(
            1
            for event in (result.intent_events or ())
            if event.get("type") == "special_activation"
            and event.get("special") in EXACT_VALUE_SPECIAL_NAMES
        )
    )


def _special_bonus(result: SimulationResult, mode: GameMode) -> float:
    exact_created_count = float(len(result.created_special_values or ()))
    generic_created = max(0.0, float(result.created_specials) - exact_created_count)
    exact_activated = _exact_activated_special_count(result)
    generic_activated = max(0.0, float(result.activated_specials) - exact_activated)
    if mode is GameMode.SPECIAL_O_RAMA or _EVERY_MATCH_IS_SPECIAL:
        return (
            result.created_special_value
            + generic_created * SPECIAL_O_RAMA_CREATED_BONUS
            + generic_activated * SPECIAL_O_RAMA_ACTIVATED_BONUS
        )
    return (
        result.created_special_value
        + generic_created * SPECIAL_CREATED_BONUS
        + generic_activated * SPECIAL_ACTIVATED_BONUS
    )


def _direct_swap_layer(
    cascade_matches,
    has_direct_match_layer: bool = True,
    fallback=None,
) -> list[MatchGroup]:
    """The matches the performed swap itself made, from a raw cascade list.

    `cascade_matches[0]` is that layer only when the swap matched something. A
    special+special combo with no match, a disco or skull swap, a booster or a
    perk effect starts the list with the first DROP cascade instead
    (`has_direct_match_layer` False), and every rule that reads "the combos of
    the performed swap" -- Floor Is Lava marks, the Vertical Rush and Lights Up
    multipliers, Column Mania growth, the Mixy code, a lotus -- then sees
    nothing. Found 2026-09-20 on the lotus (19:23:00, a Bomb+Bomb played for a
    "lotus collect" off a three that only fell in); the same read sat in all of
    these, e.g. Debug/runs 2026-09-18_22-23-22_330: a Floor Is Lava disco whose
    first drop cascade "marked" columns 3-6.

    `fallback` is for synthetic/unit results that carry only `matches` and no
    cascade list; it is never used for a move known to have no direct layer.
    """
    if not has_direct_match_layer:
        return []
    if cascade_matches:
        return list(cascade_matches[0] or ())
    return list(fallback or ())


def floor_lava_transition(
    cascade_matches: list[list[MatchGroup]],
    checked_columns=(),
    has_direct_match_layer: bool = True,
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Apply only swipe-created matches and return (destroyed, marks_after).

    A vertical line touches one column; a horizontal line touches every column
    occupied by the match.  Non-line shapes use the same cell-based rule, which
    naturally handles squares, L/T matches and overlapping match groups. Later
    cascade matches never check or destroy Lava columns -- and on a move whose
    swap matched nothing (``has_direct_match_layer`` False) the first entry of
    ``cascade_matches`` already IS a later cascade, so it marks nothing either.
    Whether the merge combo itself marks its own column is not modelled.

    A move that also spends the booster leaves the ground exactly as it was:
    ``FloorIsLavaBoard.AfterPerformedSwap`` returns before it reads a single
    combo when ``IsAbilityUsedThisMove`` is set, so no column is marked and none
    can erupt (see ``ability_used_this_move``).
    """
    if _ABILITY_USED_THIS_MOVE:
        return (), tuple(sorted(int(col) for col in checked_columns))
    return floor_lava_column_transition(
        _direct_swap_layer(cascade_matches, has_direct_match_layer),
        checked_columns,
    )


def floor_lava_column_transition(
    matches: list[MatchGroup],
    checked_columns=(),
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """One match layer's effect on the lava marks: (destroyed, marks_after)."""
    checked = {int(col) for col in checked_columns}
    destroyed: list[int] = []
    for match in matches:
        columns = sorted({col for _row, col in match.cells})
        for col in columns:
            if col in checked:
                checked.remove(col)
                destroyed.append(col)
            else:
                checked.add(col)
    return tuple(destroyed), tuple(sorted(checked))


def _floor_lava_eruption_cells(
    board: list[list[int]],
    columns,
) -> set[tuple[int, int]]:
    """Every piece standing in a column that erupts on this move.

    The engine keeps the counter per column (FloorIsLavaBoard.
    ColumnsEruptionDictionary) and breaks the ground under a column on its
    second match, which takes the whole column down -- measured 2026-08-19 on
    "the-floor-is-lava": one move whose match spanned four already-marked
    columns scored 28, i.e. four times the seven cells of a 7x7 column, and a
    later three-column eruption scored 21.
    """
    cells: set[tuple[int, int]] = set()
    for col in columns:
        for row, board_row in enumerate(board):
            if 0 <= col < len(board_row) and _is_board_piece(board_row[col]):
                cells.add((row, col))
    return cells


def _mushroom_weight(weights: dict[str, float]) -> float:
    """What one unit of `result.multiplier_mushrooms` is worth.

    With the toggle off the unit is one mushroom and only the mushroom mode
    pays for it, exactly as before. With it on the unit is one multiplier point,
    and it applies in every mode, because mushrooms sitting on the board are
    worth collecting whatever the mode box says (Debug 2026-08-15 05-13: mode
    "None", four mushrooms on the board, all scored at zero).

    A mushroom raises `PlayerModel.scoreMultiplier` -- the field the two
    multiplier boards are made of -- so the point it buys is worth the base
    points still to come divided by the multiplier already standing. The flat
    rate this used to be (22.0 / 2.5 = 8.8, whatever the multiplier) is close
    to that at the high multipliers where most of a run is spent, and far under
    it on the opening moves: measured at ~415 per point at x1 against ~6.8 at
    x17 (see `MUSHROOM_MULTIPLIER_POINT_VALUE`). On board model 29 the field
    walks x1 -> x20 inside a single ~90 s run, so those opening moves are a
    real and repeated part of every game, not an edge case.

    The value taken is the LARGER of the flat rate and the tapered one. That
    keeps late-run behaviour bit-for-bit what it was -- the taper only wins
    while `MUSHROOM_MULTIPLIER_POINT_VALUE / multiplier` is above 8.8, i.e.
    below about x13 -- and confines the change to the early multipliers the
    flat rate underpaid. `FINAL_PHASE_MUSHROOM_MODE_VALUE_FACTOR` still applies
    on top, unchanged: it discounts mushroom SETUP value on the last move of a
    turn, which is a different question from what the point is worth.
    """
    if not _MUSHROOM_MULTIPLIERS_ACTIVE:
        return weights.get("mushroom", 0.0)
    flat = max(
        weights.get("mushroom", 0.0),
        MODE_WEIGHTS[MULTIPLIER_MUSHROOMS_MODE]["mushroom"],
    ) / MUSHROOM_MEAN_MULTIPLIER
    tapered = MUSHROOM_MULTIPLIER_POINT_VALUE / max(1.0, _SCORE_MULTIPLIER)
    return max(flat, tapered)


def _mode_target_bonus_value(
    result: SimulationResult,
    mode: GameMode,
    weights: dict[str, float],
) -> float:
    per_target = (
        bounty_target_value()
        if mode is GameMode.BOUNTY
        else weights.get("mode_target", 0.0)
    )
    bonus = float(result.mode_targets) * float(per_target)
    if mode is GameMode.PURPLE_GEM:
        bonus += purple_gem_growth_bonus(float(result.mode_targets))
    return bonus


def evaluate_simulation(
    result: SimulationResult,
    mode: str,
    allow_square_matches: bool = False,
    score_rally_values: dict[int, float] | None = None,
    include_future_value: bool = True,
) -> MoveEvaluation:
    mode = normalize_game_mode(mode)
    if mode is GameMode.DUSTVILLE_DUEL:
        events = list(result.intent_events or ())
        for event in list(events):
            if event.get("type") == "mode_target_collect":
                _append_uncertain_refill_boundary(events, int(event["cascade"]), "dustville_random_shots")
        result = replace(result, intent_events=events)
    weights = MODE_WEIGHTS.get(mode, MODE_WEIGHTS[GameMode.NONE])
    instant_score = _instant_score(result, score_rally_values, mode)
    vegas_bonus = _vegas_views_bonus(result, score_rally_values, mode)
    special_bonus = _special_bonus(result, mode)
    blue_bonus = (
        result.blue_cells * weights["blue"]
        + result.blue_potential * weights["blue"] * CLEO_BLUE_POTENTIAL_WEIGHT
        - result.wasted_blue_cells * weights["blue"] * CLEO_BLUE_POTENTIAL_WEIGHT
    )
    mode_bonus = (
        result.created_specials * weights["mode_special"]
        + result.multiplier_mushrooms * _mushroom_weight(weights)
        + _mode_target_bonus_value(result, mode, weights)
        + result.chest_drops * weights.get("chest_drop", 0.0)
        + _mode_match_bonus(result, weights)
    )
    lights_up_points = 0.0
    if mode is GameMode.LIGHTS_UP:
        lights_up_points = _lights_up_multiplier_points(
            result.cascade_matches,
            result.matches,
            has_direct_match_layer=result.has_direct_match_layer,
        )
        mode_bonus += lights_up_points * _lights_up_multiplier_point_value(weights)
    multiplier_points = 0.0
    multiplier_setup_bonus = 0.0
    if is_multiplier_growth_mode(mode):
        # The move earns the multiplier here, so it is worth scoring for.
        growth_colors = multiplier_growth_colors(mode)
        multiplier_points = _multiplier_madness_points(
            result.cascade_matches, result.matches, growth_colors
        )
        multiplier_setup_bonus = _multiplier_madness_setup_bonus(
            result, growth_colors, mode
        )
        mode_bonus += (
            multiplier_points * _multiplier_madness_point_value(mode)
            + multiplier_setup_bonus
        )
    elif mode is GameMode.MOVES_MULTIPLIER:
        # Nothing a move does changes the multiplier -- every swap raises it by
        # one -- so no candidate can be preferred for it. What an *extra* move
        # buys is a second raise this turn, on top of its own points, and that
        # is the one thing worth pricing in this mode.
        multiplier_points = float(result.extra_moves)
        mode_bonus += multiplier_points * _score_multiplier_point_value(weights)
    column_mania_columns: tuple[int, ...] = ()
    column_mania_growth = 0.0
    if mode is GameMode.COLUMN_MANIA:
        column_mania_columns = _column_mania_growth_columns(
            result.cascade_matches,
            result.matches,
            has_direct_match_layer=result.has_direct_match_layer,
        )
        column_mania_growth = _column_mania_growth_value(column_mania_columns, weights)
        mode_bonus += column_mania_growth
    lava_destroyed: tuple[int, ...] = ()
    lava_checked_after: tuple[int, ...] = ()
    if mode is GameMode.FLOOR_IS_LAVA:
        lava_destroyed, lava_checked_after = floor_lava_transition(
            result.cascade_matches,
            _FLOOR_LAVA_CHECKED_COLUMNS,
            has_direct_match_layer=result.has_direct_match_layer,
        )
        fresh_checks = len(set(lava_checked_after) - _FLOOR_LAVA_CHECKED_COLUMNS)
        mode_bonus += (
            len(lava_destroyed) * weights.get("lava_destroy", 0.0)
            + fresh_checks * weights.get("lava_check", 0.0)
        )
    extra_move_bonus = result.extra_moves * EXTRA_MOVE_BONUS
    disco_move_bonus = result.disco_moves * DISCO_MOVE_BONUS
    board_potential = (
        min(count_legal_next_moves(result.board, result.special_board, allow_square_matches, limit=12, mode=mode), 12) * 0.4
        if include_future_value
        else 0.0
    )
    uncertain_refill_confidence = _uncertain_refill_confidence(result)
    uncertainty_penalty = 0.0
    if _has_uncertain_refill_boundary(result.intent_events):
        # The post-board itself depends on random replacement tiles, so its
        # apparent legal-move potential is not actionable even when no deeper
        # cascade happened in this particular simulation.
        board_potential = 0.0
    if uncertain_refill_confidence < 1.0:
        # extra_move_bonus/disco_move_bonus belong in the basis too: an extra
        # earned only in a post-refill cascade is the *least* certain part of the
        # estimate, yet it used to keep its full flat bonus while every other
        # component was scaled down. That does not double-penalise, because
        # _weighted_priority subtracts extra_move_bonus out of `base` before
        # re-applying it through has_reliable_same_move_extra -- but it does fix
        # the paths that rank on the raw score (top-N pruning,
        # _limited_lookahead_items, _beam_future_score's chain_score and the
        # points-only ignore_booster_value path), where an imagined extra could
        # push a safe, better move out of contention.
        uncertain_basis = sum(
            max(0.0, float(value))
            for value in (
                instant_score,
                special_bonus,
                blue_bonus,
                mode_bonus,
                extra_move_bonus,
                disco_move_bonus,
            )
        )
        uncertainty_penalty += uncertain_basis * (1.0 - uncertain_refill_confidence)
    component_score = (
        instant_score
        + special_bonus
        + blue_bonus
        + mode_bonus
        + extra_move_bonus
        + disco_move_bonus
        + board_potential
    )
    cleo_risk_adjustment = 0.0
    if result.cleo_scenario_count:
        score = result.cleo_risk_score
        cleo_risk_adjustment = score - component_score
    else:
        score = component_score
    score -= uncertainty_penalty
    # The sweep leftover cluster is a *deterministic* part of the post-board (no
    # refill involved), so it is added after the uncertainty penalty and is not
    # zeroed alongside board_potential.
    # Not gated on `include_future_value`. That flag guards `board_potential`,
    # the expensive count_legal_next_moves heuristic the beam search replaced --
    # and the live ranking path (_rank_candidate_results) passes False, which
    # silently took the sweep setup bonus down with it, so the Sweep SE evaluator
    # computed a leftover-cluster value that never reached any score. The sweep
    # cluster is a deterministic part of the post-board (no refill involved) and
    # costs nothing to read off the result, so it always applies.
    sweep_setup_bonus = result.sweep_setup_bonus
    score += sweep_setup_bonus
    # Same reasoning as the sweep leftover: the repainted area is a
    # deterministic part of the post-board (the conversion happens before any
    # refill), so it survives the uncertainty penalty and applies on every
    # ranking path, `include_future_value` or not.
    jelly_setup_bonus = _jelly_setup_bonus(result, score_rally_values)
    score += jelly_setup_bonus
    rally_state = "on" if score_rally_values else "off"
    explanation = (
        f"instant={instant_score:.1f}, special={special_bonus:.1f}, "
        f"blue={blue_bonus:.1f}, mode={mode_bonus:.1f}, extra_move={extra_move_bonus:.1f}, "
        f"disco={disco_move_bonus:.1f}, "
        f"rally={rally_state}, potential={board_potential:.1f}"
    )
    if jelly_setup_bonus or result.jelly_converted_tiles:
        explanation += (
            f", jelly={jelly_setup_bonus:.1f}"
            f"/tiles:{result.jelly_converted_tiles:.0f}"
            f"/color:{result.jelly_converted_color}"
        )
    if sweep_setup_bonus:
        explanation += (
            f", sweep_setup={sweep_setup_bonus:.1f}"
            f"/pairs:{result.sweep_setup_pairs:.0f}"
            f"/blue:{result.sweep_setup_blue_tiles:.0f}"
        )
    if mode is GameMode.CRAZY_COLUMNS:
        explanation += f", crazy_columns=x1..x{len(result.board)}:{result.crazy_columns_score:.1f}"
    if mode is GameMode.COLUMN_MANIA:
        ramp = (
            "?"
            if not _COLUMN_MANIA_MULTIPLIERS
            else "/".join(f"x{value}" for value in _COLUMN_MANIA_MULTIPLIERS)
        )
        raised = (
            "-"
            if not column_mania_columns
            else "+".join(str(col + 1) for col in column_mania_columns)
        )
        explanation += (
            f", column_mania={ramp}:{result.crazy_columns_score:.1f}"
            f"/rast:{raised}:{column_mania_growth:.1f}"
        )
    if is_multiplier_growth_mode(mode):
        label = (
            "multiplier_madness"
            if mode is GameMode.MULTIPLIER_MADNESS
            else "color_climb"
        )
        explanation += (
            f", {label}=+{multiplier_points:.0f}"
            f"/growth:{multiplier_points * _multiplier_madness_point_value(mode):.1f}"
            f"/setup:{multiplier_setup_bonus:.1f}"
        )
    if mode is GameMode.VEGAS_VIEWS:
        tiles = "+".join(f"({row + 1},{col + 1})" for row, col in sorted(_VEGAS_CELLS)) or "?"
        explanation += f", vegas={tiles}/x{_VEGAS_MULTIPLIER:.0f}/+{vegas_bonus:.1f}"
    if mode is GameMode.LIGHTS_UP:
        lit = "?" if _LIGHTS_UP_COLUMN is None else str(_LIGHTS_UP_COLUMN + 1)
        explanation += (
            f", lights_up=kolona:{lit}"
            f"/x{_LIGHTS_UP_MULTIPLIER:.0f}"
            f"/+{lights_up_points:.0f}"
            f":{lights_up_points * _lights_up_multiplier_point_value(weights):.1f}"
        )
    if result.created_special_values:
        exact_values = "+".join(
            f"{item['special']}:{item['value_cells']}"
            for item in result.created_special_values
        )
        explanation += f", created_exact={exact_values}"
    if result.cleo_scenario_count:
        explanation += (
            f", cleo=avg:{result.cleo_average_score:.1f}/worst:{result.cleo_worst_score:.1f}"
            f"/best:{result.cleo_best_score:.1f}/risk:{result.cleo_risk_score:.1f}"
            f"/extra_p:{result.cleo_extra_move_probability:.2f}"
            f"/blue_potential:{result.blue_potential:.1f}"
        )
    if _has_uncertain_refill_boundary(result.intent_events):
        explanation += (
            f", uncertain_refill=-{uncertainty_penalty:.1f}"
            f"/confidence:{uncertain_refill_confidence:.2f}"
        )
    return MoveEvaluation(
        candidate=result.candidate,
        score=score,
        instant_score=instant_score,
        special_bonus=special_bonus,
        blue_bonus=blue_bonus,
        mode_bonus=mode_bonus,
        extra_move_bonus=extra_move_bonus,
        disco_move_bonus=disco_move_bonus,
        extra_moves=result.extra_moves,
        disco_moves=result.disco_moves,
        cascade_count=result.cascade_count,
        board_potential=board_potential,
        lookahead_bonus=0.0,
        explanation=explanation,
        sweep_setup_pairs=result.sweep_setup_pairs,
        sweep_setup_blue_tiles=result.sweep_setup_blue_tiles,
        sweep_setup_bonus=sweep_setup_bonus,
        jelly_converted_tiles=result.jelly_converted_tiles,
        jelly_converted_color=result.jelly_converted_color,
        jelly_charge_cells=result.jelly_charge_cells,
        jelly_setup_bonus=jelly_setup_bonus,
        cleared_cells=result.cleared_cells,
        blue_cells=result.blue_cells,
        blue_potential=result.blue_potential,
        wasted_blue_cells=result.wasted_blue_cells,
        activated_specials=result.activated_specials,
        intent_events=result.intent_events,
        predictable_special_activated=result.predictable_special_activated,
        direct_extra_moves=result.direct_extra_moves,
        ufo_predicted_extra_moves=result.ufo_predicted_extra_moves,
        ufo_directional_predicted_extra_moves=result.ufo_directional_predicted_extra_moves,
        mode_targets=result.mode_targets,
        chest_drops=result.chest_drops,
        multiplier_mushrooms=result.multiplier_mushrooms,
        cleo_scenario_count=result.cleo_scenario_count,
        cleo_extra_move_scenarios=result.cleo_extra_move_scenarios,
        cleo_extra_move_probability=result.cleo_extra_move_probability,
        cleo_average_score=result.cleo_average_score,
        cleo_worst_score=result.cleo_worst_score,
        cleo_best_score=result.cleo_best_score,
        cleo_risk_score=result.cleo_risk_score,
        cleo_risk_adjustment=cleo_risk_adjustment,
        cleo_blue_cells_by_scenario=result.cleo_blue_cells_by_scenario,
        cleo_scenario_weights=result.cleo_scenario_weights,
        cleo_scenario_colors=result.cleo_scenario_colors,
        cleo_scenario_scores=result.cleo_scenario_scores,
        cleo_scenario_extra_moves=result.cleo_scenario_extra_moves,
        cascade_matches=result.cascade_matches,
        cleared_color_counts=dict(result.cleared_color_counts),
        froggy_lotus_gathered=result.froggy_lotus_gathered,
        has_direct_match_layer=result.has_direct_match_layer,
        floor_lava_destroyed_columns=lava_destroyed,
        floor_lava_checked_columns_after=lava_checked_after,
        direct_match_cells=result.direct_match_cells,
        direct_blue_cells=result.direct_blue_cells,
        direct_effect_cells=result.direct_effect_cells,
        direct_effect_blue_cells=result.direct_effect_blue_cells,
        effect_source_counts=dict(result.effect_source_counts),
        created_special_value=result.created_special_value,
        created_special_values=list(result.created_special_values),
        crazy_columns_score=result.crazy_columns_score,
        lights_up_multiplier_points=lights_up_points,
        vegas_bonus=vegas_bonus,
        multiplier_madness_points=(
            multiplier_points if is_multiplier_growth_mode(mode) else 0.0
        ),
        multiplier_madness_setup_bonus=multiplier_setup_bonus,
    )


def _has_uncertain_refill_boundary(intent_events) -> bool:
    return any(
        event.get("type") == "uncertain_refill_boundary"
        for event in (intent_events or ())
    )


def _uncertain_refill_confidence(result: SimulationResult) -> float:
    boundaries = []
    for event in result.intent_events or ():
        if event.get("type") != "uncertain_refill_boundary":
            continue
        try:
            # Use the same "last certain cascade" rule has_reliable_same_move_extra
            # applies, not the raw after_cascade. A deterministic wipe (Color
            # Crush, heart, Vinnie SE heart) removes a fixed colour set, so the
            # surviving pieces fall into an exactly predictable place and the very
            # next cascade is still certain. Reading after_cascade directly made
            # the two disagree on the same move: the extra gate called that
            # cascade guaranteed while this one valued it at 20%.
            boundaries.append(max(0.0, float(_last_certain_cascade(event))))
        except (TypeError, ValueError):
            boundaries.append(0.0)
    if not boundaries:
        return 1.0

    cascade_count = max(1.0, float(result.cascade_count or 0.0))
    stable_cascades = min(cascade_count, min(boundaries))
    uncertain_cascades = max(0.0, cascade_count - stable_cascades)
    if uncertain_cascades <= 0.0:
        return 1.0
    retained = UNCERTAIN_REFILL_CASCADE_RETAINED_VALUE
    confidence = (
        stable_cascades + uncertain_cascades * retained
    ) / cascade_count
    return min(1.0, max(0.0, confidence))


def _match_group_mode_bonus(matches, weights: dict[str, float]) -> float:
    # Vertical Rush's multiplier change is the first thing
    # `VerticalRushBoard.AfterPerformedSwap` skips when the player also used the
    # booster this move, so the orientation of that move's matches is worth
    # nothing either way (see ``ability_used_this_move``).
    if _ABILITY_USED_THIS_MOVE:
        return 0.0
    vertical_weight = weights.get("vertical_match", 0.0)
    horizontal_weight = weights.get("horizontal_match", 0.0)
    if vertical_weight == 0.0 and horizontal_weight == 0.0:
        return 0.0

    bonus = 0.0
    for match in matches:
        horizontal_lines, vertical_lines = _match_orientation_counts(match)
        bonus += horizontal_lines * horizontal_weight
        bonus += vertical_lines * vertical_weight
    return bonus


def _match_orientation_counts(match: MatchGroup) -> tuple[int, int]:
    """(horizontal, vertical) as Vertical Rush counts one match.

    Lines of three or more, plus the player's rule of 2026-09-20: a square
    match counts as vertical (+1). A bare 2x2 has no line of three either way,
    so until then it moved the multiplier by nothing here and a square extra
    was priced like a neutral move.
    """
    horizontal_lines, vertical_lines = _match_line_counts(match)
    if match.kind == "square" and not horizontal_lines and not vertical_lines:
        vertical_lines = 1
    return horizontal_lines, vertical_lines


def _mode_match_bonus(result: SimulationResult, weights: dict[str, float]) -> float:
    # Vertical Rush changes the multiplier in Board.AfterPerformedSwap, using
    # only the combos produced by the performed swap. Matches formed after the
    # first fall score normally but must not add/remove another multiplier
    # point. Synthetic/unit results may not carry cascade_matches, so retain
    # result.matches as their compatibility fallback. A swap that matched
    # nothing (special+special, disco, skull, booster/perk effect) has no such
    # combos at all: its first recorded cascade is already a fall, see
    # `_direct_swap_layer`.
    direct_matches = _direct_swap_layer(
        result.cascade_matches,
        getattr(result, "has_direct_match_layer", True),
        fallback=result.matches,
    )
    return _match_group_mode_bonus(direct_matches, weights)


def _mode_has_directional_match_weights(mode: GameMode | str | None) -> bool:
    """Whether the mode scores matches by orientation (Vertical Rush)."""
    weights = MODE_WEIGHTS.get(normalize_game_mode(mode), MODE_WEIGHTS[GameMode.NONE])
    return bool(weights.get("vertical_match", 0.0) or weights.get("horizontal_match", 0.0))


def _directional_match_penalty(
    result: SimulationResult,
    mode: GameMode | str | None,
) -> float:
    """The negative part of the orientation bonus, as a non-positive number.

    Vertical Rush is the only mode that charges a move for its *orientation*
    rather than for what it fails to accomplish, so a horizontal match that
    charges the booster can land at score <= 0 purely from the -1 multiplier.
    That is a cost, not a no-op, and it must not eliminate the move before the
    blue/extra priority tiers get to weigh it.
    """
    weights = MODE_WEIGHTS.get(normalize_game_mode(mode), MODE_WEIGHTS[GameMode.NONE])
    return min(0.0, _mode_match_bonus(result, weights))


def _survives_candidate_score_gate(
    evaluation: MoveEvaluation,
    result: SimulationResult,
    mode: GameMode | str | None,
) -> bool:
    """The `score > 0` admission gate, blind to the directional match penalty.

    A no-op in every mode without orientation weights, where the penalty is 0.
    """
    return evaluation.score - _directional_match_penalty(result, mode) > 0


def _survives_evaluation_score_gate(
    evaluation: MoveEvaluation,
    mode: GameMode | str | None,
) -> bool:
    """`_survives_candidate_score_gate` for paths that only carry the evaluation.

    Vertical Rush uses only the direct performed-swap layer, matching
    ``_mode_match_bonus`` and the native board hook.
    """
    weights = MODE_WEIGHTS.get(normalize_game_mode(mode), MODE_WEIGHTS[GameMode.NONE])
    matches = _performed_swap_matches(evaluation)
    penalty = min(0.0, _match_group_mode_bonus(matches, weights))
    return evaluation.score - penalty > 0


MULTIPLIER_LOSING_EXTRA_REASON = "vertical_rush_horizontal_extra"


def _loses_directional_multiplier(
    evaluation: MoveEvaluation, mode: GameMode | str | None
) -> bool:
    """Whether the swap's own matches net a multiplier loss (Vertical Rush).

    Direct layer only, like the engine: a horizontal three that falls in later
    costs nothing, and a vertical one earns nothing. An L/T with one line each
    way nets zero, a square counts as vertical, and a move that also spends the
    booster moves no multiplier at all (see ``_match_group_mode_bonus``).
    """
    if not _mode_has_directional_match_weights(mode):
        return False
    weights = MODE_WEIGHTS.get(normalize_game_mode(mode), MODE_WEIGHTS[GameMode.NONE])
    return _match_group_mode_bonus(_performed_swap_matches(evaluation), weights) < 0


def _is_multiplier_losing_extra(evaluation: MoveEvaluation) -> bool:
    """Whether ``_without_multiplier_losing_extras`` rejected this move's extra."""
    return any(
        event.get("type") == "extra_move_rejected"
        and event.get("reason") == MULTIPLIER_LOSING_EXTRA_REASON
        for event in evaluation.intent_events or ()
    )


def _without_multiplier_losing_extras(
    evaluations: list[MoveEvaluation],
    mode: GameMode | str | None,
    booster_state: BoosterState | None = None,
    score_rally_values: dict[int, float] | None = None,
) -> list[MoveEvaluation]:
    """Vertical Rush: a horizontal extra is not an extra worth having.

    Player rule (2026-09-20): an extra move whose own match is horizontal costs
    -1 on the multiplier that multiplies the whole score, so it is not played
    for the turn it keeps -- unless the move also fills the booster, which is
    worth the point. Before this the categorical extra tier took every sure
    extra ahead of anything else, the -6 orientation penalty never got a say,
    and a "random" horizontal four went before a plain vertical three.

    The extra credit is stripped rather than the move dropped: it stays in the
    pool as the plain horizontal match it otherwise is, so it can still be
    played for its blue, its special or because nothing else is left. Same
    shape as ``_without_unreliable_extra_credit`` -- the rejection is recorded
    in the intent events, the fields the extra tiers read are zeroed. The
    manual Extra Move button does not go through here; it only orders these
    behind the extras that keep the multiplier (``rank_extra_move_moves``).
    """
    if not _mode_has_directional_match_weights(mode):
        return evaluations
    kept = []
    for evaluation in evaluations:
        predicted_extra = max(evaluation.extra_moves, evaluation.direct_extra_moves)
        if (
            predicted_extra < 1.0
            or not _loses_directional_multiplier(evaluation, mode)
            or _evaluation_fills_booster(
                evaluation, booster_state, mode, score_rally_values
            )
        ):
            kept.append(evaluation)
            continue
        rejected_bonus = max(0.0, evaluation.extra_move_bonus)
        kept.append(
            replace(
                evaluation,
                score=evaluation.score - rejected_bonus,
                extra_move_bonus=0.0,
                extra_moves=0.0,
                direct_extra_moves=0.0,
                intent_events=list(evaluation.intent_events or ())
                + [
                    {
                        "type": "extra_move_rejected",
                        "reason": MULTIPLIER_LOSING_EXTRA_REASON,
                        "predicted_extra_moves": float(predicted_extra),
                    }
                ],
                explanation=(
                    f"{evaluation.explanation}, "
                    f"horizontal_extra_ignored={rejected_bonus:.1f}"
                ),
            )
        )
    return kept


def _match_line_counts(match: MatchGroup) -> tuple[int, int]:
    rows = {row for row, _ in match.cells}
    cols = {col for _, col in match.cells}
    horizontal_lines = sum(
        1
        for row in rows
        if sum(1 for cell_row, _ in match.cells if cell_row == row) >= 3
    )
    vertical_lines = sum(
        1
        for col in cols
        if sum(1 for _, cell_col in match.cells if cell_col == col) >= 3
    )
    return horizontal_lines, vertical_lines


def _score_multiplier_point_value(weights: dict[str, float]) -> float:
    """What one point of ``PlayerModel.scoreMultiplier`` is worth.

    Priced like the Lights Up point and for the same reason: the point
    multiplies every base point still to come, which in full is the whole rest
    of the match, and priced that way it decides moves on its own. One move's
    worth of base points at the current scale is real, comparable to an extra
    move at x1, and a tiebreaker by x9 -- and the division by the standing
    multiplier is the engine's own taper, not a tuning choice.
    """
    per_move = weights.get("score_multiplier", 0.0)
    if per_move <= 0.0:
        return 0.0
    remaining = _SCORE_MULTIPLIER_REMAINING_MOVES
    if remaining is not None and int(remaining) <= 0:
        # Nothing left to spend a multiplier on.
        return 0.0
    return per_move / max(1.0, _SCORE_MULTIPLIER)


# What one multiplier point is worth on the match clock, in base-cell units.
#
# A point multiplies every base point still to come, so its worth in real score
# is the base points left in the match, and in cells-cleared-now that is divided
# by the multiplier those cells would be paid at:
#
#     value = base points per second * seconds left / standing multiplier
#
# Measured 2026-09-19 on two timed solo Multiplier Madness matches (score delta
# over the standing multiplier, from the snapshots): 418 base points in 114 s
# (Mixy, 10043 pts, x40) and 422 in 113 s (Jelly, 6880 pts, x31) -- 3.7 a second
# in both, which is what makes the rate usable as a constant. Through a match
# that reads ~400 cells at the opening, ~25 at 30 s (x13), ~8 at the halfway
# mark (x25), ~3 with 20 s left and under 1 at the end. The flat 18 it replaces
# on the clock was about right at 30 s, far too low before it and too high
# after: the player's "sve na multiplier na pocetku, posle sredina, na kraju
# poeni" is this curve.
#
# The cap keeps the opening from being decided by the constant alone: past it a
# multiplier move already beats any ordinary move on the board, and a bigger
# number would only drown the choice BETWEEN multiplier moves.
#
# The floor is the player's middle-of-the-match rule (2026-09-19): "ako nema
# potez koji bas ima vise poena nego neki sa multiplierom, nek izabere
# multiplier; ako je velika razlika u poenima, onda poene". Through the second
# half the curve alone drops to 3-4 cells, where a multiplier move would lose to
# anything a couple of tiles bigger; the floor keeps it winning the near-ties
# and still losing to a move that is clearly richer. It lifts for the last
# MULTIPLIER_POINT_FLOOR_UNTIL_SECONDS, where a point has nothing left to
# multiply and only points count.
MULTIPLIER_POINT_BASE_CELLS_PER_SECOND = 3.7
MULTIPLIER_POINT_VALUE_CAP = 60.0
MULTIPLIER_POINT_VALUE_FLOOR = 6.0
MULTIPLIER_POINT_FLOOR_UNTIL_SECONDS = 15.0
# Leaving a multiplier-colour match ready for the next move is only worth
# steering for while a point is worth about a move; below this it is noise.
MULTIPLIER_READY_SETUP_MIN_POINT_VALUE = 10.0


def _multiplier_madness_point_value(mode=GameMode.MULTIPLIER_MADNESS) -> float:
    """What one point of the colour multiplier is worth, in base-cell units.

    On the match clock (timed solo, ``match_seconds_left`` supplied) it follows
    the measured curve above. Without a clock it keeps the flat strategic
    preference the player asked for earlier -- keep building the multiplier
    even when it is already high -- rather than the marginal immediate payout
    (18 / current multiplier). Moves Multiplier and the other boards retain
    their existing valuation. Shared by Multiplier Madness (purple) and Color
    Climb (the dealt pair).
    """
    if _SCORE_MULTIPLIER_REMAINING_MOVES == 0:
        return 0.0
    if _SCORE_MULTIPLIER_SECONDS_LEFT is not None:
        value = min(
            MULTIPLIER_POINT_VALUE_CAP,
            MULTIPLIER_POINT_BASE_CELLS_PER_SECOND
            * _SCORE_MULTIPLIER_SECONDS_LEFT
            / max(1.0, _SCORE_MULTIPLIER),
        )
        if _SCORE_MULTIPLIER_SECONDS_LEFT > MULTIPLIER_POINT_FLOOR_UNTIL_SECONDS:
            value = max(value, MULTIPLIER_POINT_VALUE_FLOOR)
        return value
    mode = normalize_game_mode(mode)
    weights = MODE_WEIGHTS.get(mode) or MODE_WEIGHTS[GameMode.MULTIPLIER_MADNESS]
    return float(weights["score_multiplier"])


def _ready_multiplier_matches(board, colors) -> int:
    """Multiplier-colour matches one swap away on a settled board, capped at 2.

    Counted by the cell the moved tile lands on, so two swaps into the same
    gap are one match. Unknown refill cells (EMPTY) are not pieces and can
    neither move nor complete a line.
    """
    size = len(board)
    targets = set()
    for row in range(size):
        for col in range(size):
            color = board[row][col]
            if color not in colors:
                continue
            for d_row, d_col in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                t_row, t_col = row + d_row, col + d_col
                if not (0 <= t_row < size and 0 <= t_col < size):
                    continue
                if (t_row, t_col) in targets:
                    continue
                landing = board[t_row][t_col]
                if landing == color or not _is_board_piece(landing):
                    continue
                for a_row, a_col in ((0, 1), (1, 0)):
                    run = 0
                    for sign in (1, -1):
                        n_row, n_col = t_row + sign * a_row, t_col + sign * a_col
                        while (
                            0 <= n_row < size
                            and 0 <= n_col < size
                            and (n_row, n_col) != (row, col)
                            and board[n_row][n_col] == color
                        ):
                            run += 1
                            n_row += sign * a_row
                            n_col += sign * a_col
                    if run >= 2:
                        targets.add((t_row, t_col))
                        break
            if len(targets) >= 2:
                return 2
    return len(targets)


def _multiplier_madness_setup_bonus(
    result: SimulationResult,
    colors=frozenset({PURPLE}),
    mode=GameMode.MULTIPLIER_MADNESS,
) -> float:
    """Discounted multiplier-colour match potential left by Jelly, Mixy and Sweep.

    Repainting is not a multiplier gain. Only surviving tiles of a multiplier
    colour and the sweep's estimated repaint receive setup credit, capped at
    two prospective matches and discounted to 35%. Immediate combos are counted
    separately. Use the strongest overlapping repaint estimate, never pay twice
    for tiles. ``colors`` is purple in Multiplier Madness and the player's
    dealt pair in Color Climb.
    """
    colors = frozenset(colors or ())
    if not colors:
        return 0.0

    def _survivors(color):
        return sum(value == color for row in result.board for value in row)

    tiles = (
        float(result.jelly_converted_tiles)
        if result.jelly_converted_color in colors else 0.0
    )
    for event in result.intent_events or ():
        if event.get("type") == "mixy_conversion" and event.get("selected_color") in colors:
            survivors = _survivors(event.get("selected_color"))
            tiles = max(tiles, min(float(event.get("converted_tiles", 0)), survivors))
        elif event.get("type") == "sweep_se_activation" and event.get("color") in colors:
            # Two adjacent pairs are roughly one future line of three.
            survivors = _survivors(event.get("color"))
            tiles = max(tiles, min(result.sweep_setup_pairs * 1.5, survivors)
                        + float(event.get("setup_recolour_tiles", 0)))
    expected_matches = min(2.0, max(0.0, tiles) / 3.0)
    point_value = _multiplier_madness_point_value(mode)
    # On the match clock, and while a point is still worth about a move, any
    # move is also credited for the multiplier-colour matches it leaves one
    # swap away -- the player's "ako nema ljubicaste, da spoji nesto posle cega
    # ostane ljubicasti mec" (2026-09-19). Solo only by construction: the clock
    # is supplied only there, and there the next move is always ours. Same cap
    # and the same 35% as the repaint estimate above, and the stronger of the
    # two, never both.
    if (
        _SCORE_MULTIPLIER_SECONDS_LEFT is not None
        and point_value >= MULTIPLIER_READY_SETUP_MIN_POINT_VALUE
    ):
        expected_matches = max(
            expected_matches, float(_ready_multiplier_matches(result.board, colors))
        )
    return expected_matches * 0.35 * point_value


def _multiplier_madness_points(
    cascade_matches, matches, colors=frozenset({PURPLE})
) -> float:
    """How many multiplier points a move earns in a colour-multiplier mode.

    ``MultiplierMadnessBoard.BeforeCombosDestroy`` (rva 0x5790184) walks the
    combos being destroyed, and for each one whose ``GetComboColor`` is the
    mode's colour it raises the current player's ScoreMultiplier by one (and
    takes one back off the opponent, which is not priced here -- the bot scores
    its own board). ``get_MultiplierColors`` (rva 0x578ff6c) builds a
    single-element list holding the constant 7, i.e. purple.

    ``RainbowMultiplierBoard.BeforeCombosDestroy`` (rva 0x5795358, Color Climb)
    is the same walk with the current player's two ``BoardUniquePlayerColors``
    in place of purple: an ordinary combo (type 2..8) of at least three cells
    in either colour is +1, capped at ``MatchRulesModel.maxScoreMultiplier``,
    and with ``linkedScoreMultiplier`` the opponent drops one. ``colors`` is
    that pair.

    Counted across *all* cascades, unlike Lights Up. `BeforeCombosDestroy` runs
    on every destroy pass, and the recorded match shows it: of the 22 steps the
    multiplier took, three landed inside one move's cascades.
    """
    colors = frozenset(colors or ())
    points = 0.0
    if not colors:
        return points
    if cascade_matches:
        for cascade in cascade_matches:
            for match in cascade or ():
                if match.color in colors:
                    points += 1.0
        return points
    # Synthetic/unit results may carry only `matches`, the same fallback
    # `_mode_match_bonus` and Lights Up use.
    for match in matches or ():
        if match.color in colors:
            points += 1.0
    return points


def _lights_up_multiplier_point_value(weights: dict[str, float]) -> float:
    """What one point of Lights Up multiplier is worth, in cleared-cell units.

    A point multiplies every base point still to come, so in full it is worth
    the whole rest of the match -- and priced that way it decided moves on its
    own: a 3-cell move with one point outscored a 16-cell move with a special
    and an extra move (Debug/runs 13:53:25 and 13:53:29, bonus 90-108 against
    an instant score of 3). That is not what the mode is worth in practice,
    because the multiplier climbs 1.2-1.7 a move by itself (measured over two
    whole matches played before this weight existed, Debug/memory_board
    2026-08-21: x1->x45 in 26 moves and x1->x42 in 35) -- aiming at the column
    mostly buys points the bot was going to get anyway, at the price of a
    worse board.

    So a point is priced as one move's worth of base points at the current
    scale: real, comparable to an extra move at x1, a tiebreaker by x9, and
    never enough on its own to give up a cascade or a booster charge. The
    division by the multiplier is the engine's taper, not a tuning choice.

    Only the swap's own matches are counted (see
    ``_lights_up_multiplier_points``), which is the conservative half of what
    the engine pays: 13 logged moves on 2026-08-21 gained a point where the
    bot predicted none as often as the other way round, so the term is kept
    small enough that being wrong either way costs a tiebreak, not a move.
    """
    per_move = weights.get("lights_up_multiplier", 0.0)
    if per_move <= 0.0:
        return 0.0
    remaining = _LIGHTS_UP_REMAINING_MOVES
    if remaining is not None and int(remaining) <= 0:
        # Nothing left to spend a multiplier on.
        return 0.0
    return per_move / max(1.0, _LIGHTS_UP_MULTIPLIER)


def _lights_up_multiplier_points(
    cascade_matches,
    matches,
    has_direct_match_layer: bool = True,
) -> float:
    """How many multiplier points a move's combos earn, engine rules included.

    ``LightsUpBoard`` raises the multiplier once per *combo* that has at least
    one cell in the lit column (the predicate is ``p => p.x ==
    CurrentActiveColumn``, tested with an ``Exists``), not once per cell.

    Only the swap's own matches count, like Vertical Rush. Two reasons: the
    engine-fix path (``HasEngineFix(5)``) moves the whole rule out of
    ``BeforeCombosDestroy``, which runs on every destroy pass, and into
    ``ApplyMultiplierForSwap``, which only ever sees the combos of the
    performed swap; and the player reports the same from the game -- a cascade
    that happens to fall through the lit column pays nothing, and neither does
    a special merged there without a match. The merge case is in the code
    outright: a ``MergeSwap`` combo (type 9) needs its target position in the
    lit column *and* an explosive merge, which is why a plain merge earns
    nothing here either.

    Not gated on ``IsAbilityUsedThisMove``, even though both compiled paths
    read it and return early. Two Lights Up matches recorded on 2026-08-21
    (Debug/memory_board) show the multiplier rising *while* the booster is
    resolving, with no move consumed: 11:16:14 x17->18 and 11:30:47 x37->38
    both land ~100ms after energy drops 7->0 and the ability flag turns true,
    and three more do the same. So whatever the flag gates, it is not the
    booster's own destruction -- and a booster move that clears the lit column
    is worth exactly what a swap is. Floor Is Lava and Vertical Rush keep
    their gate; theirs was checked against live moves, this one was not.
    """
    if _LIGHTS_UP_COLUMN is None:
        return 0.0
    # Synthetic/unit results may carry only `matches`, the same fallback
    # `_mode_match_bonus` uses for Vertical Rush. A swap that matched nothing
    # pays nothing here: its first recorded cascade is the very "cascade that
    # happens to fall through the lit column" above (see `_direct_swap_layer`).
    # The explosive MergeSwap point is still not modelled.
    direct = _direct_swap_layer(cascade_matches, has_direct_match_layer, matches)
    points = 0.0
    for match in direct:
        if any(int(col) == _LIGHTS_UP_COLUMN for _row, col in match.cells):
            points += 1.0
    return points


def _column_mania_multiplier(col: int) -> int:
    """The live Column Mania multiplier for one column, 1 when it is unknown."""
    multipliers = _COLUMN_MANIA_MULTIPLIERS
    if not multipliers:
        return 1
    index = int(col)
    if index < 0 or index >= len(multipliers):
        return 1
    return int(multipliers[index])


def _crazy_columns_cell_score(cells) -> float:
    """What cleared cells are worth on a board that scores by column.

    Crazy Columns is a fixed ramp -- x1 on the left, x7 on the right -- baked
    into the board at ``onGameStart`` and never touched again. Column Mania
    starts every column at x1 and raises the ones a move clears, so its
    multipliers are live state and are supplied through
    ``column_mania_state()``; when they are, they replace the ramp.
    """
    if _COLUMN_MANIA_MULTIPLIERS:
        return float(sum(_column_mania_multiplier(col) for _row, col in cells))
    return float(sum(int(col) + 1 for _row, col in cells))


def _crazy_columns_average_multiplier(board) -> float:
    """Mean column multiplier, i.e. what one cleared cell is worth on average."""
    multipliers = _COLUMN_MANIA_MULTIPLIERS
    if multipliers:
        return max(1.0, sum(int(value) for value in multipliers) / len(multipliers))
    size = len(board)
    if size <= 0:
        return 1.0
    return (size + 1) / 2.0


def _column_mania_growth_columns(
    cascade_matches,
    matches,
    has_direct_match_layer: bool = True,
) -> tuple[int, ...]:
    """Which columns this move raises by one, per ``ColumnManiaBoard``.

    ``AfterPerformedSwap`` (rva 0x5778c3c) appends the distinct column of every
    slot in ``combosToDestroy`` to ``colsToIncrease``, and ``onMoveEnd`` raises
    each of those columns by one. Only the swap's own matches are counted here,
    the same conservative half Lights Up takes: across the 60 captured Column
    Mania frames the list was already complete the first time it was seen and
    never grew through the cascade frames of a move, but the captures cannot
    prove a cascade never adds to it.

    A swap that matched nothing (special+special, disco, skull, booster/perk
    effect) therefore raises no column here: the first entry of its
    ``cascade_matches`` is a drop cascade, not the swap (`_direct_swap_layer`).
    The slots of the merge combo itself are not modelled.
    """
    if not _COLUMN_MANIA_MULTIPLIERS:
        return ()
    direct = _direct_swap_layer(cascade_matches, has_direct_match_layer, matches)
    columns = {int(col) for match in direct for _row, col in match.cells}
    return tuple(sorted(columns))


def _column_mania_growth_value(columns, weights: dict[str, float]) -> float:
    """What raising those columns is worth, in cleared-cell units.

    A raised column pays +1 on every cell cleared in it for the rest of the
    match, so like the Lights Up multiplier it is worth a share of everything
    still to come. Priced the same way and for the same reason: one move's
    worth of base points, divided by the number of columns because only one of
    them gains, and divided by the column's current multiplier because that is
    the engine's own taper -- +1 on a x1 column doubles it, +1 on a x20 column
    is a rounding error.
    """
    per_move = weights.get("column_mania_growth", 0.0)
    if per_move <= 0.0 or not columns:
        return 0.0
    remaining = _COLUMN_MANIA_REMAINING_MOVES
    if remaining is not None and int(remaining) <= 0:
        return 0.0
    size = len(_COLUMN_MANIA_MULTIPLIERS or ()) or 1
    return sum(
        per_move / size / max(1.0, float(_column_mania_multiplier(col)))
        for col in columns
    )


def _instant_score(
    result: SimulationResult,
    score_rally_values: dict[int, float] | None = None,
    mode: GameMode | str | None = GameMode.NONE,
) -> float:
    extra_cells = float(getattr(result, "expected_extra_cells", 0.0) or 0.0)
    if extra_cells:
        base = _instant_score_without_expectation(result, score_rally_values, mode)
        cell_value = (
            sum(float(v) for v in score_rally_values.values()) / len(score_rally_values)
            if score_rally_values
            else DEFAULT_CELL_SCORE
        )
        return (
            base
            + extra_cells * cell_value
            + _vegas_views_bonus(result, score_rally_values, mode)
        )
    return _instant_score_without_expectation(
        result, score_rally_values, mode
    ) + _vegas_views_bonus(result, score_rally_values, mode)


# Groups the simulator adds for a piece that fires without a colour match. In
# the engine those are Special / Ability / Manual combos, which
# VegasViewsBoard.BeforeCombosDestroy skips (type mask 0xC02).
_VEGAS_NON_MATCH_KINDS = frozenset({"special_combo", "cleo_activation", "auto_explode"})


def _vegas_views_bonus(
    result: SimulationResult,
    score_rally_values: dict[int, float] | None = None,
    mode: GameMode | str | None = GameMode.NONE,
) -> float:
    """The extra points the Vegas tile adds to this move, in instant-score units.

    Decoded from ``VegasViewsBoard.BeforeCombosDestroy`` (rva 0x579a2c0):

    * nothing at all when an ability was used this move;
    * every combo in the destroy batch is checked, the swap's and every
      cascade's alike -- there is no cascade gate;
    * a Special, Ability or Manual combo (a blast, a booster) is skipped, so a
      blast over the tile neither scores it nor uses it up;
    * the first colour combo with a cell on the tile turns the cell back to
      Normal and has ``combo.Score *= ScoreMultiplier`` -- the whole combo,
      not just the one tile, and not the rest of the move.

    The tile comes back only on the next ``onTurnStart`` (max 1, rate 1), so
    one move pays it at most once. Combos the engine also pulls in by
    ``origin`` (an L split into two, a special's blast in the same batch) are
    not modelled: the simulator merges the first and cannot place the second.
    """
    if (
        normalize_game_mode(mode) is not GameMode.VEGAS_VIEWS
        or not _VEGAS_CELLS
        or _VEGAS_MULTIPLIER <= 1.0
        or _ABILITY_USED_THIS_MOVE
    ):
        return 0.0
    for layer in result.cascade_matches or ():
        for match in layer:
            if match.kind in _VEGAS_NON_MATCH_KINDS:
                continue
            if _VEGAS_CELLS.isdisjoint(match.cells):
                continue
            value = (score_rally_values or {}).get(match.color, DEFAULT_CELL_SCORE)
            return (_VEGAS_MULTIPLIER - 1.0) * len(match.cells) * float(value)
    return 0.0


def _instant_score_without_expectation(
    result: SimulationResult,
    score_rally_values: dict[int, float] | None = None,
    mode: GameMode | str | None = GameMode.NONE,
) -> float:
    scored_mode = normalize_game_mode(mode)
    # Column Mania only scores by column when the live multipliers were
    # actually read; without them there is no ramp to fall back on -- its
    # columns are whatever the match has made them -- so it scores cells.
    if scored_mode is GameMode.CRAZY_COLUMNS or (
        scored_mode is GameMode.COLUMN_MANIA and _COLUMN_MANIA_MULTIPLIERS
    ):
        # Normalise back into "cleared cells" units. Every other weight in the
        # scorer -- EXTRA_MOVE_BONUS, the per-cell blue weight, the special and
        # comeback terms -- is calibrated against a cell count, but the raw
        # column sum runs ~4x that on a 7x7 board (mean of x1..x7). Feeding it
        # in unscaled quietly devalues extra moves and blue collection by the
        # same factor in this mode only. Dividing by the mean multiplier is a
        # uniform divisor, so the ranking *between* Crazy Columns moves is
        # untouched; only the balance against the other terms is restored.
        # The raw sum stays in crazy_columns_score for the logs.
        return float(result.crazy_columns_score) / _crazy_columns_average_multiplier(
            result.board
        )
    if not score_rally_values:
        return float(result.cleared_cells) + sum(
            count
            for color, count in (result.cleared_color_counts or {}).items()
            if color >= SPECIAL_AREA_SCORE_KEY_BASE
        )

    if result.cleared_color_counts:
        return sum(
            count
            * score_rally_values.get(
                color - SPECIAL_AREA_SCORE_KEY_BASE
                if color >= SPECIAL_AREA_SCORE_KEY_BASE
                else color,
                DEFAULT_CELL_SCORE,
            )
            for color, count in result.cleared_color_counts.items()
        )

    return sum(
        len(match.cells) * score_rally_values.get(match.color, DEFAULT_CELL_SCORE)
        for match in result.matches
    )


def _preexisting_matched_cells(
    board: list[list[int]],
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    special_board=None,
) -> set[tuple[int, int]]:
    return {
        cell
        for match in _find_matches_cached(
            board,
            allow_square_matches,
            match_scan_cache,
            special_board,
        )
        for cell in match.cells
    }


def _preexisting_match_cell_groups(
    board: list[list[int]],
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    special_board=None,
) -> list[frozenset[tuple[int, int]]]:
    return [
        match.cells
        for match in _find_matches_cached(
            board,
            allow_square_matches,
            match_scan_cache,
            special_board,
        )
    ]


def _is_activatable_special(special: int) -> bool:
    return (
        0 < special <= 4
        or special == SPECIAL_HEART
        or special == SPECIAL_ZANY_ZAPPER_1
        or special == SPECIAL_CROSSHAIR
        or is_vinnie_se_heart_special(special)
        or special in DIRECTIONAL_FIREWORK_SPECIALS
        or _is_created_special(special)
    )


def _is_created_special(special: int) -> bool:
    return (
        special >= CREATED_SPECIAL
        and not is_purple_gem_special(special)
        and not is_vinnie_se_heart_special(special)
        and special
        not in {
            SPECIAL_HEART,
            SPECIAL_KNIGHT,
            SPECIAL_CLEO_BUG,
            SPECIAL_BILLIE_DRONE,
            SPECIAL_COLOR_CRYSTAL,
            SPECIAL_DISCO_BALL,
            SPECIAL_MUSHROOM,
            SPECIAL_ALL_ABOARD_BANDIT,
            SPECIAL_JOOJOO_SKULL,
            SPECIAL_FROGGY_LOTUS,
            SPECIAL_FIREWORK_LEFT,
            SPECIAL_FIREWORK_RIGHT,
            SPECIAL_FIREWORK_UP,
            SPECIAL_FIREWORK_DOWN,
            SPECIAL_ZANY_ZAPPER_1,
            SPECIAL_ZANY_ZAPPER_2,
            SPECIAL_RED_BLUE_TILE,
            SPECIAL_SPRAY_SE,
            SPECIAL_SWEEP_SE_BROOM,
            SPECIAL_CROSSHAIR,
            # A cell marker, not a piece: without it two plain tiles on adjacent
            # Xtra cells read as a special combo the game would refuse.
            SPECIAL_XTRA_MOVE_TILE,
        }
    )


def _is_predictable_blue_special(special: int) -> bool:
    return (
        special in FIREWORK_ROCKET_SPECIALS
        or special
        in {
            SPECIAL_BOMB,
            SPECIAL_ALL_ABOARD_BANDIT,
            SPECIAL_JOOJOO_SKULL,
            SPECIAL_ZANY_ZAPPER_1,
        }
        or _is_created_special(special)
    )


def _is_fireworks_rocket_special(special: int) -> bool:
    return special in FIREWORK_ROCKET_SPECIALS


def _candidate_cleo_bug_pair(candidate: MoveCandidate) -> tuple[tuple[int, int], tuple[int, int]] | None:
    start_special = candidate.special_board[candidate.start[0]][candidate.start[1]]
    target_special = candidate.special_board[candidate.target[0]][candidate.target[1]]
    if start_special == SPECIAL_CLEO_BUG and target_special != SPECIAL_CLEO_BUG:
        return candidate.start, candidate.target
    if target_special == SPECIAL_CLEO_BUG and start_special != SPECIAL_CLEO_BUG:
        return candidate.target, candidate.start
    return None


def _candidate_disco_ball_pair(candidate: MoveCandidate) -> tuple[tuple[int, int], tuple[int, int]] | None:
    start_special = candidate.special_board[candidate.start[0]][candidate.start[1]]
    target_special = candidate.special_board[candidate.target[0]][candidate.target[1]]
    if start_special == SPECIAL_DISCO_BALL and target_special != SPECIAL_DISCO_BALL:
        return candidate.start, candidate.target
    if target_special == SPECIAL_DISCO_BALL and start_special != SPECIAL_DISCO_BALL:
        return candidate.target, candidate.start
    return None


def _candidate_joojoo_skull_pair(candidate: MoveCandidate) -> tuple[tuple[int, int], tuple[int, int]] | None:
    if _is_joojoo_skull_pair(candidate.special_board, candidate.start, candidate.target):
        return candidate.start, candidate.target
    return None


def _normalize_disco_drag_candidate(candidate: MoveCandidate) -> MoveCandidate:
    pair = _candidate_disco_ball_pair(candidate)
    if pair is None:
        return candidate
    disco_cell, partner_cell = pair
    return MoveCandidate(
        partner_cell,
        disco_cell,
        _direction_between(partner_cell, disco_cell),
        candidate.board,
        candidate.special_board,
    )


def _candidate_activates_special_swap(candidate: MoveCandidate, mode: str = "None") -> bool:
    start_row, start_col = candidate.start
    target_row, target_col = candidate.target
    start_special = candidate.special_board[start_row][start_col]
    target_special = candidate.special_board[target_row][target_col]
    if start_special in ZANY_ZAPPER_SPECIALS or target_special in ZANY_ZAPPER_SPECIALS:
        return False
    if (
        start_special in DIRECTIONAL_FIREWORK_SPECIALS
        or target_special in DIRECTIONAL_FIREWORK_SPECIALS
    ):
        return False
    if (
        normalize_game_mode(mode) is GameMode.FIREWORKS
        and (
            _is_fireworks_rocket_special(start_special)
            or _is_fireworks_rocket_special(target_special)
        )
    ):
        return False
    return (
        _is_activatable_special(start_special)
        and _is_activatable_special(target_special)
    )


def _candidate_activates_joojoo_skull_swap(candidate: MoveCandidate) -> bool:
    return _candidate_joojoo_skull_pair(candidate) is not None


def _candidate_activates_cleo_swap(candidate: MoveCandidate) -> bool:
    pair = _candidate_cleo_bug_pair(candidate)
    if pair is None:
        return False
    _bug_cell, partner_cell = pair
    return _is_board_piece(candidate.board[partner_cell[0]][partner_cell[1]])


def _candidate_drags_the_disco(candidate: MoveCandidate) -> bool:
    """Whether this swipe drags the ball itself -- the only direction that fires it.

    From the engine: `BoardAnalyzer::GetMergeSwapOutcome(board,
    mergeSourcePosition, mergeTargetPosition, isAfterSwap)` asks the *dragged*
    piece first, calling `AllowedMergeSwapWith(other, specialIsSwapSource=true)`
    on it, and only if that says no does it ask the piece landed on, with
    `specialIsSwapSource=false`. Brocco's override
    (`BroccoBoogiePieceLogic::AllowedMergeSwapWith`, rva 0x58c9ba4) answers
    `activateOnSwipeIntoPiece || specialIsSwapSource`, and
    `activateOnSwipeIntoPiece` is loaded from the ability params, where no
    captured Brocco config carries it -- so it is false and the ball fires only
    when it is the one being dragged.

    `candidate.board`/`special_board` are the board *after* the swap, so a ball
    sitting on `target` is the ball that started on `start`: the dragged one.
    """
    row, col = candidate.target
    return candidate.special_board[row][col] == SPECIAL_DISCO_BALL


def _candidate_activates_disco_swap(candidate: MoveCandidate) -> bool:
    pair = _candidate_disco_ball_pair(candidate)
    if pair is None:
        return False
    # The other swipe of the same pair is an ordinary swap, and it falls through
    # to the ordinary simulation rather than being read as an activation.
    if not _candidate_drags_the_disco(candidate):
        return False
    _disco_cell, partner_cell = pair
    target_color = candidate.board[partner_cell[0]][partner_cell[1]]
    return _is_normal_color(target_color)


def _match_contains_special(
    match: MatchGroup,
    special_board: list[list[int]],
) -> bool:
    return any(special_board[row][col] != EMPTY for row, col in match.cells)


def _extends_preexisting_match(
    match: MatchGroup,
    preexisting_match_groups: list[frozenset[tuple[int, int]]],
) -> bool:
    return any(
        match.cells.intersection(preexisting_cells)
        and not match.cells.issubset(preexisting_cells)
        for preexisting_cells in preexisting_match_groups
    )


def _is_special_extra_move_extension(
    match: MatchGroup,
    special_board: list[list[int]],
    preexisting_match_groups: list[frozenset[tuple[int, int]]],
) -> bool:
    return (
        len(match.cells) >= 4
        and _match_contains_special(match, special_board)
        and _extends_preexisting_match(match, preexisting_match_groups)
    )


def _candidate_pre_swap_special_board(candidate: MoveCandidate):
    """Rebuild the special board as it was *before* the candidate's swap.

    ``MoveCandidate`` only stores the post-swap special layout. Pairing that
    with the pre-swap colour board (as the preexisting-match scan does) lets a
    colour-flexible special the swap moved into a run -- e.g. a Vinnie SE heart
    -- hallucinate a match that never existed, which then masks the genuine new
    match. ``swap_cells`` is its own inverse for the swapped pair (Xtra Move
    tiles stay pinned in either direction), so swapping start/target back yields
    the true pre-swap special board.
    """
    _pre_board, pre_special = swap_cells(
        candidate.board,
        candidate.special_board,
        candidate.start,
        candidate.target,
    )
    return pre_special


def _created_swapped_matches(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> list[MatchGroup]:
    # Validate swappability against the *pre-swap* special layout: a swap that
    # moves a special (e.g. the froggy lotus rides a BLOCKED board cell) leaves
    # the special board post-swap with the special elsewhere, so pairing the
    # pre-swap colour board with the post-swap special board would wrongly reject
    # the lotus's old cell as an unswappable blocker.
    pre_swap_special = _candidate_pre_swap_special_board(candidate)
    if not _can_swap_pair(original_board, pre_swap_special, candidate.start, candidate.target):
        return []

    preexisting_match_groups = _preexisting_match_cell_groups(
        original_board,
        allow_square_matches,
        match_scan_cache,
        pre_swap_special,
    )
    swapped_cells = {candidate.start, candidate.target}
    return [
        match
        for match in _find_matches_cached(
            candidate.board,
            allow_square_matches,
            match_scan_cache,
            candidate.special_board,
        )
        if match.cells.intersection(swapped_cells)
        and (
            not any(match.cells.intersection(preexisting_cells) for preexisting_cells in preexisting_match_groups)
            or _is_special_extra_move_extension(match, candidate.special_board, preexisting_match_groups)
        )
    ]


def _spray_se_initial_state(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> tuple[
    MoveCandidate,
    list[tuple[int, int]],
    int,
    list[MatchGroup],
    list[frozenset[tuple[int, int]]],
] | None:
    transformed = _spray_se_transformed_candidate(candidate)
    if transformed is None:
        return None

    transformed_candidate, ray_cells, spray_color = transformed
    preexisting_match_groups = _preexisting_match_cell_groups(
        original_board,
        allow_square_matches,
        match_scan_cache,
        candidate.special_board,
    )
    origins = _identity_origins(transformed_candidate.board)
    ray_cell_set = set(ray_cells)
    matches = [
        match
        for match in _filter_stale_matches(
            _find_matches_cached(
                transformed_candidate.board,
                allow_square_matches,
                match_scan_cache,
                transformed_candidate.special_board,
            ),
            origins,
            preexisting_match_groups,
        )
        if match.cells.intersection(ray_cell_set)
    ]
    return (
        transformed_candidate,
        ray_cells,
        spray_color,
        matches,
        preexisting_match_groups,
    )


def _spray_se_created_matches(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> list[MatchGroup]:
    state = _spray_se_initial_state(
        original_board,
        candidate,
        allow_square_matches,
        match_scan_cache,
    )
    if state is None:
        return []
    _transformed_candidate, _ray_cells, _spray_color, matches, _stale = state
    return matches


def _sweep_se_initial_state(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> tuple[
    MoveCandidate,
    list[tuple[int, int]],
    int,
    list[MatchGroup],
    list[frozenset[tuple[int, int]]],
] | None:
    transformed = _sweep_se_transformed_candidate(candidate)
    if transformed is None:
        return None

    transformed_candidate, swept_cells, target_color = transformed
    preexisting_match_groups = _preexisting_match_cell_groups(
        original_board,
        allow_square_matches,
        match_scan_cache,
        candidate.special_board,
    )
    origins = _identity_origins(transformed_candidate.board)
    swept_cell_set = set(swept_cells)
    # Only credit matches that include a swept target-colour tile, mirroring
    # the Spray SE evaluator: incidental alignments among the shuffled
    # non-target tiles must not inflate a weak sweep.
    matches = [
        match
        for match in _filter_stale_matches(
            _find_matches_cached(
                transformed_candidate.board,
                allow_square_matches,
                match_scan_cache,
                transformed_candidate.special_board,
            ),
            origins,
            preexisting_match_groups,
        )
        if match.cells.intersection(swept_cell_set)
    ]
    return (
        transformed_candidate,
        swept_cells,
        target_color,
        matches,
        preexisting_match_groups,
    )


def _sweep_se_created_matches(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> list[MatchGroup]:
    state = _sweep_se_initial_state(
        original_board,
        candidate,
        allow_square_matches,
        match_scan_cache,
    )
    if state is None:
        return []
    _transformed_candidate, _swept_cells, _target_color, matches, _stale = state
    return matches


def _candidate_creates_swapped_match(
    original_board: list[list[int]],
    candidate: MoveCandidate,
    allow_square_matches: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    mode: str = "None",
) -> bool:
    return (
        _candidate_activates_cleo_swap(candidate)
        or _candidate_activates_disco_swap(candidate)
        or _candidate_activates_joojoo_skull_swap(candidate)
        or _candidate_activates_special_swap(candidate, mode)
        or bool(_spray_se_created_matches(original_board, candidate, allow_square_matches, match_scan_cache))
        or bool(_sweep_se_created_matches(original_board, candidate, allow_square_matches, match_scan_cache))
        or bool(_created_swapped_matches(original_board, candidate, allow_square_matches, match_scan_cache))
    )


# Lightning + Lightning merges into FourthOfJuly: GetFireworks(amount=24).
FOURTH_OF_JULY_TARGET_COUNT = 24
_MERGE_LINE_SPECIALS = frozenset({SPECIAL_HORIZONTAL, SPECIAL_VERTICAL})
_MERGE_CLASSIC_SPECIALS = _MERGE_LINE_SPECIALS | {SPECIAL_BOMB, SPECIAL_LIGHTNING}


def _merge_swap_effect_cells(
    board: list[list[int]],
    special_board: list[list[int]],
    candidate: MoveCandidate,
    start_special: int,
    target_special: int,
    intent_events: list[dict],
) -> set[tuple[int, int]] | None:
    """What the engine destroys when two classic specials are swapped together.

    Decoded from libil2cpp.so on 2026-09-15 (GameLogic.ValidSwapPerformed
    0x5749a34 -> GetMergeSwapOutcome 0x5720ad0 -> GetAreaOfEffectDestructionSlots
    0x5722468) and matching what the player describes. EVERY merged effect is
    centred on the swipe's END cell -- where the dragged piece lands, i.e.
    ``candidate.target`` on this post-swap board -- never on the cell the other
    piece stands on:

    * two lines (H+V, H+H, V+V): one Cross, the full row plus the full column
      through the end cell; the lines do not fire on their own;
    * lightning + lightning: FourthOfJuly, 24 random targets;
    * any other classic pair (lightning+bomb, bomb+line, lightning+line): no
      merge -- both pieces fire their own normal effect, both from the end cell,
      the dragged one first.

    Bomb+bomb keeps its own branch in the caller. Anything else (hearts,
    crosshairs, booster pieces with their own merge logic) returns None and is
    simulated as before.

    The simulator used to fire the second piece from its own cell, one step
    away: 2026-09-15 00:10:51 a green vertical onto a red horizontal swept the
    row BELOW the end cell, set off four more specials there and predicted +4
    charge where the game gave +1.
    """
    if start_special not in _MERGE_CLASSIC_SPECIALS or target_special not in _MERGE_CLASSIC_SPECIALS:
        return None
    if start_special == SPECIAL_BOMB and target_special == SPECIAL_BOMB:
        return None
    size = len(board)
    end_row, end_col = candidate.target
    both = {candidate.start, candidate.target}

    def _record(name: str, cells: set[tuple[int, int]]) -> None:
        intent_events.append(
            {
                "type": "special_effect",
                "cascade": 1,
                "special": name,
                "cell": _intent_cell(candidate.target),
                "cleared_cells": len(cells),
                "blue_cells": sum(
                    1 for row, col in cells if is_booster_charge_color(board[row][col])
                ),
                "activated_specials": _intent_cells(
                    _special_chain_targets(
                        board, special_board, cells, candidate.target, excluded_cells=both
                    )
                ),
            }
        )

    if start_special in _MERGE_LINE_SPECIALS and target_special in _MERGE_LINE_SPECIALS:
        cells = {
            (row, col)
            for row in range(size)
            for col in range(size)
            if (row == end_row or col == end_col) and _is_board_piece(board[row][col])
        }
        _record("line_cross", cells)
        return cells
    if start_special == SPECIAL_LIGHTNING and target_special == SPECIAL_LIGHTNING:
        cells = _random_board_wide_effect_cells(
            board, end_row, end_col, FOURTH_OF_JULY_TARGET_COUNT, both
        )
        # Named "lightning" so the random-refill boundary is recorded for it.
        _record(_special_intent_name(SPECIAL_LIGHTNING), cells)
        return cells
    cells: set[tuple[int, int]] = set()
    for special in (target_special, start_special):  # dragged piece first
        effect = _special_effect_cells(
            board, special_board, end_row, end_col, special, excluded_cells=cells | both
        )
        _record(_special_intent_name(special), effect)
        cells |= effect
    return cells


def _simulate_special_swap_candidate(
    candidate: MoveCandidate,
    max_cascades: int = 40,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    original_board: list[list[int]] | None = None,
) -> SimulationResult:
    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    origins = _candidate_origins(candidate)
    direct_matches = (
        _created_swapped_matches(
            original_board,
            candidate,
            allow_square_matches,
            match_scan_cache,
        )
        if original_board is not None
        else []
    )
    # Only the dragged piece travels: it lands on the target cell and can
    # complete a colour match there. The other special stays put and detonates,
    # so a match through the *source* cell never happens -- and keeping it would
    # make the two swipe directions score identically, which is exactly why the
    # bot used to swipe the wrong way and lose the extra move.
    direct_matches = [
        match for match in direct_matches if candidate.target in match.cells
    ]
    direct_match_cells = {
        cell for match in direct_matches for cell in match.cells
    }
    start_special = special_board[candidate.start[0]][candidate.start[1]]
    target_special = special_board[candidate.target[0]][candidate.target[1]]
    # Bomb+bomb is the only ordinary two-special swap whose combined board
    # effect is modelled explicitly below.  Other pairs are currently simulated
    # as two independent activations.  That is useful for rough scoring, but it
    # is not strong enough evidence to promise an Extra Move created by the
    # resulting drop: the real game can resolve the joint combo differently.
    # We still count an Xtra tile collected by the initial effect, but suppress
    # cascade match-4 claims from an unverified combo.
    cascade_extra_is_verified = (
        start_special == SPECIAL_BOMB and target_special == SPECIAL_BOMB
    )
    suppressed_special_effect_cells = set()
    # A special+special swap can also create a normal match. The game awards
    # that direct match-4/5 Extra Move while activating the two specials. The
    # old special-combo path cleared the specials first and never recorded the
    # match, so the dedicated Extra Move action incorrectly returned ``none``.
    initial_cells = {candidate.start, candidate.target}.union(direct_match_cells)
    intent_events = []
    _append_match_intent_events(intent_events, direct_matches, 1)
    active_funky_cells = set(_FUNKY_TILE_CELLS)
    # UFO SE: a special+special swap counts as a match of the *dragged* piece's
    # colour -- a red bomb pulled into a green one reads as red -- so the eye
    # locks onto it exactly as it would onto an ordinary line. One eye takes the
    # dragged piece's colour, a second the other special's (recorded 2 eye swaps,
    # Debug/research 20261102; not yet confirmed in the disassembly).
    ufo_eyes_left = _ufo_eyes_this_move()
    ufo_abducted_colors: set[int] = set()
    dragged_color = board[candidate.target[0]][candidate.target[1]]
    other_color = board[candidate.start[0]][candidate.start[1]]
    ufo_swap_colors = _ufo_abduction_colors(
        [match.color for match in direct_matches] + [dragged_color, other_color],
        ufo_abducted_colors,
        ufo_eyes_left,
    )
    ufo_pending_colors: list[int] = []
    ufo_has_fired = False
    if ufo_swap_colors:
        ufo_eyes_left -= len(ufo_swap_colors)
        ufo_abducted_colors.update(ufo_swap_colors)
        ufo_pending_colors.extend(ufo_swap_colors)
    if start_special == SPECIAL_BOMB and target_special == SPECIAL_BOMB:
        bomb_effect_cells = _bomb_bomb_effect_cells(board, *candidate.target)
        initial_cells.update(bomb_effect_cells)
        suppressed_special_effect_cells = {candidate.start, candidate.target}
        combo_activated = _special_chain_targets(
            board,
            special_board,
            bomb_effect_cells,
            candidate.target,
            excluded_cells={candidate.start, candidate.target},
        )
        intent_events.append(
            {
                "type": "special_effect",
                "cascade": 1,
                "special": "bomb_bomb",
                "cell": _intent_cell(candidate.target),
                "cleared_cells": len(bomb_effect_cells),
                "blue_cells": sum(
                    1
                    for row, col in bomb_effect_cells
                    if is_booster_charge_color(board[row][col])
                ),
                "activated_specials": _intent_cells(combo_activated),
            }
        )

    event_start = len(intent_events)
    merge_cells = _merge_swap_effect_cells(
        board, special_board, candidate, start_special, target_special, intent_events
    )
    if merge_cells is not None:
        initial_cells.update(merge_cells)
        suppressed_special_effect_cells = {candidate.start, candidate.target}
    random_refill_tracker = []
    xtra_move_counter = []
    (
        cleared,
        activated,
        cleared_cell_set,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        cleared_color_counts,
    ) = _clear_cells_with_specials(
        board,
        special_board,
        initial_cells,
        suppressed_special_effect_cells=suppressed_special_effect_cells,
        intent_events=intent_events,
        cascade_number=1,
        extra_move_counter=xtra_move_counter,
    )
    random_refill_after_cascade = (
        1
        if _mark_color_clear_random_refill_boundary(intent_events, event_start, 1)
        else None
    )
    # Jelly SE: a special+special swap converts the zone like a match does, in
    # the DRAGGED piece's colour -- but only when the dragged piece lands inside
    # the zone. Stated by the player 2026-09-15: a red lightning inside the zone
    # swiped onto a purple one outside just detonates the pair and the jelly is
    # untouched; the purple one swiped onto the red one converts the whole zone
    # to purple. Before this the simulator knew no combo conversion at all, so
    # both swipe directions of a pair looked alike to the jelly tier and the
    # 2026-09-15 00:01:55 lightning pair was merged on the outside cell.
    jelly_converted_origins: set = set()
    if candidate.target in _JELLY_ZONE_CELLS and _is_normal_color(dragged_color):
        combo_as_match = MatchGroup(
            cells=frozenset({candidate.target}),
            color=int(dragged_color),
            kind="special_combo",
        )
        conversion_start = len(intent_events)
        _apply_jelly_zone_conversion(
            board,
            special_board,
            list(direct_matches) + [combo_as_match],
            set(_JELLY_ZONE_CELLS),
            intent_events,
            1,
        )
        # Before gravity, so the repainted cells still sit where their origin
        # grid names them -- same bookkeeping as the ordinary path.
        for event in intent_events[conversion_start:]:
            if event.get("type") == JELLY_ZONE_CONVERSION_EVENT:
                for row, col in event.get("cells") or ():
                    if origins[row][col] is not None:
                        jelly_converted_origins.add(origins[row][col])
    for row, col in cleared_cell_set:
        origins[row][col] = None
    board, special_board, origins = _drop_and_refill(board, special_board, origins)
    counted_chest_origins = set()
    chest_drops = _count_new_chest_drops(board, origins, counted_chest_origins)

    all_matches = list(direct_matches)
    cascade_matches = [list(direct_matches)] if direct_matches else []
    cleared_cells = cleared
    crazy_columns_score = _crazy_columns_cell_score(cleared_cell_set)
    activated_specials = activated
    created_specials = 0
    direct_extra_moves = _count_direct_extra_move_matches(direct_matches)
    extra_moves = _count_extra_move_matches(direct_matches)
    if xtra_move_counter:
        extra_moves += 1
    xtra_extra_move_awarded = bool(xtra_move_counter)
    cascade_count = 1 if cleared or activated else 0
    stale_match_cells = _preexisting_match_cell_groups(
        candidate.board,
        allow_square_matches,
        match_scan_cache,
        candidate.special_board,
    )

    auto_explode_tags = set()
    for _ in range(max_cascades - 1):
        next_cascade = cascade_count + 1
        past_random_refill_boundary = (
            random_refill_after_cascade is not None
            and next_cascade > random_refill_after_cascade
        )
        if past_random_refill_boundary and not ufo_pending_colors:
            break
        if past_random_refill_boundary:
            matches = []
        else:
            matches = _filter_stale_matches(
                _find_matches_cached(
                    board,
                    allow_square_matches,
                    match_scan_cache,
                    special_board,
                ),
                origins,
                stale_match_cells,
            )
        matches = _with_auto_explosions(matches, board, origins, auto_explode_tags, past_random_refill_boundary)
        auto_explode_tags = set()
        # Same deferred pull as the ordinary path: the eyes collect once the
        # cascades this combo started have finished resolving.
        ufo_settled_wipe: tuple[int, ...] = ()
        if not matches:
            if not ufo_pending_colors:
                break
            ufo_settled_wipe = tuple(ufo_pending_colors)
            ufo_pending_colors = []
            ufo_has_fired = True
        else:
            cascade_count += 1
            all_matches.extend(matches)
            cascade_matches.append(matches)
            _append_match_intent_events(intent_events, matches, cascade_count)
        cascade_extra_moves = _count_extra_move_matches(matches)
        if cascade_extra_moves and not cascade_extra_is_verified:
            intent_events.append(
                {
                    "type": "extra_move_rejected",
                    "cascade": cascade_count,
                    "reason": "unverified_special_swap_combo",
                    "predicted_extra_moves": cascade_extra_moves,
                }
            )
        else:
            extra_moves += cascade_extra_moves
        # Like ordinary swaps, a special swap may supply additional distinct
        # colours through natural cascades before its one passive fire.
        if matches and ufo_eyes_left > 0 and not ufo_has_fired:
            locked = _ufo_abduction_colors(
                [match.color for match in matches], ufo_abducted_colors, ufo_eyes_left
            )
            if locked:
                ufo_eyes_left -= len(locked)
                ufo_abducted_colors.update(locked)
                ufo_pending_colors.extend(locked)
                intent_events.append({
                    "type": "ufo_color_lock",
                    "cascade": int(cascade_count),
                    "colors": [int(color) for color in locked],
                    "source": "cascade",
                })
        if ufo_settled_wipe:
            intent_events.append(
                {
                    "type": UFO_ABDUCTION_EVENT,
                    "cascade": int(cascade_count + 1),
                    "colors": [int(color) for color in ufo_settled_wipe],
                }
            )
        event_start = len(intent_events)
        xtra_move_counter = []
        classic_before = _classic_specials(special_board, explode_created_specials_immediately, mode)
        (
            cleared,
            activated,
            created,
            cleared_cell_set,
            cleared_blue,
            cleared_mushrooms,
            cleared_mode_targets,
            cleared_predictable_special,
            color_counts,
        ) = _clear_matches_with_details(
            board,
            special_board,
            matches,
            mode,
            intent_events=intent_events,
            cascade_number=cascade_count,
            extra_move_counter=xtra_move_counter,
            active_funky_cells=active_funky_cells,
            ufo_abducted_colors=ufo_settled_wipe,
        )
        if xtra_move_counter and not xtra_extra_move_awarded:
            extra_moves += 1
            xtra_extra_move_awarded = True
        if _mark_color_clear_random_refill_boundary(
            intent_events,
            event_start,
            cascade_count,
        ):
            random_refill_after_cascade = cascade_count
        for row, col in cleared_cell_set:
            origins[row][col] = None
        cleared_cells += cleared
        crazy_columns_score += _crazy_columns_cell_score(cleared_cell_set)
        _merge_color_counts(cleared_color_counts, color_counts)
        blue_cells += cleared_blue
        activated_specials += activated
        created_specials += created
        multiplier_mushrooms += cleared_mushrooms
        mode_targets += cleared_mode_targets
        predictable_special_activated = predictable_special_activated or cleared_predictable_special
        _tag_auto_explosions(special_board, origins, classic_before, auto_explode_tags)
        board, special_board, origins = _drop_and_refill(board, special_board, origins, chain_combos=_chain_combo_count(matches))
        chest_drops += _count_new_chest_drops(board, origins, counted_chest_origins)

    jelly_surviving_tiles = 0
    if jelly_converted_origins:
        jelly_surviving_tiles = sum(
            1
            for row in range(len(board))
            for col in range(len(board[row]))
            if origins[row][col] in jelly_converted_origins
        )
    return _apply_jelly_conversion_value(SimulationResult(
        candidate=candidate,
        board=board,
        special_board=special_board,
        matches=all_matches,
        cascade_matches=cascade_matches,
        has_direct_match_layer=bool(direct_matches),
        cascade_count=cascade_count,
        cleared_cells=cleared_cells,
        cleared_color_counts=cleared_color_counts,
        blue_cells=blue_cells + _chest_blue(chest_drops),
        created_specials=created_specials,
        activated_specials=activated_specials,
        extra_moves=extra_moves,
        direct_extra_moves=direct_extra_moves,
        multiplier_mushrooms=multiplier_mushrooms,
        mode_targets=mode_targets,
        chest_drops=chest_drops,
        predictable_special_activated=predictable_special_activated,
        intent_events=intent_events,
        direct_match_cells=float(len(direct_match_cells)),
        direct_blue_cells=float(
            sum(
                1
                for row, col in direct_match_cells
                if is_booster_charge_color(candidate.board[row][col])
            )
        ),
        direct_effect_cells=float(cleared),
        direct_effect_blue_cells=float(blue_cells),
        effect_source_counts={
            EffectSource.DIRECT_MATCH.value: float(len(direct_match_cells)),
            EffectSource.SPECIAL.value: max(
                0.0, float(cleared) - float(len(direct_match_cells))
            ),
            EffectSource.CASCADE.value: max(0.0, float(cleared_cells) - float(cleared)),
        },
        crazy_columns_score=crazy_columns_score,
    ), jelly_surviving_tiles)


def _simulate_joojoo_skull_swap_candidate(
    candidate: MoveCandidate,
    max_cascades: int = 40,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
    original_board: list[list[int]] | None = None,
) -> SimulationResult | None:
    pair = _candidate_joojoo_skull_pair(candidate)
    if pair is None:
        return None
    start_cell, target_cell = pair
    start_row, start_col = start_cell
    target_row, target_col = target_cell

    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    origins = _candidate_origins(candidate)
    active_funky_cells = set(_FUNKY_TILE_CELLS)
    dragged_color = int(board[target_row][target_col])
    joined_color = int(board[start_row][start_col])
    # Like any special+special swap, the dragged skull can complete a colour
    # line where it lands, and a four there is a direct extra (player,
    # 2026-09-26 20:21:35: yellow skull dragged onto a red one made four yellow
    # skulls in a column; the pair was scored as a bare combo with no extra).
    direct_matches = [
        match
        for match in (
            _created_swapped_matches(
                original_board,
                candidate,
                allow_square_matches,
                match_scan_cache,
            )
            if original_board is not None
            else []
        )
        if target_cell in match.cells
    ]
    initial_cells = {start_cell, target_cell}
    initial_cells.update(cell for match in direct_matches for cell in match.cells)
    initial_cells.update(
        _joojoo_skull_effect_cells_for_color(board, special_board, target_row, target_col, dragged_color)
    )
    initial_cells.update(
        _joojoo_skull_effect_cells_for_color(board, special_board, target_row, target_col, joined_color)
    )
    special_board[start_row][start_col] = EMPTY
    special_board[target_row][target_col] = EMPTY

    random_refill_tracker = []
    xtra_move_counter = []
    intent_events: list[dict] = []
    _append_match_intent_events(intent_events, direct_matches, 1)
    intent_events.append(
        {
            "type": "special_effect",
            "cascade": 1,
            "special": "joojoo_skull",
            "cell": _intent_cell(target_cell),
            "colors": [dragged_color, joined_color],
            "cleared_cells": len(initial_cells),
        }
    )
    (
        cleared,
        activated,
        cleared_cell_set,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        cleared_color_counts,
    ) = _clear_cells_with_specials(
        board,
        special_board,
        initial_cells,
        intent_events=intent_events,
        cascade_number=1,
        random_refill_tracker=random_refill_tracker,
        extra_move_counter=xtra_move_counter,
    )
    random_refill_after_cascade = 1 if random_refill_tracker else None
    activated += 2
    predictable_special_activated = True
    for row, col in cleared_cell_set:
        origins[row][col] = None
    board, special_board, origins = _drop_and_refill(board, special_board, origins)
    counted_chest_origins = set()
    chest_drops = _count_new_chest_drops(board, origins, counted_chest_origins)

    all_matches = list(direct_matches)
    cascade_matches = [list(direct_matches)] if direct_matches else []
    cleared_cells = cleared
    crazy_columns_score = _crazy_columns_cell_score(cleared_cell_set)
    activated_specials = activated
    created_specials = 0
    direct_extra_moves = _count_direct_extra_move_matches(direct_matches)
    extra_moves = direct_extra_moves + (1 if xtra_move_counter else 0)
    xtra_extra_move_awarded = bool(xtra_move_counter)
    cascade_count = 1 if cleared or activated else 0
    stale_match_cells = _preexisting_match_cell_groups(
        candidate.board,
        allow_square_matches,
        match_scan_cache,
        candidate.special_board,
    )

    auto_explode_tags = set()
    for _ in range(max_cascades - 1):
        next_cascade = cascade_count + 1
        if (
            random_refill_after_cascade is not None
            and next_cascade > random_refill_after_cascade
        ):
            break
        matches = _filter_stale_matches(
            _find_matches_cached(
                board,
                allow_square_matches,
                match_scan_cache,
                special_board,
            ),
            origins,
            stale_match_cells,
        )
        matches = _with_auto_explosions(matches, board, origins, auto_explode_tags, False)
        auto_explode_tags = set()
        if not matches:
            break
        cascade_count += 1
        all_matches.extend(matches)
        cascade_matches.append(matches)
        _append_match_intent_events(intent_events, matches, cascade_count)
        extra_moves += _count_extra_move_matches(matches)
        random_refill_tracker = []
        xtra_move_counter = []
        classic_before = _classic_specials(special_board, explode_created_specials_immediately, mode)
        (
            cleared,
            activated,
            created,
            cleared_cell_set,
            cleared_blue,
            cleared_mushrooms,
            cleared_mode_targets,
            cleared_predictable_special,
            color_counts,
        ) = _clear_matches_with_details(
            board,
            special_board,
            matches,
            mode,
            intent_events=intent_events,
            cascade_number=cascade_count,
            random_refill_tracker=random_refill_tracker,
            extra_move_counter=xtra_move_counter,
            active_funky_cells=active_funky_cells,
        )
        if xtra_move_counter and not xtra_extra_move_awarded:
            extra_moves += 1
            xtra_extra_move_awarded = True
        if random_refill_tracker:
            random_refill_after_cascade = cascade_count
        for row, col in cleared_cell_set:
            origins[row][col] = None
        cleared_cells += cleared
        crazy_columns_score += _crazy_columns_cell_score(cleared_cell_set)
        _merge_color_counts(cleared_color_counts, color_counts)
        blue_cells += cleared_blue
        activated_specials += activated
        created_specials += created
        multiplier_mushrooms += cleared_mushrooms
        mode_targets += cleared_mode_targets
        predictable_special_activated = predictable_special_activated or cleared_predictable_special
        _tag_auto_explosions(special_board, origins, classic_before, auto_explode_tags)
        board, special_board, origins = _drop_and_refill(board, special_board, origins, chain_combos=_chain_combo_count(matches))
        chest_drops += _count_new_chest_drops(board, origins, counted_chest_origins)

    return SimulationResult(
        candidate=candidate,
        board=board,
        special_board=special_board,
        matches=all_matches,
        cascade_matches=cascade_matches,
        has_direct_match_layer=bool(direct_matches),
        direct_extra_moves=direct_extra_moves,
        cascade_count=cascade_count,
        cleared_cells=cleared_cells,
        cleared_color_counts=cleared_color_counts,
        blue_cells=blue_cells + _chest_blue(chest_drops),
        created_specials=created_specials,
        activated_specials=activated_specials,
        extra_moves=extra_moves,
        multiplier_mushrooms=multiplier_mushrooms,
        mode_targets=mode_targets,
        chest_drops=chest_drops,
        predictable_special_activated=predictable_special_activated,
        intent_events=intent_events,
        crazy_columns_score=crazy_columns_score,
    )


def _simulate_disco_candidate(
    candidate: MoveCandidate,
    max_cascades: int = 40,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
    match_scan_cache: dict[tuple, list[MatchGroup]] | None = None,
) -> SimulationResult | None:
    pair = _candidate_disco_ball_pair(candidate)
    if pair is None:
        return None
    disco_cell, partner_cell = pair
    target_color = candidate.board[partner_cell[0]][partner_cell[1]]
    if not _is_normal_color(target_color):
        return None
    candidate = _normalize_disco_drag_candidate(candidate)
    pair = _candidate_disco_ball_pair(candidate)
    if pair is None:
        return None
    disco_cell, partner_cell = pair
    # candidate.board is after the swap, so the ball started on the partner's cell.
    if _ENGINE_BALL_SPENT is not None:
        _ENGINE_BALL_SPENT(partner_cell)

    board = clone_grid(candidate.board)
    special_board = clone_grid(candidate.special_board)
    origins = _candidate_origins(candidate)
    spent_cell = disco_cell
    # A ball dragged onto a special merges with it: the special keeps its own cell
    # and fires there (recorded 010847 009; 26 such simulations, nothing else moved).
    if special_board[partner_cell[0]][partner_cell[1]]:
        for grid in (board, special_board, origins):
            grid[disco_cell[0]][disco_cell[1]], grid[partner_cell[0]][partner_cell[1]] = (
                grid[partner_cell[0]][partner_cell[1]], grid[disco_cell[0]][disco_cell[1]]
            )
        spent_cell = partner_cell
    active_funky_cells = set(_FUNKY_TILE_CELLS)
    initial_cells = {
        (row, col)
        for row, values in enumerate(board)
        for col, value in enumerate(values)
        if value == target_color
    }
    initial_cells.add(spent_cell)
    # Drillin' Down: the ball's activation drills its own column, from the ball
    # down (recorded Debug/research 20261103_005457, not the wiped tiles' columns).
    if normalize_game_mode(mode) is GameMode.DRILLIN_DOWN:
        ball_row, ball_col = disco_cell
        initial_cells.update(
            (row, ball_col) for row in range(ball_row, len(board)) if _is_board_piece(board[row][ball_col])
        )

    random_refill_tracker = []
    xtra_move_counter = []
    intent_events: list[dict] = []
    intent_events.append(
        {
            "type": "special_effect",
            "cascade": 1,
            "special": "disco_ball",
            "cell": _intent_cell(disco_cell),
            "color": int(target_color),
            "cleared_cells": len(initial_cells),
        }
    )
    (
        cleared,
        activated,
        cleared_cell_set,
        cleared_blue,
        cleared_mushrooms,
        mode_targets,
        predictable_special_activated,
        cleared_color_counts,
    ) = _clear_cells_with_specials(
        board,
        special_board,
        initial_cells,
        intent_events=intent_events,
        cascade_number=1,
        random_refill_tracker=random_refill_tracker,
        extra_move_counter=xtra_move_counter,
        consumed_disco_cells={spent_cell},
    )
    random_refill_after_cascade = 1 if random_refill_tracker else None
    for row, col in cleared_cell_set:
        origins[row][col] = None
    board, special_board, origins = _drop_and_refill(board, special_board, origins)
    counted_chest_origins = set()
    chest_drops = _count_new_chest_drops(board, origins, counted_chest_origins)

    all_matches = []
    cascade_matches = []
    cleared_cells = cleared
    crazy_columns_score = _crazy_columns_cell_score(cleared_cell_set)
    # The Brocco disco's own clear never charges the booster, including when its
    # selected partner colour is blue. Any `cleared_blue` counted in this direct
    # phase belongs to the colour wipe or a special detonated by it, and the game
    # does not credit either source. Measured on the
    # 2026-08-10 21:1x game: 4 clean cases where the ball destroyed a special and
    # the charge did not move at all (0->0 with the next move's gain fully
    # accounting for the later rise), against a disco that destroyed no special
    # and charged normally. Cascade matches after the drop still count; they are
    # ordinary matches and are added below.
    #
    # Zero charge is not the same as no cost, though: those blue tiles are gone
    # from the board, so they cannot charge the meter on any later move either.
    # Kept as `wasted_blue_cells` and scored as a loss, otherwise a wipe that
    # burns nine blue for points looks free next to one that burns none.
    wasted_blue_cells = float(cleared_blue)
    blue_cells = 0
    activated_specials = activated
    created_specials = 0
    multiplier_mushrooms = cleared_mushrooms
    extra_moves = 1 if xtra_move_counter else 0
    xtra_extra_move_awarded = bool(xtra_move_counter)
    disco_moves = 1
    cascade_count = 1 if cleared or activated else 0
    stale_match_cells = _preexisting_match_cell_groups(
        candidate.board,
        allow_square_matches,
        match_scan_cache,
        candidate.special_board,
    )

    auto_explode_tags = set()
    for _ in range(max_cascades - 1):
        next_cascade = cascade_count + 1
        if (
            random_refill_after_cascade is not None
            and next_cascade > random_refill_after_cascade
        ):
            break
        matches = _filter_stale_matches(
            _find_matches_cached(
                board,
                allow_square_matches,
                match_scan_cache,
                special_board,
            ),
            origins,
            stale_match_cells,
        )
        matches = _with_auto_explosions(matches, board, origins, auto_explode_tags, False)
        auto_explode_tags = set()
        if not matches:
            break
        cascade_count += 1
        all_matches.extend(matches)
        cascade_matches.append(matches)
        _append_match_intent_events(intent_events, matches, cascade_count)
        extra_moves += _count_extra_move_matches(matches)
        random_refill_tracker = []
        xtra_move_counter = []
        classic_before = _classic_specials(special_board, explode_created_specials_immediately, mode)
        (
            cleared,
            activated,
            created,
            cleared_cell_set,
            cleared_blue,
            cleared_mushrooms,
            cleared_mode_targets,
            cleared_predictable_special,
            color_counts,
        ) = _clear_matches_with_details(
            board,
            special_board,
            matches,
            mode,
            intent_events=intent_events,
            cascade_number=cascade_count,
            random_refill_tracker=random_refill_tracker,
            extra_move_counter=xtra_move_counter,
            active_funky_cells=active_funky_cells,
        )
        if xtra_move_counter and not xtra_extra_move_awarded:
            extra_moves += 1
            xtra_extra_move_awarded = True
        if random_refill_tracker:
            random_refill_after_cascade = cascade_count
        for row, col in cleared_cell_set:
            origins[row][col] = None
        cleared_cells += cleared
        crazy_columns_score += _crazy_columns_cell_score(cleared_cell_set)
        _merge_color_counts(cleared_color_counts, color_counts)
        blue_cells += cleared_blue
        activated_specials += activated
        created_specials += created
        multiplier_mushrooms += cleared_mushrooms
        mode_targets += cleared_mode_targets
        predictable_special_activated = predictable_special_activated or cleared_predictable_special
        _tag_auto_explosions(special_board, origins, classic_before, auto_explode_tags)
        board, special_board, origins = _drop_and_refill(board, special_board, origins, chain_combos=_chain_combo_count(matches))
        chest_drops += _count_new_chest_drops(board, origins, counted_chest_origins)

    return SimulationResult(
        candidate=candidate,
        board=board,
        special_board=special_board,
        matches=all_matches,
        cascade_matches=cascade_matches,
        has_direct_match_layer=False,
        cascade_count=cascade_count,
        cleared_cells=cleared_cells,
        cleared_color_counts=cleared_color_counts,
        blue_cells=blue_cells + _chest_blue(chest_drops),
        wasted_blue_cells=wasted_blue_cells,
        created_specials=created_specials,
        activated_specials=activated_specials,
        extra_moves=extra_moves,
        disco_moves=disco_moves,
        multiplier_mushrooms=multiplier_mushrooms,
        mode_targets=mode_targets,
        chest_drops=chest_drops,
        predictable_special_activated=predictable_special_activated,
        intent_events=intent_events,
        crazy_columns_score=crazy_columns_score,
    )


def high_voltage_effect_cells(
    board: list[list[int]],
    target_color: int,
) -> set[tuple[int, int]]:
    if not _is_high_voltage_color(target_color):
        return set()

    size = len(board)
    effect_cells = {
        (row, col)
        for row, values in enumerate(board)
        for col, value in enumerate(values)
        if value == target_color
    }

    for row, values in enumerate(board):
        cols = [col for col, value in enumerate(values) if value == target_color]
        for start_col, end_col in zip(cols, cols[1:]):
            if all(_is_board_piece(board[row][col]) for col in range(start_col, end_col + 1)):
                effect_cells.update((row, col) for col in range(start_col, end_col + 1))

    for col in range(size):
        rows = [row for row in range(size) if board[row][col] == target_color]
        for start_row, end_row in zip(rows, rows[1:]):
            if all(_is_board_piece(board[row][col]) for row in range(start_row, end_row + 1)):
                effect_cells.update((row, col) for row in range(start_row, end_row + 1))

    return effect_cells


def _high_voltage_target_cell(
    board: list[list[int]],
    special_board: list[list[int]],
    target_color: int,
) -> tuple[int, int] | None:
    cells = [
        (row, col)
        for row, values in enumerate(board)
        for col, value in enumerate(values)
        if value == target_color
    ]
    if not cells:
        return None

    plain_cells = [cell for cell in cells if special_board[cell[0]][cell[1]] == EMPTY]
    candidates = plain_cells or cells
    center = (len(board) - 1) / 2
    return min(
        candidates,
        key=lambda cell: ((cell[0] - center) ** 2 + (cell[1] - center) ** 2, cell[0], cell[1]),
    )


def _identity_origins(board: list[list[int]]) -> list[list[tuple[int, int] | None]]:
    return [
        [(row, col) if value != EMPTY else None for col, value in enumerate(values)]
        for row, values in enumerate(board)
    ]


def _simulate_high_voltage_color(
    original_board: list[list[int]],
    original_special_board: list[list[int]],
    target_color: int,
    max_cascades: int = 40,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
) -> SimulationResult | None:
    target_cell = _high_voltage_target_cell(original_board, original_special_board, target_color)
    if target_cell is None:
        return None

    board = clone_grid(original_board)
    special_board = clone_grid(original_special_board)
    origins = _identity_origins(board)
    active_funky_cells = set(_FUNKY_TILE_CELLS)
    initial_cells = high_voltage_effect_cells(board, target_color)
    if not initial_cells:
        return None

    candidate = MoveCandidate(
        target_cell,
        target_cell,
        Direction.RIGHT,
        clone_grid(original_board),
        clone_grid(original_special_board),
    )

    random_refill_tracker = []
    xtra_move_counter = []
    intent_events: list[dict] = [
        {
            "type": "special_effect",
            "cascade": 1,
            "special": "high_voltage",
            "cell": _intent_cell(target_cell),
            "color": int(target_color),
            "cleared_cells": len(initial_cells),
        },
    ]
    (
        cleared,
        activated,
        cleared_cell_set,
        blue_cells,
        multiplier_mushrooms,
        mode_targets,
        predictable_special_activated,
        cleared_color_counts,
    ) = _clear_cells_with_specials(
        board,
        special_board,
        initial_cells,
        intent_events=intent_events,
        cascade_number=1,
        random_refill_tracker=random_refill_tracker,
        extra_move_counter=xtra_move_counter,
    )
    random_refill_after_cascade = 1 if random_refill_tracker else None
    # NOTHING blue that leaves the board during a High Voltage activation
    # charges the meter -- not the blast's own colour wipe, not a special it
    # detonates, and not the cascade matches that follow the drop. This is
    # stronger than the Brocco disco rule (where cascade matches after the ball
    # DO charge, see _simulate_disco_swap_candidate) and it is measured, not
    # assumed: across every recorded activation that actually fired the meter
    # read 0 immediately afterwards and stayed 0 until the next ordinary move,
    # including cascades that cleared 3, 4, 7 and 13 blue
    # (Debug/runs 2026-08-28 08-19-33 charge_blue=7 over 3 cascades -> 0,
    # 09-48-39 -> 0, 09-49-48 -> 0, 10-02-44 -> 0; the 2026-08-23 15-38..15-45
    # activations behave the same once the repeated pre-click decisions are
    # discounted).
    #
    # So `blue_cells` (charge earned) stays 0 for the whole activation -- which
    # is why the scorer's blue_bonus has always had to be forced to 0 -- and
    # every blue cell the activation removes is booked as a loss: those tiles
    # are off the board, so they cannot charge on a later move either.
    wasted_blue_cells = float(blue_cells)
    blue_cells = 0
    for row, col in cleared_cell_set:
        origins[row][col] = None
    board, special_board, origins = _drop_and_refill(board, special_board, origins)
    counted_chest_origins = set()
    chest_drops = _count_new_chest_drops(board, origins, counted_chest_origins)

    all_matches = []
    cascade_matches = []
    cleared_cells = cleared
    crazy_columns_score = _crazy_columns_cell_score(cleared_cell_set)
    activated_specials = activated
    created_specials = 0
    extra_moves = 1 if xtra_move_counter else 0
    xtra_extra_move_awarded = bool(xtra_move_counter)
    cascade_count = 1 if cleared or activated else 0
    stale_match_cells = _preexisting_match_cell_groups(
        original_board,
        allow_square_matches,
        special_board=original_special_board,
    )

    auto_explode_tags = set()
    for _ in range(max_cascades - 1):
        next_cascade = cascade_count + 1
        if (
            random_refill_after_cascade is not None
            and next_cascade > random_refill_after_cascade
        ):
            break
        matches = _filter_stale_matches(
            find_matches(board, allow_square_matches, special_board),
            origins,
            stale_match_cells,
        )
        matches = _with_auto_explosions(matches, board, origins, auto_explode_tags, False)
        auto_explode_tags = set()
        if not matches:
            break
        cascade_count += 1
        all_matches.extend(matches)
        cascade_matches.append(matches)
        _append_match_intent_events(intent_events, matches, cascade_count)
        extra_moves += _count_extra_move_matches(matches)
        random_refill_tracker = []
        xtra_move_counter = []
        classic_before = _classic_specials(special_board, explode_created_specials_immediately, mode)
        (
            cleared,
            activated,
            created,
            cleared_cell_set,
            cleared_blue,
            cleared_mushrooms,
            cleared_mode_targets,
            cleared_predictable_special,
            color_counts,
        ) = _clear_matches_with_details(
            board,
            special_board,
            matches,
            mode,
            intent_events=intent_events,
            cascade_number=cascade_count,
            random_refill_tracker=random_refill_tracker,
            extra_move_counter=xtra_move_counter,
            active_funky_cells=active_funky_cells,
        )
        if xtra_move_counter and not xtra_extra_move_awarded:
            extra_moves += 1
            xtra_extra_move_awarded = True
        if random_refill_tracker:
            random_refill_after_cascade = cascade_count
        for row, col in cleared_cell_set:
            origins[row][col] = None
        cleared_cells += cleared
        crazy_columns_score += _crazy_columns_cell_score(cleared_cell_set)
        _merge_color_counts(cleared_color_counts, color_counts)
        # Cascade blue is a loss too, not charge -- see the note above.
        wasted_blue_cells += cleared_blue
        activated_specials += activated
        created_specials += created
        multiplier_mushrooms += cleared_mushrooms
        mode_targets += cleared_mode_targets
        predictable_special_activated = predictable_special_activated or cleared_predictable_special
        _tag_auto_explosions(special_board, origins, classic_before, auto_explode_tags)
        board, special_board, origins = _drop_and_refill(board, special_board, origins, chain_combos=_chain_combo_count(matches))
        chest_drops += _count_new_chest_drops(board, origins, counted_chest_origins)

    return SimulationResult(
        candidate=candidate,
        board=board,
        special_board=special_board,
        matches=all_matches,
        cascade_matches=cascade_matches,
        has_direct_match_layer=False,
        cascade_count=cascade_count,
        cleared_cells=cleared_cells,
        cleared_color_counts=cleared_color_counts,
        blue_cells=blue_cells + _chest_blue(chest_drops),
        wasted_blue_cells=wasted_blue_cells,
        created_specials=created_specials,
        activated_specials=activated_specials,
        extra_moves=extra_moves,
        multiplier_mushrooms=multiplier_mushrooms,
        mode_targets=mode_targets,
        chest_drops=chest_drops,
        predictable_special_activated=predictable_special_activated,
        intent_events=intent_events,
        crazy_columns_score=crazy_columns_score,
    )


