def woolly_workout_conversion_cells(
    board: list[list[int]],
    target_color: int,
    special_board: list[list[int]] | None = None,
) -> set[tuple[int, int]]:
    """Cells recolored by the selected Woolly color's four-way workout steps."""
    if not _is_woolly_workout_color(target_color):
        return set()

    sources = {
        (row, col)
        for row, values in enumerate(board)
        for col, value in enumerate(values)
        if value == target_color
    }
    converted = set()
    for row, col in sources:
        for row_delta, col_delta in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            next_row = row + row_delta
            next_col = col + col_delta
            if not (0 <= next_row < len(board)):
                continue
            if not (0 <= next_col < len(board[next_row])):
                continue
            if (
                special_board is not None
                and special_board[next_row][next_col]
                in WOOLLY_WORKOUT_COLOR_PRESERVING_SPECIALS
            ):
                continue
            if _is_board_piece(board[next_row][next_col]):
                converted.add((next_row, next_col))
    return converted - sources


def _simulate_woolly_workout_color(
    original_board: list[list[int]],
    original_special_board: list[list[int]],
    target_color: int,
    max_cascades: int = 40,
    allow_square_matches: bool = False,
    mode: str = "None",
    explode_created_specials_immediately: bool = False,
    allow_conversion_only: bool = False,
) -> tuple[SimulationResult, int] | None:
    target_cell = _high_voltage_target_cell(
        original_board,
        original_special_board,
        target_color,
    )
    if target_cell is None:
        return None

    converted_cells = woolly_workout_conversion_cells(
        original_board,
        target_color,
        special_board=original_special_board,
    )
    if not converted_cells:
        return None

    transformed_board = clone_grid(original_board)
    transformed_special_board = clone_grid(original_special_board)
    for row, col in converted_cells:
        transformed_board[row][col] = target_color

    candidate = MoveCandidate(
        target_cell,
        target_cell,
        Direction.RIGHT,
        transformed_board,
        transformed_special_board,
    )
    stale_match_cells = _preexisting_match_cell_groups(
        original_board,
        allow_square_matches,
        special_board=original_special_board,
    )
    initial_matches = _filter_stale_matches(
        find_matches(
            transformed_board,
            allow_square_matches,
            transformed_special_board,
        ),
        _identity_origins(transformed_board),
        stale_match_cells,
    )
    if not initial_matches:
        if not allow_conversion_only:
            return None
        result = SimulationResult(
            candidate=candidate,
            board=transformed_board,
            special_board=transformed_special_board,
        )
    else:
        result = simulate_candidate(
            candidate,
            max_cascades=max_cascades,
            initial_matches=initial_matches,
            stale_match_cells=stale_match_cells,
            allow_square_matches=allow_square_matches,
            mode=mode,
            explode_created_specials_immediately=explode_created_specials_immediately,
        )
    result.intent_events.insert(
        0,
        {
            "type": "woolly_workout_conversion",
            "target_color": int(target_color),
            "converted_cells": _intent_cells(converted_cells),
        },
    )
    return result, len(converted_cells)


